(window.EH_ROOMS=window.EH_ROOMS||{})["jijin"]={"id": "jijin", "zh": "吉金", "lat": "Late Shang Bronzes", "yrs": "c. 1300 – 1046 BCE", "one": "虎口之下，一张平静的人脸", "wall": "#1A1613", "wallWhy": "墙色取近乎无光的黑褐，像祭祀的地方只剩低处一点火光的时候；青铜要在暗处，才看得出它的光泽。器物本来没有框，本厅不加框：卣用后腿和尾巴立在地上，身下只有一片落影。", "ink": "light", "frame": "none", "art": {"img": "main_cut.webp", "w": 1260, "h": 2215, "who": "佚名商代铸工", "whoLat": "Unknown bronze caster, late Shang period", "title": "《虎食人卣》", "short": "《虎食人卣》", "meta": ["公元前 1100–1050 年，青铜，块范铸造", "高 32.4 cm，长 23.6 cm，宽 23.3 cm", "巴黎，赛努奇博物馆（M.C. 6155）"], "credit": "Wikimedia Commons, File:La Tigresse (vase you 卣), M.C. 6155.jpg — 摄影 Paris Musées / 赛努奇博物馆，CC0"}, "lede": "三千多年前，商代的铸工把一只蹲坐的虎铸成青铜酒器，又在它张开的口下，铸了一张人的脸。", "work": "虎用两条后腿和卷起的尾巴撑地，三点立稳；它的身子就是一件卣（yǒu），一种带提梁的盛酒器。虎头昂起，圆眼，大口张开。前爪搭在一个人的肩上，把他搂在胸前；人的头正好在虎的上颌底下，耳上穿孔，脸却很平静。盖上立着一只有角的小兽，提梁跨过虎的肩背。满身浮起夔龙和兽面，底下再铺一层细密的云雷纹：方折的回旋，一圈套一圈。", "quote": ["远方图物，贡金九牧，铸鼎象物，百物而为之备，使民知神、奸。", "《左传·宣公三年》，王孙满答楚庄王问鼎"], "origin": "商代后期约从公元前 1300 年起，王都在今河南安阳，青铜器主要用来祭祀祖先。长江中游另有自己的青铜传统，爱把整件器做成动物。这件卣的出土经过不明，口传说出自湖南宁乡与安化交界的沩山脚下。赛努奇博物馆认为这一说有其道理：器身黑绿发亮，与湖南出土的铜器相同；兽形的卣，也是那一带的特色。1920 年，它在拍卖会上被赛努奇博物馆买下，至今是馆里最有名的藏品。", "traits": [["是吃，还是护", "人在虎口下，是被吃还是被护，说法不一：一说是献祭；馆方倾向《左传》母虎哺育子文一类的传说；张光直认为人是巫师，虎助他通天。本展不作裁决。"], ["纹样铺满全身", "许多商代晚期的青铜器，主纹高高浮起，是兽面、夔龙、鸟；主纹之间再用细密的云雷纹填满，不留一处空白。近看密不透风，远看只见一双双眼睛。"], ["泥范里铸出来", "先塑泥模，从模上翻出泥范，切成几块取下，在范的内面刻出纹样，入窑焙烧后围着泥芯合拢，再浇进铜液。纹样刻在范上，所以铸出来边角锋利。"], ["吉金：新铜是金色的", "青铜刚铸成时常是金黄色的；古人称铜为“金”，好铜叫“吉金”，东周铭文里常说“择其吉金”。眼前的青绿和黑亮，是三千年锈蚀留下的颜色。"]], "special": {"title": "块范浇铸", "type": "casting", "text": "泥范已经合好。把铜液从浇口倒进去，一直倒到灌满：倒得太快会溢出来，倒得太慢，铜液半路凝住，接不上头。等它冷却，敲开泥范，里面是一件金黄的新铜器。再让时间走过去，看它慢慢锈成今天的青黑，最后和墙上的原作放在一起看。", "hints": {"start": "泥范已合好，拿起坩埚", "pour": "按住，把铜液倒进浇口", "fast": "倒得太快，铜液溢出来了", "slow": "倒得太慢，铜液要凝住了", "full": "灌满了，松手，等它冷却", "cool": "铜在范里冷却", "break": "敲开泥范", "aging": "拖动，让时间走过三千年", "done": "和墙上的原作并排看", "again": "重新合范，再铸一次"}, "captions": {"good": "一次灌满，纹样清清楚楚", "overflow": "铜液冲得太急，溢出浇口，器身留下气孔", "coldShut": "两股铜液没有熔在一起，留下一道冷隔", "short": "没灌满，缺了一块", "new": "刚铸成：金黄色，古人叫它“金”", "aged": "三千年后：青绿与黑亮的锈", "yours": "你铸的", "orig": "原作"}, "timeline": [{"t": 0, "label": "刚出范"}, {"t": 0.35, "label": "几十年"}, {"t": 0.7, "label": "入土"}, {"t": 1, "label": "今天"}], "colors": {"melt": "#F2A640", "newBronze": "#C8A064", "clay": "#8A6A4A", "patinaDark": "#271F16", "patinaGreen": "#64775F", "patinaMid": "#51493C"}, "img": "main_cut.webp", "imgW": 1260, "imgH": 2215, "imgAt": [260, 105], "compareCrop": [880, 560, 640, 900], "note": "colors：melt、newBronze、clay 为示意色；patinaDark/patinaGreen/patinaMid 为 main_cut.webp 不透明像素实测（最暗 20% 中位、偏绿像素中位、全体中位）。compareCrop 为 main.webp 像素 [x,y,w,h]，含虎头、虎口、人面、前爪；img 放在 main 的 imgAt 处。timeline 的 t 为时间滑块 0–1，label 是刻度字。"}, "works": [{"img": "w1.webp", "w": 965, "h": 1200, "who": "佚名商代铸工", "whoLat": "Unknown bronze caster, Shang period", "title": "《鸮尊》", "meta": ["公元前 13–12 世纪，青铜", "31.1 × 18.3 × 21 cm", "明尼阿波利斯美术馆（50.46.116a, b）"], "note": "同是兽形酒器；铸法与长江中游的传统相合。", "credit": "明尼阿波利斯美术馆开放图像, File:mia_7036704.jpg — 摄影 明尼阿波利斯美术馆，公有领域"}, {"img": "w2.webp", "w": 1200, "h": 1168, "who": "佚名商代铸工", "whoLat": "Unknown bronze caster, Shang period", "title": "《饕餮纹鼎》", "meta": ["约公元前 1250–1046 年（安阳期），青铜", "24.5 × 20 cm", "克利夫兰艺术博物馆（1962.281）"], "note": "兽面正对着你：一双大眼，左右对称。", "credit": "克利夫兰艺术博物馆开放获取, File:1962.281_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w3.webp", "w": 900, "h": 1200, "who": "佚名西周铸工", "whoLat": "Unknown bronze caster, Western Zhou period", "title": "《毛公鼎》", "meta": ["西周晚期，公元前 827–782 年，青铜", "通高 53.8 cm，口径 47.0 cm", "台北，国立故宫博物院（中铜 000651）"], "note": "器身几乎素面，腹内铸了五百字铭文。", "credit": "Wikimedia Commons, File:毛公鼎.png — 國立故宮博物院，台北，CC BY 4.0"}, {"img": "w4.webp", "w": 898, "h": 1200, "who": "佚名西周铸工", "whoLat": "Unknown bronze caster, Western Zhou period", "title": "《逨钟》", "meta": ["约公元前 800–700 年，青铜", "70.3 × 37 × 26.6 cm", "克利夫兰艺术博物馆（1989.3）"], "note": "八件一套里的第二大；这类钟一口敲得出两个音。", "credit": "克利夫兰艺术博物馆开放获取, File:1989.3_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}], "chain": "之前：约公元前 1700 年起，中原的二里头已铸出青铜酒器。之后：西周的铜器纹样渐渐简省，铭文越铸越长，要记的是王命和家族的功劳。神兽并没有退场：到了汉代，它们出现在墓中的丝帛上。", "sources": [{"label": "Paris Musées · 虎形卣藏品数据", "claim": "La Tigresse (vase you 卣)，M.C. 6155：Entre -1100 et -1050；Bronze, Fonte au moule；Hunan；高 32.4、长 23.6、宽 23.3 cm，盖高 9.9 cm；1920 年 5 月拍卖购入；CC0 图；Béguin 说明：盛发酵酒；后足与卷尾三点支撑；前爪抱一小人；夔龙等动物纹在方折螺旋地纹上，属商末特征；盖上有角大耳的羊类动物；出土背景不明，口传出自沩山（宁乡、安化交界）；黑绿有光与兽形卣两点使南方来源“说得通”（plausible）；《左传》子文被母虎哺育说；献祭说不能排除", "url": "https://www.parismuseescollections.paris.fr/fr/musee-cernuschi/oeuvres/la-tigresse-vase-you-you"}, {"label": "赛努奇博物馆 · 虎形卣（虎食人卣）", "claim": "馆方中文页：中文名“虎形卣（虎食人卣）”；赛努奇博物馆最有名的文物；南方来源与传说诸说（同上）", "url": "https://www.cernuschi.paris.fr/zh-hans/collections/hu-xing-you-hu-shi-ren-you"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图 4389×5852，Paris Musées 开放图，CC0", "url": "https://commons.wikimedia.org/wiki/File:La_Tigresse_(vase_you_%E5%8D%A3),_M.C._6155.jpg"}, {"label": "大都会艺术博物馆 · 商周：中国的青铜时代", "claim": "块范法：做模、翻泥范、切块取下、焙烧后合范，器物需内芯；纹样直接刻印在范的内面，所以锋利清晰；商代至少到末期只用此法；饕餮以一对眼为主，左右对称；饕餮等纹样在商代社会中的含义至今不明", "url": "https://www.metmuseum.org/essays/shang-and-zhou-dynasties-the-bronze-age-of-china"}, {"label": "大英百科全书 · 商朝", "claim": "商约公元前 1600–1046 年；约公元前 1300 年盘庚以后亦称殷；青铜器多为祭祀祖先的礼器", "url": "https://www.britannica.com/topic/Shang-dynasty"}, {"label": "大英百科全书 · 二里头文化", "claim": "二里头文化已用先进的青铜铸造技术，有约公元前 1700–1500 年的青铜酒器", "url": "https://www.britannica.com/topic/Erlitou-culture"}, {"label": "维基文库 · 《春秋左氏传·宣公》", "claim": "宣公三年王孙满答楚子问鼎：“远方图物，贡金九牧，铸鼎象物，百物而为之备，使民知神、奸”；宣公四年：子文生而被弃于梦中，“虎乳之”，楚人谓虎“於菟”，故名斗谷於菟", "url": "https://zh.wikisource.org/wiki/%E6%98%A5%E7%A7%8B%E5%B7%A6%E6%B0%8F%E5%82%B3/%E5%AE%A3%E5%85%AC"}, {"label": "Kwang-chih Chang · Art, Myth, and Ritual（哈佛大学出版社，1983）", "claim": "张光直：商周青铜器上的动物是巫师通天的助手；虎食人卣中人为巫师、虎为其动物伙伴（第 44 页起“Shamanism and Politics”）", "url": "https://www.fulcrum.org/concern/monographs/44558d53h"}, {"label": "河南博物院 · 一键“青铜”变“吉金”（媒体报道转载）", "claim": "“吉金铸史”特展报道：商周青铜器刚铸成时表面呈金黄色，古人称之为“金”或“吉金”（因果说法为报道口径，墙文只写事实并列）", "url": "https://www.chnmus.net/content/redirect?id=7447474048059052032"}, {"label": "故宫博物院 · 馆藏青铜乐器考释", "claim": "越国其次勾鑃铭文“择其吉金铸句鑃，以享以孝”：东周铭文用“择其吉金”", "url": "https://www.dpm.org.cn/forum_detail/100136.html"}, {"label": "中国国家博物馆 · 青铜器的岁月痕迹：锈蚀背后的故事", "claim": "刚铸出的青铜器常常金光灿灿，古人称之为“金”或“吉金”；用一段时间表面就发乌变暗，潮湿处生绿锈；锈色最常见绿色，也有蓝、红、黑", "url": "https://www.chnmuseum.cn/yj/yjjg/wby/202411/t20241114_270524.shtml"}, {"label": "明尼阿波利斯美术馆 · 鸮尊藏品数据", "claim": "Zun wine vessel in the shape of an owl，13th–12th century BCE，Bronze，31.1 × 18.3 × 21 cm，50.46.116a, b，Public Domain；商代贵族祭祖所用；形制近安阳，铸造技术与长江中游南方传统相合", "url": "https://search.artsmia.org/id/827"}, {"label": "克利夫兰艺术博物馆 · 鼎藏品数据", "claim": "Tripod (Ding)，c. 1250–1046 BCE，Shang dynasty Anyang phase，bronze，24.5 × 20 cm，1962.281，CC0；饕餮兽面是青铜礼器中最有力的符号", "url": "https://www.clevelandart.org/art/1962.281"}, {"label": "国立故宫博物院 · 毛公鼎", "claim": "毛公鼎，西周晚期，西元前 827–782 年，通高 53.8、腹深 27.2、口径 47.0 cm，中铜 000651；器身光素，仅口沿下重环纹与凸弦纹；器内铭文五百字，迄今最长；铭文中有“秬鬯一卣”；图像标示“國立故宮博物院，台北，CC BY 4.0”", "url": "https://digitalarchive.npm.gov.tw/Antique/Content?uid=1438&Dept=U"}, {"label": "维基共享资源 · 毛公鼎图片文件页", "claim": "毛公鼎.png 2122×2829，来源国立故宫博物院开放资料，CC BY 4.0", "url": "https://commons.wikimedia.org/wiki/File:%E6%AF%9B%E5%85%AC%E9%BC%8E.png"}, {"label": "克利夫兰艺术博物馆 · 逨钟藏品数据", "claim": "Bell (Lai Zhong)，c. 800–700 BCE，陕西眉县，西周，bronze，70.3 × 37 × 26.6 cm，1989.3，CC0；八件一套中第二大；铭文 118 字", "url": "https://www.clevelandart.org/art/1989.3"}, {"label": "史密森尼国立亚洲艺术博物馆 · 青铜时代的音乐", "claim": "周代的钟从下面看是杏仁形（合瓦形），敲正中和敲近边处发出两个不同的音", "url": "https://asia-archive.si.edu/learn/for-educators/teaching-china-with-the-smithsonian/lesson-plans/music-in-the-bronze-age/"}]};

