(window.EH_ROOMS=window.EH_ROOMS||{})["bohua"]={"id": "bohua", "zh": "帛画", "lat": "State of Chu", "yrs": "475 – 221 BCE", "one": "人站上龙背，像要往天上去", "wall": "#1B1411", "wallWhy": "墙色取楚国漆器的黑漆：楚地多漆器，作品栏里的鼓架便是黑漆底上画朱纹。这幅帛画本是能挂起来的幡，原物没有装裱，所以本厅不加框，也不仿造装裱，照原样挂在它自己的竹竿上。", "ink": "light", "frame": "none", "art": {"img": "cut/main_cut.webp", "w": 1759, "h": 2400, "who": "佚名楚国画工", "whoLat": "Unknown Chu painter", "title": "《人物御龙帛画》", "short": "《人物御龙帛画》", "meta": ["战国中晚期，绢本墨绘", "37.5 × 28 cm", "长沙，湖南博物院"], "credit": "Wikimedia Commons, File:Figure Driving a Dragon - Google Art Project.jpg — 摄影 湖南博物院（Google 艺术与文化），公有领域"}, "lede": "大约两千三百年前，楚国一位画工在一块如今呈深褐色的绢上画了一个人：他站在一条龙上，手里牵着缰绳。", "work": "从下往上看。最下面一条鲤鱼，和龙一同朝左；龙昂着头，身子弯成一只船，尾巴翘起，尾上立着一只鹤（一说是凤）。一个男子侧身站在龙背上，高冠长袍，腰佩长剑，牵着缰绳。头顶一顶华盖。冠缨和华盖的垂穗都向后飘，像龙舟正迎着风往前走。全画以墨线勾成，局部平涂，几处用了金粉、白粉。帛的上端缠着细竹，系着丝绳。", "quote": ["为余驾飞龙兮，杂瑶象以为车。何离心之可同兮，吾将远逝以自疏。", "《离骚》，传为战国楚人屈原作"], "origin": "这幅画出自楚国的墓。湖南博物院说，楚人相信灵魂可以四处游荡，也可以归天为神，这类“魂幡”源自楚地为死者招魂的习俗。长沙子弹库一号墓在 1942 年被盗掘，墓中的帛书流散海外（2025 年已有两卷归国）；1973 年重新发掘，才在椁盖板与外棺之间的隔板上找到这幅画，平放着。1949 年，长沙陈家大山楚墓出过另一幅《人物龙凤帛画》，两幅常被并称为先秦绘画的双璧。", "traits": [["引魂升天", "大多数学者认为，这是一幅“引魂升天”图：画中男子当为墓主，驾着龙往天上去，华盖表明他身份尊贵，鱼和鹤一路相随。"], ["以线为骨", "画几乎全靠墨线：脸部的线细而准，衣袍的线长而舒展，颜色只在局部平涂。一般认为，中国画用线造型的路子，在楚国帛画上已经看得清楚。"], ["楚辞里的人", "《涉江》（传为屈原作）自述“带长铗之陆离兮，冠切云之崔嵬”：佩长剑，戴高冠。有研究者拿画中男子对照楚辞里这种乘龙远行的形象。"], ["人驾驭神兽", "上一厅的卣上，人在虎口之下，被虎抱着；这里，人站在龙背上，手握缰绳。两件相隔七八百年，本展不说谁影响了谁；并排看，人和神兽的位置换了过来。"]], "special": {"title": "风中举幡", "type": "banner", "text": "这块帛本来就挂在一根细竹上。按住竹竿往上送，松开让它荡回；跟着它回落的节奏再送，一下一下把幡举高，帛就在风里飘起来。节奏乱了，幡会落下。这幅画在葬仪上具体怎么用，已难确知；这里只让你感受一面幡在风里的样子。", "hints": {"start": "按住竹竿，往上送", "release": "松开，让它荡回来", "rhythm": "等它回落，再送一次", "early": "送早了，它还在往上走", "late": "送晚了，它已经落下去了", "good": "节奏对了，幡又高了一截", "high": "幡在风里飘起来了", "fall": "节奏乱了，幡落了下来", "again": "再举一次"}, "captions": {"height": "高度", "best": "最高", "wind": "风从左边来", "orig": "原画", "origNote": "冠缨和华盖的垂穗都向右后飘：画里的风也从左前方来，龙舟迎着风走"}, "layers": {"silk": {"img": "cut/silk.webp", "x": 0, "y": 26, "w": 1759, "h": 2374}, "rod": {"img": "cut/rod.webp", "x": 0, "y": 0, "w": 1759, "h": 26}, "shadow": {"img": "cut/shadow.webp", "x": -80, "y": -80, "w": 1919, "h": 2560}}, "rodEnds": [[7, 13], [1753, 13]], "silkBox": [28, 26, 1736, 2400], "hatRibbons": [1045, 760, 1240, 808], "canopyRibbons": [[300, 410, 490, 500], [860, 360, 1130, 485], [1500, 440, 1705, 565]], "windFrom": "left", "realSize": [28, 37.5], "note": "坐标为 main.webp 像素（1759×2400）；silk、rod 分层来自 cut/layers.json，先画 silk 再画 rod；rodEnds 为竹竿两端中心；realSize 为原件宽×高（cm）。风向按画中冠缨与华盖垂穗读出：向右后飘，风从左来"}, "works": [{"img": "w1.webp", "w": 925, "h": 1200, "who": "佚名楚国画工", "whoLat": "Unknown Chu painter", "title": "《人物龙凤帛画》", "meta": ["战国中期晚段，帛画", "31 × 22.5 cm", "长沙，湖南博物院"], "note": "也出自长沙楚墓：妇人合掌而立，凤在上方，龙在身前。", "credit": "Wikimedia Commons, File:Figure with Dragon and Phoenix - Google Art Project.jpg — 摄影 湖南博物院（Google 艺术与文化），公有领域"}, {"img": "w2.webp", "w": 490, "h": 1200, "who": "佚名西汉画工", "whoLat": "Unknown Western Han painter", "title": "《马王堆 T 形帛画》", "meta": ["西汉，公元前 2 世纪，绢本设色", "长 205 cm，上宽 92 cm，下宽 47.7 cm", "长沙，湖南博物院"], "note": "晚一百多年：天上、人间、地下画在同一幅上。", "credit": "Wikimedia Commons, File:T-shaped Painting on Silk - Google Art Project.jpg — 摄影 湖南博物院（Google 艺术与文化），公有领域"}, {"img": "w3.webp", "w": 1027, "h": 1200, "who": "佚名楚国漆工", "whoLat": "Unknown Chu lacquer artisan", "title": "《蛇座凤鸟鼓架》", "meta": ["战国，公元前 475–221 年，木胎漆绘", "132.1 × 124.5 cm", "克利夫兰，克利夫兰艺术博物馆（1938.9）"], "note": "两只长颈鸟踏在盘蛇上，据说出自长沙。", "credit": "克利夫兰艺术博物馆开放获取, File:1938.9_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w4.webp", "w": 1200, "h": 1162, "who": "佚名铸镜工", "whoLat": "Unknown bronze caster", "title": "《四神博局镜》", "meta": ["公元 9–100 年，青铜", "直径 19 cm", "克利夫兰，克利夫兰艺术博物馆（1995.301）"], "note": "镜背是一幅宇宙图：龙守东方，虎守西方。", "credit": "克利夫兰艺术博物馆开放获取, File:1995.301_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}], "chain": "之前：上一厅的商代铜器上，神兽是主角。之后：西汉马王堆的 T 形帛画把天上、人间、地下画进一幅，一般认为墓主同样往天上去；汉代又把天、地和守四方的神兽铸在铜镜背面。下一厅，回到人间。", "sources": [{"label": "湖南博物院 · 战国人物御龙帛画", "claim": "人物御龙帛画：战国（前475—前221年），长 37.5、宽 28 厘米；1973 年长沙子弹库 1 号墓出土，出土时平放在椁盖板与外棺中间的隔板上；头戴高冠、身穿博袍、腰佩长剑的男子当为墓主人，侧身立于龙身，头顶华盖；龙昂首卷尾、弓身成舟，舟尾立鹤（凤），舟旁鲤鱼随行；面部线条精微、服饰线条流畅；魂幡，大多数学者认为是“导引灵魂升天”图", "url": "https://www.hnmuseum.com/zh-hans/zuixintuijie/%E6%88%98%E5%9B%BD%E4%BA%BA%E7%89%A9%E5%BE%A1%E9%BE%99%E5%B8%9B%E7%94%BB"}, {"label": "湖南博物院 · 展品欣赏：人物御龙帛画", "claim": "“魂幡”，平放于椁盖板与外棺中间隔板上；人物衣着飘带、华盖垂穗表示风动方向，龙舟迎风前进；大多数学者认为是“引魂升天”图；楚地迷信灵魂可四处游荡、也可归天为神，魂幡源自楚地为死者招魂的习俗；与《人物龙凤帛画》并称先秦绘画双璧", "url": "https://www.hnmuseum.com/gallery/node/31/27"}, {"label": "湖南博物院 · Figure Driving a Dragon, Ink on Silk", "claim": "英文馆方页：Warring States period (475–221 BC)，Ink on silk，Height 37.5 cm，Width 28 cm，1973 年出土于长沙子弹库楚墓；有须男子侧身、戴冠佩剑、执缰驭龙，龙身如舟，龙尾立白鹭（heron），上有华盖三条飘带", "url": "https://www.hnmuseum.com/en/zuixintuijie/figure-driving-dragon-ink-silk"}, {"label": "美术报 · 人物御龙帛画（赵启斌、朱同）", "claim": "帛画上端有竹轴，轴上有丝绳，可垂直悬挂；基本用白描，局部平涂，部分用金白粉彩；1973 年出土于长沙子弹库楚墓一号墓；战国晚期（馆方作战国中晚期）", "url": "http://msb.zjol.com.cn/html/2015-07/04/content_3092717.htm?div=-1"}, {"label": "中文维基百科 · 人物御龙帛画", "claim": "战国中晚期；深褐色平纹绢；长 37.5、宽 28 厘米；与屈原“带长铗之陆离兮，冠切云之崔嵬”的意象相呼应；2002 年列入首批禁止出国（境）展览文物", "url": "https://zh.wikipedia.org/zh-hans/%E4%BA%BA%E7%89%A9%E5%BE%A1%E9%BE%99%E5%B8%9B%E7%94%BB"}, {"label": "英文维基百科 · Silk painting depicting a man riding a dragon", "claim": "1973 年子弹库一号墓出土，37.5 × 28 cm；深褐色绢；龙身如舟，尾立鹭，鲤鱼在下，华盖示身份", "url": "https://en.wikipedia.org/wiki/Silk_painting_depicting_a_man_riding_a_dragon"}, {"label": "湖南省文物局 · 长沙子弹库战国帛书“回家”", "claim": "子弹库帛书 1942 年出土于长沙子弹库楚墓，流失海外 79 载；分《四时令》《五行令》《攻守占》三卷；墓中出土《人物御龙帛画》", "url": "https://wwj.hunan.gov.cn/wwj/c100310/c100313/202510/t20251014_33824866.html"}, {"label": "新华网 · 子弹库战国帛书正式入藏湖南省博物馆", "claim": "子弹库帛书“于 1942 年在湖南长沙子弹库楚墓遭盗掘出土”", "url": "https://www.news.cn/culture/20251014/7e69268d45ae4497bd2da1e5dae56cfb/c.html?page=7"}, {"label": "长沙新闻网 · 长沙子弹库帛书：跨越79载的坎坷回家路", "claim": "1942 年土夫子盗掘子弹库楚墓得帛书；1973 年 5 月湖南重启子弹库楚墓发掘，出土《人物御龙帛画》；一椁二棺，墓主推测为士大夫一级贵族，约 40 岁；2025 年 5 月美国史密森学会返还子弹库帛书第二、三卷《五行令》《攻守占》，第一卷《四时令》仍在追索", "url": "https://news.changsha.cn/xctt/html/110186/20250518/200649.shtml"}, {"label": "维基文库 · 离骚", "claim": "“為余駕飛龍兮，雜瑤象以為車。何離心之可同兮，吾將遠逝以自疏。”（通行本，简体转写）", "url": "https://zh.wikisource.org/wiki/%E9%9B%A2%E9%A8%B7"}, {"label": "维基文库 · 楚辞·九章（涉江）", "claim": "《涉江》：“帶長鋏之陸離兮，冠切雲之崔嵬。”", "url": "https://zh.wikisource.org/wiki/%E6%A5%9A%E8%BE%AD/%E4%B9%9D%E7%AB%A0"}, {"label": "维基共享资源 · 主图文件页", "claim": "Figure Driving a Dragon - Google Art Project.jpg，3384×4512，湖南博物院经 Google Arts & Culture 提供，公有领域", "url": "https://commons.wikimedia.org/wiki/File:Figure_Driving_a_Dragon_-_Google_Art_Project.jpg"}, {"label": "Google 艺术与文化 · 湖南博物院：人物御龙帛画", "claim": "Figure Driving a Dragon，Hunan Provincial Museum 提供（asset SAFcDilMMbW6pA，即 Commons 主图文件的来源）", "url": "https://artsandculture.google.com/asset/SAFcDilMMbW6pA"}, {"label": "湖南博物院 · 人物龙凤帛画", "claim": "战国中期晚段，纵 31、横 22.5 厘米，1949 年 2 月出土于长沙陈家大山楚墓；高髻妇人侧身合掌，上有凤鸟、左有龙；楚人丧葬仪式中的魂幡", "url": "https://www.hnmuseum.com/zh-hans/zuixintuijie/%E4%BA%BA%E7%89%A9%E9%BE%99%E5%87%A4%E5%B8%9B%E7%94%BB"}, {"label": "维基共享资源 · 人物龙凤帛画图片文件页", "claim": "Figure with Dragon and Phoenix - Google Art Project.jpg，湖南博物院经 Google Arts & Culture，公有领域", "url": "https://commons.wikimedia.org/wiki/File:Figure_with_Dragon_and_Phoenix_-_Google_Art_Project.jpg"}, {"label": "湖南博物院 · 马王堆一号汉墓 T 形帛画", "claim": "长约 205 厘米，上宽 92、下宽 47.7 厘米；1972 年出土，覆盖在一号墓内棺上；分天上、人间、地下三部分；招魂之幡", "url": "https://www.hnmuseum.com/zh-hans/zuixintuijie/%E9%A9%AC%E7%8E%8B%E5%A0%86%E4%B8%80%E5%8F%B7%E6%B1%89%E5%A2%93t%E5%BD%A2%E5%B8%9B%E7%94%BB"}, {"label": "中文维基百科 · 马王堆一号汉墓帛画", "claim": "西汉初期，一号墓墓主为长沙国丞相利苍之妻（三号墓纪年公元前 168 年），帛画绢本设色", "url": "https://zh.wikipedia.org/zh-hans/%E9%A9%AC%E7%8E%8B%E5%A0%86%E4%B8%80%E5%8F%B7%E6%B1%89%E5%A2%93%E5%B8%9B%E7%94%BB"}, {"label": "维基共享资源 · T 形帛画图片文件页", "claim": "T-shaped Painting on Silk - Google Art Project.jpg，湖南博物院经 Google Arts & Culture，公有领域（作品栏图裁去四周黑边）", "url": "https://commons.wikimedia.org/wiki/File:T-shaped_Painting_on_Silk_-_Google_Art_Project.jpg"}, {"label": "克利夫兰艺术博物馆 · Cranes and Serpents", "claim": "蛇座凤鸟鼓架（馆方中文名“蛇座鳳鳥鼓架”），475–221 BCE，战国·楚，reportedly from Changsha，lacquered wood with polychromy，132.1 × 124.5 cm，1938.9，CC0；黑漆底上以红漆、黄色颜料绘纹；馆方说“probably a drum stand”，鸟为鹤（cranes）", "url": "https://www.clevelandart.org/art/1938.9"}, {"label": "克利夫兰艺术博物馆 · TLV Mirror with Four Spirits and Companions", "claim": "四神博局式青铜镜，9–100 CE，bronze，直径 19 cm，1995.301，CC0；镜背为宇宙图：圆圈与云纹带表天、方框表地，四方神兽：虎守西、龙守东、朱雀南、蛇绕龟北；馆方记铭文为十二辰（zodiac series），未记升仙铭", "url": "https://www.clevelandart.org/art/1995.301"}]};

