(window.EH_ROOMS=window.EH_ROOMS||{})["shuochang"]={"id": "shuochang", "zh": "说唱俑", "lat": "Eastern Han", "yrs": "25 – 220 CE", "one": "墓里一盏灯，照见他还在说笑", "wall": "#1B1411", "wallWhy": "墙色取汉代漆器的黑：这件俑原本立在不见天日的墓室里。器物本来没有框，本厅不加框。原件不大，比真人小得多。", "ink": "light", "frame": "none", "art": {"img": "cut/main_cut.webp", "w": 1715, "h": 2181, "who": "佚名东汉陶工", "whoLat": "Unknown Eastern Han potter", "title": "《击鼓说唱俑》（明器）", "short": "《击鼓说唱俑》", "meta": ["东汉，1–2 世纪，陶", "60.33 × 43.18 × 40.01 cm", "明尼阿波利斯美术馆（2003.101）"], "credit": "明尼阿波利斯美术馆开放图像, File:mia_35290a.jpg — 摄影 明尼阿波利斯美术馆，公有领域"}, "lede": "东汉时，有人把一个说唱艺人的陶像放进墓里：让他在地下接着击鼓说笑，给墓主人解闷。", "work": "他蹲坐着，右腿向外平平踢出，脚尖朝天，左脚赤着踩在座上。左臂夹紧一面扁圆的鼓，把左肩顶得高高耸起；右手举着鼓槌，正要敲下去。上身光着，肚子圆滚滚地挺出来。全身最用力的是那张脸：嘴咧开大笑，双眼眯成两道缝，额头挤出一道道皱纹，像正说到最逗的地方。这一刻定在陶土里，近两千年没有散。", "quote": ["事死如事生，事亡如事存，孝之至也。", "《礼记·中庸》"], "origin": "汉代把这类艺人叫俳优（pái yōu）：说笑话，击鼓唱歌，常陪在主人身边即兴表演。皇室、贵族、富户多爱蓄养俳优，司马迁在《史记》里专为几位滑稽人物写了《滑稽列传》。东汉（25–220 年）时，四川一带墓里放这类逗笑艺人俑的风气特别盛，一座墓有时放进整整一班艺人。那里常凿山为墓，称崖墓；说唱、吹笛、抚琴、起舞的陶俑，不少出自这样的墓。", "traits": [["事死如事生", "学者认为，汉人把死后看作生前的延续。墓修得像住宅，放进陶制的房屋、牲畜、仆从和乐舞艺人，统称明器：生前有的，地下也要有。"], ["模子里出来的生气", "汉墓陶俑大多用模具成批制作，却做得很活：舞者停在半步，鼓手随着节拍晃动。成批出窑的东西，神气一点不减。"], ["不照比例，照神气", "头大、腿短、肚子挺出，比例并不写实。有研究者认为俳优多由身材矮小的人担任，也有人认为是有意夸张。本展不作裁决。"], ["满墙都在动", "汉墓的画像石、画像砖上常刻乐舞百戏：抛丸、弄剑、倒立，旁边常有赤膊、矮胖的滑稽艺人。汉代艺术偏爱人在动的那一刻。"]], "special": {"title": "跟他打鼓", "type": "drum", "text": "他腋下夹着一面扁鼓。跟着节拍拍这面鼓：拍准了，他说得越来越快、越来越欢；拍乱了，他就停下来等你。节拍是本展设的，不是复原：汉代说唱的鼓点，没有留下记录。", "hints": {"start": "跟着节拍，拍他腋下的鼓", "listen": "先听两小节，再跟上", "good": "拍准了", "early": "早了一点", "late": "晚了一点", "faster": "他越说越快了", "stop": "拍子乱了，他停下来等你", "resume": "再跟上节拍，他接着说", "again": "从头再来一段"}, "captions": {"level": ["慢慢说开了", "说到兴头上", "满堂大笑"], "stats": "跟准了 {n} 拍", "best": "最快跟到每分钟 {bpm} 拍", "end": "这一段说完了"}, "img": "main.webp", "imgW": 2099, "imgH": 2400, "drum": {"c": [1530, 1015], "box": [1400, 830, 260, 370]}, "face": {"c": [1050, 540], "box": [890, 290, 360, 490]}, "stickEnd": [800, 462], "bpm": [84, 96, 108, 120, 132], "pattern": [1, 0, 1, 1, 1, 0, 1, 0], "note": "坐标为 main.webp 像素（左上原点）；drum/face 的 box 为 [x,y,w,h]。bpm 为每一级的速度，pattern 为一小节 8 个八分音符位置上该不该拍（1=拍），均为本展设定，不是复原。俑本身不做任何变形或动画：只动光与声。"}, "works": [{"img": "w1.webp", "w": 935, "h": 1200, "who": "佚名东汉陶工", "whoLat": "Unknown Eastern Han potter", "title": "《彩绘陶乐舞俑》", "meta": ["东汉，2 世纪，陶，有彩绘残迹", "高 60 cm", "克利夫兰艺术博物馆（2023.98）"], "note": "四川东汉的女艺人：一手扬袖，一手提裙，裙下像藏着鼓。", "credit": "克利夫兰艺术博物馆开放获取, File:2023.98_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w2.webp", "w": 928, "h": 1200, "who": "佚名东汉陶工", "whoLat": "Unknown Eastern Han potter", "title": "《陶马》", "meta": ["东汉，1–3 世纪，陶，有颜料残迹", "106.68 × 92.71 × 29.21 cm", "明尼阿波利斯美术馆（98.19）"], "note": "抬起前腿，昂首拱颈，在地下为墓主人撑起排场。", "credit": "明尼阿波利斯美术馆开放图像, File:PCD19981204_4467_IMG0028.jpg — 摄影 明尼阿波利斯美术馆，公有领域"}, {"img": "w3.webp", "w": 1190, "h": 1200, "who": "佚名西汉铜匠", "whoLat": "Unknown Western Han bronzesmith", "title": "《博山炉》", "meta": ["西汉，公元前 1 世纪，青铜", "18.7 × 20.3 × 20.3 cm", "明尼阿波利斯美术馆（2001.5.3a, b）"], "note": "炉盖铸成群峰，兽与骑手出没其间，象征仙山。", "credit": "明尼阿波利斯美术馆开放图像, File:mia_6028100.jpg — 摄影 明尼阿波利斯美术馆，公有领域"}, {"img": "w4.webp", "w": 1200, "h": 1142, "who": "佚名东汉铸镜工", "whoLat": "Unknown Eastern Han mirror caster", "title": "《画像镜》", "meta": ["东汉，2 世纪，青铜", "直径 19.5 cm", "克利夫兰艺术博物馆（1995.331）"], "note": "镜背高浮雕神人与吴越君臣，讲吴越相争的旧事。", "credit": "克利夫兰艺术博物馆开放获取, File:1995.331_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}], "chain": "之前：战国楚墓里的帛画随葬入墓，一般认为画的是墓主人乘龙升天。之后：陶俑随葬一路延续到隋唐，唐墓的三彩俑更加华丽。研究者多把汉代俳优看作后世说唱、戏曲的远源之一。下一厅离开墓室，回到活人的书案。", "sources": [{"label": "明尼阿波利斯美术馆 · 击鼓说唱俑藏品数据", "claim": "主作品：Figure of a Squatting Drummer，Eastern Han dynasty (25–220 CE)，1st–2nd century，Earthenware，60.33 × 43.18 × 40.01 cm，2003.101，Public Domain，图像 mia_35290a.jpg 3366×3849；馆方说明：东汉四川尤流行滑稽艺人俑，作随葬俑在死后供娱乐，一座墓可放整班艺人；鼓手擅半说半唱的说唱；此俑欢唱、额头笑出皱纹，身形粗重或为侏儒；相似身形的艺人见于汉墓杂技画像砖；汉墓陶俑成批制作", "url": "https://search.artsmia.org/id/72222"}, {"label": "明尼阿波利斯美术馆 · 击鼓说唱俑藏品页", "claim": "同上，馆方网页", "url": "https://collections.artsmia.org/art/72222"}, {"label": "大都会艺术博物馆 · 早期中国墓葬中的明器", "claim": "时人把死后看作生前的延续，随葬小像称明器（spirit goods），盛行于汉代并延续到隋唐；汉代陶明器大多用模具成批制作，却十分生动：舞者停在半步，鼓手随节奏摆动", "url": "https://www.metmuseum.org/essays/the-vibrant-role-of-mingqi-in-early-chinese-burials"}, {"label": "中国国家博物馆 · 击鼓说唱俑", "claim": "汉代俳优以调谑、滑稽、讽刺的表演为主，常随侍主人左右即兴表演，表演时一般边击鼓边歌唱；皇室贵族、豪富大吏蓄养俳优之风甚盛；汉代画像石乐舞百戏图中常见身材粗短、上身赤裸、动作滑稽的表演者", "url": "https://www.chnmuseum.cn/portals/0/web/zt/202112jgscy/"}, {"label": "方志四川（澎湃新闻）· 俳优的欢乐颂", "claim": "崖墓是汉代流行于岷江流域、凿山为室的墓葬形式；四川、重庆、贵州出土说唱、吹笛、抚琴、舞俑，成都最多，多属东汉晚期和三国；《史记》专立《滑稽列传》；俳优多为侏儒（王国维“古之优人，其始皆以侏儒为之”），俑的变形可能兼有写实与写意；研究者普遍认为俳优对后世说唱、戏曲、话本的兴起起过重要作用（四川省地方志工作办公室供稿）", "url": "https://www.thepaper.cn/newsDetail_forward_23604264"}, {"label": "成都博物馆 · 画像砖：小空间里的大世界", "claim": "东汉杂技盘舞画像砖（成都博物馆藏）：一人在层叠案几上倒立反弓，一人跳丸，一人踏盘鼓而舞；画像砖多表现宴饮、乐舞、百戏", "url": "https://cdmuseum.com/xinwen/202204/2711.html"}, {"label": "新浪收藏 · 四川汉代陶俑", "claim": "汉代盛行“事死如事生”的厚葬之风，墓中有歌舞说唱俑、武士俑、庖厨俑、动物俑及楼阁院落等；《盐铁论·散不足》记民间丧事“歌舞俳优，连笑伎戏”", "url": "http://collection.sina.com.cn/yhds/20120831/161982553.shtml"}, {"label": "维基文库 · 礼记·中庸", "claim": "“践其位，行其礼，奏其乐，敬其所尊，爱其所亲，事死如事生，事亡如事存，孝之至也。”", "url": "https://zh.wikisource.org/wiki/%E7%A6%AE%E8%A8%98/%E4%B8%AD%E5%BA%B8"}, {"label": "克利夫兰艺术博物馆 · 彩绘陶乐舞俑", "claim": "Female Figure of a Court Entertainer Dancing（漢 彩繪陶樂舞俑），100s CE，China, Sichuan province, Eastern Han dynasty，Pottery with traces of color pigment，60 cm，2023.98，CC0；馆方说明：一手执宽袖扬起，一手提裙，裙下似有一鼓；汉代贵族墓放入侍从、乐人塑像以示身份", "url": "https://www.clevelandart.org/art/2023.98"}, {"label": "明尼阿波利斯美术馆 · 陶马藏品数据", "claim": "Prancing Horse，Eastern Han dynasty (25–220 CE)，1st–3rd century，Earthenware with traces of pigment，106.68 × 92.71 × 29.21 cm，98.19，Public Domain；馆方说明：抬起前腿、拱颈，随葬以彰显墓主身份与排场", "url": "https://search.artsmia.org/id/5623"}, {"label": "明尼阿波利斯美术馆 · 博山炉藏品数据", "claim": "Boshanlu hill censer，Western Han dynasty, 206 BCE–9 CE，1st century BCE，Bronze，18.7 × 20.3 × 20.3 cm，2001.5.3a,b，Public Domain；馆方说明：炉盖为群峰，有野兽与骑手，象征通往仙界的圣山，用于随葬", "url": "https://search.artsmia.org/id/6155"}, {"label": "克利夫兰艺术博物馆 · 画像镜", "claim": "Mirror with Deities and Kings（畫像鏡），100s CE，Eastern Han dynasty，bronze，直径 19.5 cm，1995.331，CC0；馆方说明：饰吴越两国历史人物，讲吴越相争（吴亡于公元前 473 年），绍兴为汉代铸镜中心", "url": "https://www.clevelandart.org/art/1995.331"}]};

;
(window.EH_ROOMS=window.EH_ROOMS||{})["lanting"]={"id": "lanting", "zh": "兰亭", "lat": "Eastern Jin", "yrs": "317 – 420 CE", "one": "像是边写边改，字成了一个人的心迹", "wall": "#3E443C", "wallWhy": "墙色取竹林的灰青：兰亭序里写那天“茂林修竹”，魏晋名士也爱在竹林里清谈。灰青压深了一档，让中间调的纸色和浅色文字都立得住。这卷是手卷，本来平放在案上从右往左展开看，所以本厅不加框，也不仿造它的装裱，照原样横陈。", "ink": "light", "frame": "none", "art": {"img": "main.webp", "w": 2400, "h": 834, "who": "王羲之", "whoLat": "Wang Xizhi, c. 303 – 361 (or 321 – 379)", "title": "《兰亭序》（神龙本）", "short": "《兰亭序》", "meta": ["唐摹本（原作 353 年），纸本行书", "24.5 × 69.9 cm", "北京，故宫博物院（故00002597）"], "credit": "Wikimedia Commons, File:Lanting Xu by Feng Chengsu.jpg — 上传者 Joanhappy3000，CC BY-SA 4.0"}, "lede": "东晋永和九年（353）三月初三，王羲之和四十多位友人在会稽山阴的兰亭聚会，饮酒作诗，他为这些诗写了一篇序。", "work": "本幅二十八行、三百二十四字，行书，由两张纸接成，前纸 13 行，后纸 15 行。字与字之间常有一丝细墨牵连，字的大小、笔画的轻重随手变化，一行一行向左走。全篇有二十来个“之”字，写法各不相同。卷上留着涂改：第四行右侧添了“崇山”两个小字，后面有一处整块涂黑，还有几个字是在原字上改写的，像是写字的人一边写一边改。", "quote": ["写《乐毅》则情多怫郁；书《画赞》则意涉瑰奇；《黄庭经》则怡怿虚无；《太史箴》又纵横争折；暨乎《兰亭》兴集，思逸神超。", "孙过庭《书谱》，唐垂拱三年（687）"], "origin": "那天与会的人把诗汇成一集，王羲之作序。唐人何延之《兰亭始末记》说：原迹在王家传到七世孙智永；唐太宗派萧翼从智永的弟子辩才手里设计取得，命冯承素等四人各拓数本，赐给皇太子和近臣；太宗死后，原迹随他葬入昭陵。这是传统说法，原迹至今没有下落。眼前这卷卷首有唐中宗“神龙”年号的半方小印，称“神龙本”；明人题记说它是冯承素所摹。故宫认为半印是后人所添，冯承素之名也不可信，但它仍是唐以来流传有绪的古摹本。", "traits": [["晋尚韵", "清人梁巘《评书帖》说：“晋尚韵，唐尚法，宋尚意。”晋人的字不摆森严的法度，笔势连绵，轻松随意，像是不费力气，看的是通篇的气息与风神。"], ["人的觉醒", "李泽厚在《美的历程》里把汉末魏晋称作“人的觉醒”的时代：外在的节操让位于内在的精神。字也不只是器物、碑石上的铭文，更成了一个人的心迹。"], ["信札里的好字", "晋代留下来的名家墨迹，多是写给亲友的短信：问病、报平安、道一声雪后安好。随手写成，不为给人看，反倒最见性情。作品栏的四件都是这样的尺牍。"], ["靠摹本传世", "一般认为王羲之的真迹已经不存，今天看到的是唐人照原迹精摹的本子和据此刻石的拓本。精摹常用“双钩廓填”：先勾出字的轮廓，再在里面填墨。"]], "special": {"title": "曲水流觞", "type": "wine_cup", "text": "序里写的“流觞曲水”，是让盛了酒的杯子从上游顺着弯曲的溪水漂下，停在谁面前，谁就饮酒赋诗。传统说法里，那天四十二人中，十一人各成四言、五言诗一首，十五人各成一首，十六人作不出，各罚酒三觥。这里的诗句都出自他们留下的《兰亭诗》。杯子照马王堆汉墓的“君幸酒”漆耳杯画，比兰亭早约五百年。", "hints": {"start": "拖动水面，让溪水推着杯子走", "drift": "杯子顺水漂下去了", "bank": "碰到岸边，打了个转", "fast": "水推得太猛了", "capsize": "杯子翻了，酒洒进溪里", "reset": "再放一只杯子", "stop": "杯子停在{name}面前", "poem": "{name}作得一首{form}诗", "fine": "{name}作不出，罚酒三觥", "again": "让杯子再漂下去"}, "captions": {"tally": "今天：成诗 {poems} 人，罚酒 {fines} 人", "history": "传统说法：四十二人，二十六人成诗，十六人罚酒", "source": "诗句出自《兰亭诗》，据宋孔延之编《会稽掇英总集》卷三", "cup": "耳杯，照马王堆“君幸酒”漆耳杯", "form4": "四言", "form5": "五言", "upstream": "上游", "downstream": "下游"}, "guests": [{"name": "王羲之", "note": "会稽内史，这篇序的作者", "form": "五言", "line": ["仰视碧天际，", "俯瞰渌水滨。"], "bank": "right"}, {"name": "谢安", "note": "", "form": "五言", "line": ["相与欣嘉节，", "率尔同褰裳。"], "bank": "left"}, {"name": "王献之", "note": "王羲之之子，这年约十岁", "fine": true, "bank": "right"}, {"name": "孙绰", "note": "为诗集写了后序", "form": "五言", "line": ["莺羽吟修竹，", "游鳞戏澜涛。"], "bank": "left"}, {"name": "谢瑰", "note": "", "fine": true, "bank": "right"}, {"name": "孙统", "note": "", "form": "五言", "line": ["因流转轻觞，", "泠风飘落松。"], "bank": "left"}, {"name": "王凝之", "note": "王羲之之子", "form": "五言", "line": ["氤氲柔风扇，", "熙怡和气淳。"], "bank": "right"}, {"name": "卞迪", "note": "", "fine": true, "bank": "left"}, {"name": "徐丰之", "note": "", "form": "五言", "line": ["零觞飞曲津，", "欢然朱颜舒。"], "bank": "right"}, {"name": "华茂", "note": "", "form": "四言", "line": ["泛泛轻觞，", "载欣载怀。"], "bank": "left"}, {"name": "卓髦", "note": "", "fine": true, "bank": "right"}, {"name": "王徽之", "note": "王羲之之子", "form": "四言", "line": ["散怀山水，", "萧然忘羁。"], "bank": "left"}, {"name": "羊模", "note": "", "fine": true, "bank": "right"}], "tallyHistoric": {"total": 42, "twoPoems": 11, "onePoem": 15, "fined": 16}, "note": "guests 顺序即沿溪从上游到下游的座次（座次本身是示意，史料无记载）；bank 为坐在溪水哪一侧。成诗者 8 人、罚酒者 5 人，比例约同史载 26:16。诗句为各人《兰亭诗》中的一联，原文据《会稽掇英总集》卷三（四库本）转简体；罚酒名单据葛立方《韵语阳秋》卷五。杯形参考湖南博物院藏马王堆一号墓“君幸酒”云纹漆耳杯（西汉，长 16.9 cm，高 4.4 cm，内红漆黑卷云纹，杯底黑漆书“君幸酒”）。"}, "works": [{"img": "w1.webp", "w": 992, "h": 1200, "who": "陆机", "whoLat": "Lu Ji, 261 – 303", "title": "《平复帖》", "meta": ["西晋，纸本草隶书", "23.7 × 20.6 cm", "北京，故宫博物院（新00044430）"], "note": "信里说起病中的朋友，是现存最早的名家墨迹。", "credit": "Wikimedia Commons, File:陆机草隶平复帖卷.png — 来源 故宫博物院数字文物库，公有领域"}, {"img": "w2.webp", "w": 798, "h": 1200, "who": "王珣", "whoLat": "Wang Xun, 350 – 401", "title": "《伯远帖》", "meta": ["东晋，纸本行书", "25.1 × 17.2 cm", "北京，故宫博物院（新00145155）"], "note": "故宫认为它与《平复帖》同为仅存的晋代名家真迹。", "credit": "Wikimedia Commons, File:王珣行书伯远帖卷.png — 来源 故宫博物院数字文物库，公有领域"}, {"img": "w3.webp", "w": 1200, "h": 955, "who": "王羲之", "whoLat": "Wang Xizhi, c. 303 – 361", "title": "《快雪时晴帖》（唐摹本）", "meta": ["东晋原作，唐摹本，纸本行书", "本幅 23 × 14.8 cm", "台北，台北故宫博物院（故书000141）"], "note": "雪后问候友人的短信；左页是赵孟頫的跋。", "credit": "Wikimedia Commons, File:晉王羲之快雪時晴帖 冊.jpg — 来源 台北故宫博物院，CC0"}, {"img": "w4.webp", "w": 1200, "h": 1117, "who": "王献之", "whoLat": "Wang Xianzhi, 344 – 386", "title": "《鸭头丸帖》（唐摹本）", "meta": ["东晋原作，唐摹本，绢本行书", "26.1 × 26.9 cm", "上海，上海博物馆"], "note": "王羲之之子，兰亭那天据说没作出诗。", "credit": "Wikimedia Commons, File:王獻之 鴨頭丸帖.jpg — 来源 上海博物馆，公有领域"}], "chain": "之前：上一厅的说唱俑出自一位没留下名字的陶工。之后：唐太宗推崇王羲之，唐人的摹本和后来的刻帖让兰亭成了历代学书的范本，王羲之被尊为“书圣”。晋人的行书连绵不断，一笔带着下一笔；下一厅，这样的线进到画里。", "sources": [{"label": "故宫博物院 · 冯承素行书摹兰亭序卷", "claim": "兰亭序神龙本：文物号 故00002597，唐，纸本行书，纵 24.5 横 69.9 cm；卷首有唐中宗神龙年号小印故称神龙本；楮纸两幅拼接，前纸 13 行后纸 15 行；时出贼毫、叉笔，兼有勾摹与临写特点；后纸明项元汴题记，后世据此定为冯承素摹本；馆方又说“据考”神龙半印并非唐中宗内府钤印而是后人所添，定冯承素摹也不可信，但仍是唐以来流传有绪的古摹本；钤鉴藏印 180 余方，后纸宋至明 20 家题跋", "url": "https://www.dpm.org.cn/collection/handwriting/228279.html"}, {"label": "故宫博物院 · 《王羲之〈兰亭序〉神龙本》", "claim": "故宫出版社 2016：冯承素摹本为最接近原迹的唐摹本", "url": "https://www.dpm.org.cn/journal_detail/239217.html"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图 File:Lanting Xu by Feng Chengsu.jpg，4513 × 1480，上传者 Joanhappy3000，页面标“Own work”、CC BY-SA 4.0；与 2006 年上传的 File:LantingXu.jpg（来源临沂市政府网站，PD-Art）为同一扫描（像素网格相同，灰度相关 0.999，只差整体明暗），摄影者不详；本展按页面许可署名", "url": "https://commons.wikimedia.org/wiki/File:Lanting_Xu_by_Feng_Chengsu.jpg"}, {"label": "维基百科 · 兰亭集序神龙本", "claim": "神龙半印仅存左半；神龙半印真伪与冯承素摹的归属均有质疑；2008 年王开儒提出或为明摹本", "url": "https://zh.wikipedia.org/zh-hans/%E5%85%B0%E4%BA%AD%E9%9B%86%E5%BA%8F%E7%A5%9E%E9%BE%99%E6%9C%AC"}, {"label": "维基文库 · 何延之《兰亭始末记》", "claim": "何延之（唐）：永和九年三月三日与孙统、孙绰、谢安等四十有一人修禊；“挥毫制序，典乐而书”（当场写序）；凡二十八行三百二十四字，“之”字二十许个变转悉异；传至七代孙智永；太宗使萧翼取之；命赵模、韩道政、冯承素、诸葛贞四人各拓数本赐皇太子诸王近臣；随仙驾入玄宫（昭陵）", "url": "https://zh.wikisource.org/wiki/%E8%98%AD%E4%BA%AD%E5%A7%8B%E6%9C%AB%E8%A8%98"}, {"label": "维基文库 · 《会稽掇英总集》卷三", "claim": "宋孔延之编：王羲之序与《兰亭诗》全文；十一人四言五言各一首（王羲之、谢安、谢万、孙绰、徐丰之、孙统、王彬之、王凝之、王肃之、王徽之、袁峤之），十五人一篇成（郗昙、王丰之、华茂等），“一十六人诗不成各罚酒三觥”；孙绰作后序。本厅展项所引诗句均据此", "url": "https://zh.wikisource.org/wiki/%E6%9C%83%E7%A8%BD%E6%8E%87%E8%8B%B1%E7%B8%BD%E9%9B%86_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B703"}, {"label": "维基文库 · 葛立方《韵语阳秋》卷五", "claim": "罚酒三觥的十六人：王献之、谢瑰、卞迪、卓髦、羊模、孔炽、刘密、虞谷、劳夷、后绵、华耆、谢藤、王儗、吕系、吕本、曹礼", "url": "https://zh.wikisource.org/wiki/%E9%9F%BB%E8%AA%9E%E9%99%BD%E7%A7%8B/%E5%8D%B7%E4%BA%94"}, {"label": "维基文库 · 周密《齐东野语》卷十九", "claim": "永和兰亭禊饮集者四十二人，十一人各成两篇，十五人各成一篇，十六人诗不成罚觥，其中有王献之", "url": "https://zh.wikisource.org/wiki/%E9%BD%8A%E6%9D%B1%E9%87%8E%E8%AA%9E/%E5%8D%B7%E5%8D%81%E4%B9%9D"}, {"label": "维基文库 · 孙过庭《书谱》", "claim": "写乐毅则情多怫郁，书画赞则意涉瑰奇，黄庭经则怡怿虚无，太史箴又纵横争折，暨乎兰亭兴集，思逸神超；卷末自署垂拱三年", "url": "https://zh.wikisource.org/wiki/%E6%9B%B8%E8%AD%9C"}, {"label": "维基文库 · 梁巘《评书帖》", "claim": "晋尚韵，唐尚法，宋尚意，元、明尚态", "url": "https://zh.wikisource.org/wiki/%E8%A9%95%E6%9B%B8%E5%B8%96"}, {"label": "中国教育新闻网 · 人的觉醒", "claim": "李泽厚《美的历程》“魏晋风度”：把汉末魏晋的新思潮概括为“人的觉醒”，内在的精神性成为最高标准", "url": "http://www.jyb.cn/zgjsb/201706/t20170614_666702.html"}, {"label": "台北故宫博物院 · 晋王羲之快雪时晴帖 册", "claim": "快雪时晴帖：王羲之（约 303–361），东晋，唐代精摹本，双钩填廓；本幅 23 × 14.8 cm；统一编号 故书000141N000000000；二十八字；乾隆与《中秋帖》《伯远帖》合称三希；王羲之后人尊称“书圣”（Commons 所录馆方说明）；低阶图像 CC0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/19?dep=P"}, {"label": "故宫博物院 · 陆机草隶书平复帖卷", "claim": "平复帖：文物号 新00044430，西晋，陆机（261–303），纸本，纵 23.7 横 20.6 cm，草隶书 9 行 86 字；现存年代最早并真实可信的西晋名家法笔；内容涉及贺循病情；1956 年张伯驹捐献", "url": "https://www.dpm.org.cn/collection/handwriting/234553.html"}, {"label": "故宫博物院 · 王珣行书伯远帖", "claim": "伯远帖：文物号 新00145155，王珣（350–401），纸本行书，纵 25.1 横 17.2 cm，5 行 47 字；与《平复帖》为现存仅有的两件晋代名人法书真迹；乾隆三希之一", "url": "https://www.dpm.org.cn/collection/handwriting/228199.html"}, {"label": "上海博物馆 · 王献之行书鸭头丸帖卷", "claim": "鸭头丸帖：王献之（344–386），东晋，丝绢，纵 26.1 横 26.9 cm，唐摹本", "url": "https://www.shanghaimuseum.net/mu/frontend/pg/article/id/CI00000376"}, {"label": "湖南博物院 · “君幸酒”云纹漆耳杯", "claim": "马王堆一号汉墓出土，西汉，长 16.9 cm、高 4.4 cm，内红漆黑卷云纹，底书“君幸酒”（请君饮酒）；展项杯形据此", "url": "https://www.hnmuseum.com/zh-hans/gallery/node/9984/8"}, {"label": "维基共享资源 · 作品栏图片文件页", "claim": "平复帖、伯远帖（故宫数字文物库来源，公有领域）、快雪时晴帖（台北故宫，CC0）、鸭头丸帖（上海博物馆来源，公有领域）", "url": "https://commons.wikimedia.org/wiki/File:%E9%99%86%E6%9C%BA%E8%8D%89%E9%9A%B6%E5%B9%B3%E5%A4%8D%E5%B8%96%E5%8D%B7.png"}]};

