(window.EH_ROOMS=window.EH_ROOMS||{})["luoshen"]={"id": "luoshen", "zh": "洛神", "lat": "Six Dynasties", "yrs": "4th – 6th c. CE", "one": "赋里的惊鸿游龙，画成了真的", "wall": "#2B3333", "wallWhy": "墙色取洛水的深青：这卷画的是洛水边的一场相遇，水从卷首一直流到卷尾。青色压得很深，让褐色的旧绢和浅色文字都立得住。手卷本来平放在案上从右往左展开看，所以本厅不加框，也不仿造它的装裱，只挂画心，照原样横陈。", "ink": "light", "frame": "none", "art": {"img": "main_hang.webp", "w": 3000, "h": 1177, "who": "顾恺之（传）", "whoLat": "Gu Kaizhi, c. 344 – c. 406", "title": "《洛神赋图》（宋摹本）", "short": "《洛神赋图》", "meta": ["宋摹本，原作传为东晋，绢本设色", "27.1 × 572.8 cm", "北京，故宫博物院（新00147329）"], "credit": "Wikimedia Commons, File:顾恺之洛神赋图卷（宋摹）.png — 来源 故宫博物院名画记，公有领域"}, "lede": "三国魏的诗人曹植写过一篇《洛神赋》，说他在洛水边遇见了水神宓妃。相传一百多年后，东晋画家顾恺之把这篇赋画成了一卷画。", "work": "手卷从右往左展开。卷首，曹植一行停车歇马，他被侍从簇拥着站在岸边，望向水上的洛神。她手执一柄扇，衣带向后飘，回头看他。天上画着赋里形容她的比喻：两只飞雁是“翩若惊鸿”，一条龙是“婉若游龙”，还有一轮初升的红日。同一个洛神、同一个曹植在卷中反复出现，一段接一段，直到她乘六龙云车离去，他驾车东归。", "quote": ["其形也，翩若惊鸿，婉若游龙。荣曜秋菊，华茂春松。仿佛兮若轻云之蔽月，飘飖兮若流风之回雪。", "曹植《洛神赋》，序称作于魏黄初三年（222）"], "origin": "曹植在赋序里说，黄初三年（222）他朝见京师后返回（《三国志》记这次入朝在次年），渡过洛水，想起宋玉写神女的故事，于是作赋。这卷画不抄赋文，也没有名款，传为顾恺之原作。故宫博物院从画法、绢和颜色判断，它是宋人的摹本，卷上钤有金章宗“明昌”诸印。学者陈葆真统计，传世的《洛神赋图》有九本（套），她认为这一系摹本所据的原本约成于 560–580 年，比顾恺之晚一百多年。原稿出自谁手，本展不作裁决。", "traits": [["画家有了名字", "顾恺之在世时就有“才绝、画绝、痴绝”之称，还写下《论画》《画云台山记》等画论。画不再只出自无名的工匠，画家有了名字，也有了自己的主张。"], ["传神写照", "《世说新语》记顾恺之画人，有时几年不点眼睛。他说身体美丑无关紧要，“传神写照，正在阿堵中”：一个人的神，全在眼睛里。"], ["书画用笔同法", "唐人张彦远说：王献之写字一笔连着下一笔，称“一笔书”；陆探微作画也连绵不断，称“一笔画”，“故知书画用笔同法”。"], ["人大于山", "张彦远说早期山水“或水不容泛，或人大于山”。这卷里山石树木只勾轮廓、填颜色，不加皴擦，人比山还大，山水还只是故事的背景。"]], "special": {"title": "春蚕吐丝", "type": "silk_line", "text": "元人汤垕说顾恺之的画“如春蚕吐丝”：线细而匀，连绵不断，衣纹和飘带都靠这样一根线勾出来。在这段空绢上拖着笔尖，描一根长长的衣带。笔尖会慢半拍跟着你的手：走得稳，线就细而连绵，琴的泛音一直响着；手一急，线就变粗；一停顿，墨积成疙瘩，泛音也断了。描完，把你的线和洛神衣带上的一根线并排比一比。", "hints": {"start": "在空绢上按住，拖出一根衣带", "startTouch": "在空绢上按住，拖出一根衣带", "steady": "稳住，线细而连绵", "fast": "手急了，线变粗", "pause": "停住了，墨积成一个疙瘩", "broken": "泛音断了，接着往下描", "short": "线还短，再往下拖一段", "done": "一根衣带描完了", "compare": "和原作上的一根衣带线比一比", "again": "换一段空绢，再描一根"}, "captions": {"mine": "你的线", "orig": "原作：洛神回眸处，衣带尾端的一根飘带", "origSource": "传顾恺之《洛神赋图》（宋摹本），故宫博物院", "width": "粗细变化", "breaks": "停顿", "length": "连绵长度", "verdictGood": "细、匀、不断，像春蚕吐丝", "verdictUneven": "时粗时细，手快慢不匀", "verdictBroken": "断了几处，气没有连上", "quote": "“如春蚕吐丝，初见甚平易……细视之，六法兼备”", "quoteSource": "汤垕《画鉴》，元代"}, "orig": {"note": "原作衣带线：洛神回眸（s2 段）衣带尾端向右飘出的一根绿色飘带，近似中线，目测误差约 ±6 F 像素。F = _wip/prep-luoshen/painting_full.npy 坐标（47002×2168），main = main.webp 坐标（16000×738）。", "img": "cut/hr/huimou.webp", "boxF": [39500, 1290, 480, 200], "boxMain": [13446.2, 439.1, 163.4, 68.1], "lineF": [[39600, 1424], [39645, 1409], [39685, 1398], [39715, 1411], [39740, 1424], [39780, 1419], [39830, 1409], [39895, 1416]], "lineMain": [[13480.3, 484.7], [13495.6, 479.6], [13509.2, 475.9], [13519.4, 480.3], [13527.9, 484.7], [13541.6, 483.0], [13558.6, 479.6], [13580.7, 482.0]]}}, "works": [{"img": "w1.webp", "w": 1200, "h": 508, "who": "顾恺之（传）", "whoLat": "Gu Kaizhi, c. 344 – c. 406", "title": "《女史箴图》（局部）", "meta": ["约 400–700 年（馆方定年），绢本设色", "24.4 × 343.8 cm", "伦敦，大英博物馆（1903,0408,0.1）"], "note": "熊冲出来，冯媛挺身挡在汉元帝前。", "credit": "Wikimedia Commons, File:Admonitions Scroll (center).jpg — 来源 大英博物馆，公有领域"}, {"img": "w2.webp", "w": 1200, "h": 837, "who": "顾恺之（传）", "whoLat": "Gu Kaizhi, c. 344 – c. 406", "title": "《列女仁智图》（局部）", "meta": ["宋摹本，绢本设色", "25.8 × 470.3 cm", "北京，故宫博物院"], "note": "卷首一段：楚武王和夫人邓曼。", "credit": "Wikimedia Commons, File:顾恺之列女仁智图卷（宋摹）.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w3.webp", "w": 596, "h": 1200, "who": "佚名北魏画工", "whoLat": "Unknown Northern Wei painter", "title": "《彩绘人物故事漆屏》", "meta": ["北魏，不晚于 484 年，木板漆画", "高 81.5 cm，两板拼合宽约 40 cm", "太原，山西博物院"], "note": "出自司马金龙墓；最下一格画班婕妤辞辇。", "credit": "Wikimedia Commons, File:Lacquer painting over wood, Northern Wei.jpg — 来源 苏立文《中国艺术》（1999）扫描，公有领域"}, {"img": "w4.webp", "w": 1200, "h": 453, "who": "佚名南朝工匠", "whoLat": "Unknown Southern Dynasties artisans", "title": "《竹林七贤与荣启期》", "meta": ["南朝，模印砖画", "南壁 78 × 242.5 cm", "南京，南京博物院"], "note": "南壁：嵇康、阮籍、山涛、王戎各坐树下。", "credit": "Wikimedia Commons, File:Seven Sages of the Bamboo Grove 1.Nanjing Museum.jpg — 摄影 Gary Lee Todd，Ismoon 拼接，CC BY-SA 4.0"}], "chain": "之前：兰亭的行书一笔带着下一笔，史书说王羲之的笔势“矫若惊龙”。之后：唐人张彦远把顾恺之、陆探微、张僧繇、吴道子四家的用笔放在一起讲，人物画的线一代代传下去。下一厅，线和矿物颜色进了石窟的墙壁。", "sources": [{"label": "故宫博物院 · 顾恺之洛神赋图卷（宋摹）", "claim": "文物号 新00147329；晋顾恺之（宋摹），绢本设色，横 572.8、纵 27.1 cm；开首曹植远望龙鸿飞舞、洛神飘然而来，后段洛神驾六龙云车离去；分段描绘、主要人物反复出现；山石树木钩填无皴，“人大于山，水不容泛”；不书赋文、无名款，当为宋人摹本；钤“明昌”“御府宝绘”“群玉中秘”“明昌御鉴”及清内府诸印；顾恺之小传（“才绝、画绝、痴绝”，著《论画》《魏晋胜流画赞》《画云台山记》，行笔如春蚕吐丝，传神阿堵）；洛神赋序“黄初三年”", "url": "https://www.dpm.org.cn/collection/paint/234597.html"}, {"label": "故宫名画记 · 顾恺之洛神赋图卷（宋摹）", "claim": "主图的馆方高清全卷图（Commons 文件的来源）", "url": "https://minghuaji.dpm.org.cn/paint/detail?id=69037b434240e1bbaa99067ca79e94f3"}, {"label": "维基共享资源 · 主图文件页", "claim": "File:顾恺之洛神赋图卷（宋摹）.png，97531 × 2472，公有领域（PD-Art）；本厅只挂画心", "url": "https://commons.wikimedia.org/wiki/File:%E9%A1%BE%E6%81%BA%E4%B9%8B%E6%B4%9B%E7%A5%9E%E8%B5%8B%E5%9B%BE%E5%8D%B7%EF%BC%88%E5%AE%8B%E6%91%B9%EF%BC%89.png"}, {"label": "大英百科全书 · 顾恺之", "claim": "顾恺之约生于 344 年，无锡人，约卒于 406 年；代表作《洛神赋图》《女史箴图》（后者或为唐摹本）", "url": "https://www.britannica.com/biography/Gu-Kaizhi"}, {"label": "维基文库 · 曹植《洛神赋》", "claim": "序“黄初三年，余朝京师，还济洛川……感宋玉对楚王神女之事，遂作斯赋”；“翩若惊鸿，婉若游龙。荣曜秋菊，华茂春松。髣髴兮若轻云之蔽月，飘颻兮若流风之回雪。远而望之，皎若太阳升朝霞”", "url": "https://zh.wikisource.org/wiki/%E6%B4%9B%E7%A5%9E%E8%B3%A6"}, {"label": "维基文库 · 《三国志》卷十九 陈思王植传", "claim": "“四年，徙封雍丘王。其年，朝京都。”——史传所记曹植此次入朝在黄初四年（223），与赋序“黄初三年”相差一年", "url": "https://zh.wikisource.org/wiki/%E4%B8%89%E5%9C%8B%E5%BF%97/%E5%8D%B719"}, {"label": "维基文库 · 《晋书》卷八十 王羲之传", "claim": "“论者称其笔势，以为飘若浮云，矫若惊龙”", "url": "https://zh.wikisource.org/wiki/%E6%99%89%E6%9B%B8/%E5%8D%B7080"}, {"label": "维基文库 · 《世说新语·巧艺》", "claim": "“顾长康画人，或数年不点目精……四体妍蚩，本无关于妙处；传神写照，正在阿堵中”", "url": "https://zh.wikisource.org/wiki/%E4%B8%96%E8%AA%AA%E6%96%B0%E8%AA%9E/%E5%B7%A7%E8%93%BA"}, {"label": "维基文库 · 汤垕《画鉴》", "claim": "元汤垕：“顾恺之画如春蚕吐丝，初见甚平易，且形似时或有失，细视之，六法兼备”；曾见《洛神赋》等", "url": "https://zh.wikisource.org/wiki/%E7%95%AB%E9%91%92_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)"}, {"label": "维基文库 · 张彦远《历代名画记》卷二", "claim": "“顾恺之之迹紧劲联绵，循环超忽”；王献之“一笔书”、陆探微“一笔画”，“故知书画用笔同法”", "url": "https://zh.wikisource.org/wiki/%E6%AD%B4%E4%BB%A3%E5%90%8D%E7%95%AB%E8%A8%98_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B702"}, {"label": "故宫博物院《紫禁城》2020 年第 4 期 · 形神之间", "claim": "《历代名画记》论早期山水“群峰之势，若钿饰犀栉，或水不容泛，或人大于山”；《列女仁智图》卷（宋摹本）绢本设色，纵 25.8、横 470.3 cm，故宫博物院藏", "url": "https://www.dpm.org.cn/Uploads/File/2020/04/28/u5ea804b8c128f.pdf"}, {"label": "台北故宫《故宫学术季刊》23 卷 1 期 · 陈葆真《传世〈洛神赋〉故事画的表现类型与风格系谱》", "claim": "存世《洛神赋图》（不计现代作品）共九卷；六朝类型祖本约作成于 560~580 年；辽宁本与北京甲本为摹自同一祖本的临摹本，约作成于南北宋之间（约 12 世纪）；北京甲本缺卷首〔离京〕与〔休憩〕的一部分", "url": "https://www.npm.gov.tw/NewChineseArtDownload.ashx?bid=3698"}, {"label": "大英博物馆 · 女史箴图展览页", "claim": "传为顾恺之（约 345–406 年），大约作于公元 400–700 年之间", "url": "https://www.britishmuseum.org/exhibitions/admonitions-instructress-court-ladies"}, {"label": "大英博物馆 · 藏品数据库 1903,0408,0.1", "claim": "女史箴图卷，5–7 世纪，绢本；高 24.37、长 343.75 cm", "url": "https://www.britishmuseum.org/collection/object/A_1903-0408-1"}, {"label": "英文维基百科 · 女史箴图", "claim": "大英博物馆 1903,0408,0.1；绢本；高约 25 cm；现存九段（原十一段），冯媛挡熊一段", "url": "https://en.wikipedia.org/wiki/Admonitions_Scroll"}, {"label": "维基共享资源 · 女史箴图文件页", "claim": "File:Admonitions Scroll (center).jpg，18955 × 1340，公有领域", "url": "https://commons.wikimedia.org/wiki/File:Admonitions_Scroll_(center).jpg"}, {"label": "维基共享资源 · 列女仁智图文件页", "claim": "File:顾恺之列女仁智图卷（宋摹）.png，66787 × 3140，来源故宫名画记，公有领域；卷首为楚武王与邓曼", "url": "https://commons.wikimedia.org/wiki/File:%E9%A1%BE%E6%81%BA%E4%B9%8B%E5%88%97%E5%A5%B3%E4%BB%81%E6%99%BA%E5%9B%BE%E5%8D%B7%EF%BC%88%E5%AE%8B%E6%91%B9%EF%BC%89.png"}, {"label": "维基百科 · 彩绘人物故事漆屏", "claim": "1965 年出土于山西大同司马金龙墓；北魏；画《列女传》故事，含班婕妤", "url": "https://zh.wikipedia.org/wiki/%E5%BD%A9%E7%BB%98%E4%BA%BA%E7%89%A9%E6%95%85%E4%BA%8B%E6%BC%86%E5%B1%8F"}, {"label": "中国文物资料 · 司马金龙墓木板漆画", "claim": "每块高 81.5、宽 20.5 cm；司马金龙卒于太和八年（484）；保存最完好的两块藏山西博物院，其余藏大同市博物馆", "url": "https://www.56-china.com.cn/show-case-9481.html"}, {"label": "山西晚报 · 司马金龙墓漆画屏风：心中的期会", "claim": "漆画屏风通高 82、宽 40、厚约 2.5 cm；现分藏山西博物院与大同市博物馆（图片由两馆提供）", "url": "https://www.sohu.com/a/614881037_115635"}, {"label": "维基共享资源 · 山西博物院陈列的漆屏实拍", "claim": "Gary Lee Todd 摄于山西博物院（Shanxi Provincial Museum, Taiyuan），与本厅所挂一块（下格班婕妤辞辇）为同一块两板拼合的屏板", "url": "https://commons.wikimedia.org/wiki/File:Northern_Wei_Black_Lacquer_Painting,_Tomb_of_Sima_Jinlong,_484_AD_(10100456626).jpg"}, {"label": "维基共享资源 · 漆屏文件页", "claim": "File:Lacquer painting over wood, Northern Wei.jpg，扫描自苏立文《中国艺术》（1999），公有领域", "url": "https://commons.wikimedia.org/wiki/File:Lacquer_painting_over_wood,_Northern_Wei.jpg"}, {"label": "南京博物院 · 竹林七贤与荣启期砖画", "claim": "南朝，南京西善桥宫山大墓出土；一组高 78、长 242.5 cm，二组高 78、长 241.5 cm", "url": "https://www.njmuseum.com/en/collectionDetails?id=465"}, {"label": "宝鸡市文物局 · 首批禁止出国（境）展览文物", "claim": "南壁嵇康、阮籍、山涛、王戎，高 78、长 242.5 cm；北壁向秀、刘伶、阮咸、荣启期；藏南京博物院", "url": "https://wwj.baoji.gov.cn/col1892/col17273/202510/t20251014_1218478.html"}, {"label": "维基共享资源 · 竹林七贤砖画文件页", "claim": "File:Seven Sages of the Bamboo Grove 1.Nanjing Museum.jpg，由 Ismoon 用 Gary Lee Todd 的两张照片拼接，作者署 Gary Lee Todd，CC BY-SA（GFDL / cc-by-sa-all）；左端银杏树下为嵇康", "url": "https://commons.wikimedia.org/wiki/File:Seven_Sages_of_the_Bamboo_Grove_1.Nanjing_Museum.jpg"}], "scroll": {"w": 16000, "h": 738, "win": [12978.98, 0.0, 14860.08, 738.0], "head": "right", "lo": "scroll/lo.webp", "loW": 3469, "loH": 160, "levels": [{"f": "scroll/a{i2}.webp", "w": 25517, "h": 1177, "tw": 1024}]}};

