(window.EH_ROOMS=window.EH_ROOMS||{})["jiuselu"]={"id": "jiuselu", "zh": "九色鹿", "lat": "Northern Wei", "yrs": "386 – 534 CE", "one": "无名画工，把佛经画成了连环画", "wall": "#2A221D", "wallWhy": "墙色取石窟里熏暗的泥壁：九色鹿画在第 257 窟西壁的泥层上，窟里光线昏暗。深褐压住了四周，横带上的土红、石绿和白鹿才亮得起来。壁画本是墙的一部分，没有画框，所以本厅不加框，照原样挂这一段横带。", "ink": "light", "frame": "none", "art": {"img": "main.webp", "w": 3248, "h": 557, "who": "佚名北魏画工", "whoLat": "Unknown Northern Wei painters", "title": "《九色鹿王本生》", "short": "《九色鹿王本生》", "meta": ["北魏，泥壁彩绘", "纵 96 × 横 385 cm", "敦煌，敦煌研究院（莫高窟第 257 窟西壁）"], "credit": "Wikimedia Commons, File:鹿王本生故事畫.jpg — 来源 佛光山佛陀纪念馆（Google 艺术与文化），公有领域"}, "lede": "北魏时，敦煌莫高窟第 257 窟的画工在西壁上画了一个本生故事。本生讲佛陀前世的事：这一世他是一头九色鹿，救起落水的人，却被那人出卖。", "work": "长长一条横带铺着土红色的地，故事从两头开讲，到中间收尾。左端，白鹿驮着落水的人游出水，那人随后跪地叩谢；右端，王后在宫中要鹿皮，那人跪在宫前告密，国王带人马出城。马前那个遍身白点的人，一般认为就是他。两头在中间会合：九色鹿站在国王马前，昂头陈说。山只是一排排青绿、白色的小三角。人物的脸多已发黑，宫中王后的脸却还是白的。", "quote": ["我时不惜此命，自投水中，负此人出，本要誓不相道；人无反复，不如水中浮木也。", "支谦译《佛说九色鹿经》，三国吴；鹿对国王说"], "origin": "敦煌在河西走廊西端，是丝路进入中原的门户，佛教艺术从这里东来。北魏时，莫高窟开出一批中心塔柱窟，第 257 窟是其中之一：窟中立一方柱，四壁分三层，上层画天宫伎乐，中层画千佛和故事，下层画药叉。九色鹿画在西壁中层，依据的是三国吴支谦所译《佛说九色鹿经》。经里说，鹿只求被救的人别说出它的住处；那人为了国王的重赏告了密，脸上随即生出癞疮。国王听完鹿的话，放它回去。", "traits": [["凹凸法", "人物的肉身用色一层层晕染，边深中浅，显出起伏。段文杰认为，白鼻梁、白眼眶的“小字脸”，是吸收西域传来的“天竺遗法”凹凸法的新样式。"], ["颜色也在变", "敦煌研究院的吴荣鉴说，壁画变色的主要是人物肤色：初绘时是肉色，南北朝到隋初的壁画多变成黑色或铅灰。通行说法是颜料氧化，成因学者仍在研究。"], ["画在泥壁上", "莫高窟的壁画画在窟壁的泥层上：先抹掺了麦草的粗泥，再抹细泥，刷上白色的底子，然后上色。研究者在同期的 254 窟测出了铅丹、石膏等多种材料。"], ["没有名字的画工", "上一厅的画还挂着顾恺之的名字，这面墙的画工却没有留下姓名。学者认为，这里有印度、西域和汉地的多种因素，合在一起，成了中国化的佛教艺术。"]], "special": {"title": "燃灯照壁", "type": "oil_lamp", "text": "第 257 窟中间立着一根方柱，西壁在方柱后面，离窟门最远。这里借一盏油灯看这段横带：灯光只照亮灯边一小圈。手移得快，火苗会歪，太快就灭了；灯在一处停久些，石绿和土红会慢慢显出来。故事从两头开讲，照着它一路走到中间。唐人许嵩记南朝寺门上用“天竺遗法”画的花“远望眼晕如凹凸，就视即平”：把灯拉远、凑近，看看这些晕染。", "hints": {"start": "移动油灯，在暗处找壁画", "startTouch": "按住拖动油灯，在暗处找壁画", "slow": "慢慢走，火苗稳了", "fast": "走快了，火苗歪了", "out": "灯灭了，停一停再点上", "relit": "灯又点着了", "linger": "停久一点，颜色慢慢显出来", "ends": "故事从两头开讲", "center": "两头的故事在这里会合", "distance": "滚动滚轮，把灯拉远或凑近", "distanceTouch": "双指开合，把灯拉远或凑近", "far": "灯拉远了：晕染像是鼓了起来", "near": "灯凑近了：又是平的", "done": "九个场面都照过了", "again": "再从头照一遍"}, "captions": {"lamp": "油灯", "left": "左端", "right": "右端", "order": "左端从救人讲起，右端从王宫讲起，两头在中间会合", "xiaozi": "发黑的脸上留着白鼻梁、白眼眶，人称“小字脸”", "queen": "王后的脸还是白的", "black": "肉色晕染，如今多已发黑（通行说：颜料氧化）", "aotuQuote": "“远望眼晕如凹凸，就视即平”", "aotuSource": "唐许嵩《建康实录》记南朝梁一乘寺的凹凸花，据《太平御览》卷六五八引", "aotuNote": "那段话说的是建康一乘寺门上的花，不是这面墙；借来看同一路晕染。", "count": "已照亮 {n} / 9 个场面"}, "scenes": [{"id": "rescue", "end": "left", "step": 1, "box": [250, 280, 200, 230], "caption": "落水的人伏在鹿背上，被驮出水"}, {"id": "herd", "end": "left", "step": 2, "box": [270, 10, 420, 380], "caption": "山间奔跑的鹿"}, {"id": "thanks", "end": "left", "step": 3, "box": [683, 200, 300, 250], "caption": "他跪地叩谢；鹿只求他别说出自己的住处"}, {"id": "sleep", "end": "left", "step": 4, "box": [900, 5, 210, 115], "caption": "鹿卧在山间"}, {"id": "palace", "end": "right", "step": 1, "box": [2690, 20, 450, 510], "caption": "王后梦见九色鹿，要它的皮做衣裳、角做拂柄"}, {"id": "inform", "end": "right", "step": 2, "box": [2480, 320, 220, 200], "caption": "被救的人贪图重赏，跪在宫前告密"}, {"id": "chariot", "end": "right", "step": 3, "box": [2060, 20, 420, 420], "caption": "国王的白马与车"}, {"id": "ride", "end": "right", "step": 4, "box": [1620, 60, 500, 420], "caption": "国王带人马出城；遍身白点的人，一般认为是生了癞疮的告密者"}, {"id": "confront", "end": "center", "step": 5, "box": [1035, 30, 580, 400], "caption": "九色鹿站在国王马前，说出了实情"}], "faces": [{"id": "kneeler", "head": [768, 232], "tone": "black"}, {"id": "king_horse", "head": [1432, 125], "tone": "black"}, {"id": "pointer", "head": [1932, 170], "tone": "black"}, {"id": "king_palace", "head": [2878, 272], "tone": "black"}, {"id": "queen", "head": [2966, 300], "tone": "white"}], "center": {"box": [1035, 30, 580, 400], "deerHead": [1205, 180]}, "note": "坐标都是 main.webp 像素（3248×557），与 cut/layers.json 一致；场景框与脸的坐标为目测（±4 px），释读按敦煌研究院与崇秀全 2008 的通行说法，herd、sleep 两格的释读各家不一，所以字幕只写看得见的内容。step 是各自那一头的叙事次序，center 为终点。油灯、凹凸远近效果是展项的体验设计，不是史料。"}, "works": [{"img": "w1.webp", "w": 1200, "h": 891, "who": "佚名北魏画工", "whoLat": "Unknown Northern Wei painters", "title": "《尸毗王本生》", "meta": ["北魏，泥壁彩绘", "尺寸不详", "敦煌，敦煌研究院（莫高窟第 254 窟北壁）"], "note": "同时代的 254 窟：割肉救鸽的国王，身子也已发黑。", "credit": "Wikimedia Commons, File:Mogao Cave 254, Shibi Jataka, Northern Wei period.jpg — 来源不详，公有领域"}, {"img": "w2.webp", "w": 1200, "h": 655, "who": "佚名西魏画工", "whoLat": "Unknown Western Wei painters", "title": "《五百强盗成佛》（局部）", "meta": ["西魏，约 538–539 年，泥壁彩绘", "尺寸不详", "敦煌，敦煌研究院（莫高窟第 285 窟南壁）"], "note": "强盗出家为僧，人物修长清秀，画在白地上。", "credit": "Wikimedia Commons, File:五百強盜成佛.jpg — 来源 佛光山佛陀纪念馆（Google 艺术与文化），公有领域"}, {"img": "w3.webp", "w": 833, "h": 1200, "who": "佚名唐代画工", "whoLat": "Unknown Tang painters", "title": "《维摩诘经变》（局部）", "meta": ["盛唐（8 世纪），泥壁彩绘", "尺寸不详", "敦煌，敦煌研究院（莫高窟第 103 窟东壁）"], "note": "维摩诘手持麈尾，身子前倾；以线描为主。", "credit": "Wikimedia Commons, File:Vimalakirti debating Manjusri, Tang Dynasty.jpg — 来源 苏立文《中国艺术》（1999）扫描，公有领域"}, {"img": "w4.webp", "w": 1200, "h": 1196, "who": "佚名五代画工", "whoLat": "Unknown Five Dynasties painters", "title": "《五台山图》（局部）", "meta": ["五代（10 世纪中叶），泥壁彩绘", "全图长 13.4 m，高 3.4 m", "敦煌，敦煌研究院（莫高窟第 61 窟西壁）"], "note": "五台山一带的寺院、道路和香客，都画上了墙。", "credit": "Wikimedia Commons, File:莫高窟五臺山圖.jpg — 来源 佛光山佛陀纪念馆（Google 艺术与文化），公有领域"}], "chain": "之前：本生故事和凹凸晕染从印度、西域一路传到敦煌；上一厅的线条还画在文人的绢上。之后：西魏 285 窟的人物变得修长清秀，画在白地上；唐代的经变画铺满整面墙。下一厅，佛像的样式也在一路吸收各地的审美。", "sources": [{"label": "敦煌研究院 · 莫高窟第 257 窟", "claim": "257 窟建于北魏；中心塔柱窟，前部人字披顶、后部平棋顶；四壁上段天宫伎乐、中段千佛与故事、下段药叉；西壁中段绘九色鹿故事，横卷连环画，按两头开始、中间结束的顺序布局", "url": "https://www.dha.ac.cn/info/1425/3548.htm"}, {"label": "崇秀全 · 敦煌莫高窟第 257 窟壁画《鹿王本生》释读", "claim": "《敦煌学辑刊》2008 年第 1 期 101–109 页；图注：壁画，《鹿王本生》，北魏，敦煌莫高窟第 257 窟西壁中层，纵 96 cm，横 385 cm；摘要：外来佛教艺术逐渐形成印度、边疆、汉地等多种因素有机结合的中国化佛教艺术特征", "url": "https://ygx.sxu.edu.cn/db/%E6%9C%9F%E5%88%8A/dhxjk/dhxj2008/0801pdf/080111.pdf"}, {"label": "维基文库 · 支谦译《佛说九色鹿经》", "claim": "经文：溺人被鹿负出，鹿言“欲报恩者，莫得道我在此间”；夫人梦见九色鹿，欲得其皮作衣裘、角作拂柄；溺人应募告密，面上即生癞疮；鹿对王说“人无反覆，不如水中浮木也”；王放鹿去。引文据大正藏本转简体", "url": "https://zh.wikisource.org/wiki/%E4%BD%9B%E8%AA%AA%E4%B9%9D%E8%89%B2%E9%B9%BF%E7%B6%93_(%E6%94%AF%E8%AC%99%E8%AD%AF%E6%9C%AC%E4%B8%80)"}, {"label": "新浪科技（新华社、光明日报）· 我国专家探明敦煌壁画变色原因并非铅粉氧化", "claim": "2004 年 3 月 8 日：敦煌研究院美术所吴荣鉴说，变色的主要是人物肤色及近似色彩，由初绘的肉色变成黑色、铅灰色或褐色；南北朝至隋代初期多变成黑色或铅灰色，隋中期至元代多变成褐色；X 衍射分析指向朱丹及其调和色的氧化、植物颜料褪色、碱性土质催化", "url": "http://tech.sina.com.cn/other/2004-03-08/1808302365.shtml"}, {"label": "澎湃新闻 · 段文杰：敦煌九色鹿壁画的艺术特色", "claim": "段文杰：人物肉体的明暗晕染，白鼻梁、白眼眶、“小字脸”，是吸收传自西域的天竺遗法——凹凸法的新式样", "url": "https://m.thepaper.cn/newsDetail_forward_29504456"}, {"label": "npj Heritage Science · 莫高窟 254 窟北魏变色壁画的虚拟复原", "claim": "Bolong C. 等，Herit Sci 10, 164 (2022)：254 窟北魏（386–534）壁画变色、褪色严重；莫高窟壁画地仗为掺沙与麦草的粗泥层和掺麻、植物纤维的细泥层，其上为底层与颜料层；红褐底色主要为铅丹与密陀僧，部分底层为石膏", "url": "https://www.nature.com/articles/s40494-022-00785-4"}, {"label": "维基文库 · 《太平御览》卷六五八", "claim": "引《建康实录》：一乘寺，梁邵陵王纶造……寺门遍画凹凸花，代称张僧繇手迹，其花乃天竺遗法，朱及青绿所成，远望眼晕如凹凸，就视即平，世咸异之，乃名凹凸寺（维基文库本有 OCR 误字，已按通行本校）", "url": "https://zh.wikisource.org/wiki/%E5%A4%AA%E5%B9%B3%E5%BE%A1%E8%A6%BD/0658"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图 File:鹿王本生故事畫.jpg，6496 × 1114，公有领域；上游为 Google 艺术与文化资产，提供方佛光山佛陀纪念馆", "url": "https://commons.wikimedia.org/wiki/File:%E9%B9%BF%E7%8E%8B%E6%9C%AC%E7%94%9F%E6%95%85%E4%BA%8B%E7%95%AB.jpg"}, {"label": "佛光山佛陀纪念馆（Google 艺术与文化）· 鹿王本生", "claim": "Ruru Jataka，Mogao Cave 257，Northern Wei dynasty；提供方 Fo Guang Shan Buddha Museum", "url": "https://artsandculture.google.com/asset/%E9%B9%BF%E7%8E%8B%E6%9C%AC%E7%94%9F%E6%95%85%E4%BA%8B%E7%95%AB/cAF407gix6E1LA"}, {"label": "敦煌研究院 · 莫高窟第 254 窟", "claim": "254 窟建于北魏，隋代重修；北壁前部西侧绘尸毗王本生，南壁前部西侧绘萨埵太子本生；部分颜料已变色；明显受西域画风影响", "url": "https://www.dha.ac.cn/info/1425/3685.htm"}, {"label": "敦煌研究院 · 莫高窟第 285 窟", "claim": "285 窟北壁有西魏大统四年、五年（538、539）发愿文题记；南壁横幅《五百强盗成佛》画战争、受审施刑、剃度等场面；人物身体修长俊秀；西域与中原风格相结合", "url": "https://www.dha.ac.cn/info/1425/3698.htm"}, {"label": "敦煌研究院 · 莫高窟第 103 窟", "claim": "103 窟盛唐；东壁维摩诘手拿麈尾，身体微微前倾；线条流畅，是八世纪集体的成就", "url": "https://www.dha.ac.cn/info/1425/3626.htm"}, {"label": "敦煌研究院 · 莫高窟第 61 窟", "claim": "61 窟五代曹元忠开凿；西壁《五台山图》全图长 13.4 米，高 3.4 米，描绘山西太原经五台山至河北镇州的山川、寺院、城廓与巡礼场景", "url": "https://www.dha.ac.cn/info/1425/3588.htm"}, {"label": "维基共享资源 · 尸毗王本生图片文件页", "claim": "w1 图片文件及公有领域标注（来源页未写明拍摄者）", "url": "https://commons.wikimedia.org/wiki/File:Mogao_Cave_254,_Shibi_Jataka,_Northern_Wei_period.jpg"}, {"label": "维基共享资源 · 五百强盗成佛图片文件页", "claim": "w2 图片文件 6496 × 928，公有领域；上游佛光山佛陀纪念馆（Google 艺术与文化），截取右段", "url": "https://commons.wikimedia.org/wiki/File:%E4%BA%94%E7%99%BE%E5%BC%B7%E7%9B%9C%E6%88%90%E4%BD%9B.jpg"}, {"label": "维基共享资源 · 维摩诘像图片文件页", "claim": "w3 图片文件，扫描自苏立文《中国艺术》第 4 版（1999），公有领域", "url": "https://commons.wikimedia.org/wiki/File:Vimalakirti_debating_Manjusri,_Tang_Dynasty.jpg"}, {"label": "维基共享资源 · 五台山图图片文件页", "claim": "w4 图片文件 8409 × 2362，公有领域；上游佛光山佛陀纪念馆（Google 艺术与文化），截取中段", "url": "https://commons.wikimedia.org/wiki/File:%E8%8E%AB%E9%AB%98%E7%AA%9F%E4%BA%94%E8%87%BA%E5%B1%B1%E5%9C%96.jpg"}]};

