(window.EH_ROOMS=window.EH_ROOMS||{})["fokan"]={"id": "fokan", "zh": "佛龛", "lat": "Northern Wei", "yrs": "386 – 534 CE", "one": "一路东来的佛像，学者说它像南朝名士", "wall": "#4A3C30", "wallWhy": "墙色取北方石窟砂岩压暗后的暖褐：这一部的佛像，很多原本刻在砂岩山崖开出的石窟里，转场走过的那面长墙也是砂岩。颜色压深一档，让鎏金和铜绿都立得住。这龛金铜像前后左右都能看，本来没有框，所以本厅不加框，让它立在墙前。", "ink": "light", "frame": "none", "art": {"img": "main_cut.webp", "w": 896, "h": 2056, "who": "佚名北魏工匠", "whoLat": "Unknown Northern Wei artisans", "title": "《金铜弥勒佛龛》（造像）", "short": "《金铜弥勒佛龛》", "meta": ["北魏正光五年（524），鎏金铜", "高 76.8 cm，宽 40.6 cm，深 24.8 cm", "纽约，大都会艺术博物馆（38.158.1a–n）"], "credit": "大都会艺术博物馆开放获取, File:DP217575.jpg — 摄影 大都会艺术博物馆，CC0"}, "lede": "北魏正光五年（524）九月，一位父亲为死去的儿子造了这一龛金铜弥勒像，愿儿子和家中亲人永远与佛相会。", "work": "主尊弥勒立在莲座上，右手上举，左手垂下，馆方解作安抚信众、许其所愿的手势。他身后是镂空的背光，四周环绕着火焰和奏乐的飞天。两旁莲茎上各立一尊胁侍菩萨，脚边还有一对；再往外，四位穿俗装的供养人捧着供钵。前角立着两名执金刚力士，台下蹲着两只狮子。主尊脸长颈细，肩膀窄削，衣服却宽大，衣摆向两侧层层张开。", "quote": ["陆公参灵酌妙，动与神会，笔迹劲利，如锥刀焉。秀骨清像，似觉生动，令人懔懔若对神明。", "唐人张怀瓘评南朝画家陆探微，见张彦远《历代名画记》卷六"], "origin": "佛教在汉代已传入中国，但要到 4 世纪才开始大量造像。北魏皇室在都城平城（今山西大同）附近开凿云冈石窟，早期佛像照印度的范本雕成。孝文帝（471–499 在位）推行改制，494 年迁都洛阳，改说汉语、改穿汉服。佛像的样子也在变：云冈中期已见宽袍佛像，迁洛后成了主流。学者多认为，它借用了南朝士大夫的形象，身形清瘦，宽袍大带，后人概括为“秀骨清像”“褒衣博带”。这一龛造于迁都三十年后。", "traits": [["从犍陀罗到马图拉", "最早一批佛像出在今巴基斯坦的犍陀罗和印度北部的马图拉。犍陀罗借了希腊罗马的衣褶，佛像像披着厚重的长袍；马图拉把衣纹做得更抽象，身体更有力量。"], ["身瘦衣厚", "大都会博物馆的学者这样分辨：身体健壮、衣服贴身的，出自印度范本；身体清瘦、衣服厚重的，是中国的样式。许多造像两者兼有，这一龛主尊偏向后一种。"], ["褒衣博带", "“褒衣博带”原指宽袍阔带，是古代儒者的装束，《淮南子》里已有这个说法。学者借它形容北魏后期佛像的袈裟：做成中原士大夫那样宽袍博带的式样。"], ["为亲人造像", "北朝人常出资造像，为亡故或在世的亲人祈福，把发愿人、日期和心愿刻在像座或龛旁，相信这能积功德。龙门石窟留下约两千八百方碑刻题记，多有造像记。"]], "special": {"title": "装龛", "type": "assemble", "text": "这一龛不是一整块铸成的，而是由许多部件组装起来的，馆方编号从 a 排到 n。馆方现在的组合里，香炉后面的两尊小僧像，借自馆里另一龛年代相近的佛像。现在部件打散在案上：把它们一件件拖回原位，放准了会卡住，位置不对就滑开。装齐以后，和原作对照看看。部件怎样插接，本展只作示意。", "hints": {"start": "把案上的部件拖回佛龛", "startTouch": "按住一个部件，拖回佛龛", "pick": "拿起了：{name}", "near": "快到了，再往里一点", "snap": "卡住了：{name}", "wrong": "位置不对，滑开了", "order": "背光和主尊先装，别的才有地方插", "progress": "已装 {n} / {total} 件", "done": "装齐了", "compare": "和原作对照", "again": "打散，再装一次"}, "captions": {"mine": "你装的", "orig": "原作", "origSource": "《金铜弥勒佛龛》，北魏正光五年（524），大都会艺术博物馆", "note": "部件划分依大都会艺术博物馆说明；插接方式为本展示意", "borrowed": "借自另一龛（38.158.2f、g）"}, "img": "main.webp", "imgW": 1800, "imgH": 2400, "parts": [{"id": "base", "name": "四足方座", "label": "承托整龛的方座，四足落地", "box": [500, 1860, 760, 420], "order": 0}, {"id": "mandorla", "name": "背光", "label": "镂空举身背光，四周火焰与奏乐飞天", "box": [480, 230, 840, 1290], "order": 1, "count": 1}, {"id": "buddha", "name": "主尊弥勒", "label": "立在莲座上的弥勒", "box": [735, 940, 280, 760], "order": 2}, {"id": "bodhiSideL", "name": "胁侍菩萨（左）", "label": "立在左侧莲茎顶上", "box": [500, 1170, 120, 300], "order": 3}, {"id": "bodhiSideR", "name": "胁侍菩萨（右）", "label": "立在右侧莲茎顶上", "box": [1105, 1175, 130, 300], "order": 3}, {"id": "bodhiFootL", "name": "菩萨（左下）", "label": "主尊脚边，带头光", "box": [685, 1480, 90, 280], "order": 4}, {"id": "bodhiFootR", "name": "菩萨（右下）", "label": "主尊脚边，带头光", "box": [955, 1500, 100, 260], "order": 4}, {"id": "patronsL", "name": "供养人（左两位）", "label": "穿俗装，捧供钵", "box": [550, 1555, 110, 235], "order": 5}, {"id": "patronsR", "name": "供养人（右两位）", "label": "穿俗装，捧供钵", "box": [1100, 1545, 110, 245], "order": 5}, {"id": "guardL", "name": "执金刚力士（左）", "label": "守在前角", "box": [455, 1770, 150, 270], "order": 6}, {"id": "guardR", "name": "执金刚力士（右）", "label": "守在前角", "box": [1160, 1790, 110, 225], "order": 6}, {"id": "incense", "name": "香炉", "label": "莲座下正中", "box": [835, 1690, 100, 180], "order": 7}, {"id": "monkL", "name": "小僧像（左）", "label": "香炉后，借自另一龛", "box": [752, 1650, 50, 140], "order": 8, "borrowed": true}, {"id": "monkR", "name": "小僧像（右）", "label": "香炉后，借自另一龛", "box": [948, 1650, 55, 140], "order": 8, "borrowed": true}, {"id": "lionL", "name": "狮子（左）", "label": "蹲在左前足上，护法", "box": [460, 2030, 190, 230], "order": 9}, {"id": "lionR", "name": "狮子（右）", "label": "蹲在右前足上，护法", "box": [1050, 2040, 190, 210], "order": 9}], "note": "box = main.webp 像素 [x,y,w,h]（左上原点，1800×2400），目测估计，误差约 ±20 px，部件之间有重叠（背光在主尊后、力士与狮子上下相接）；做展项时请按 cut/ 抠图 1:1 核准。部件划分依馆方说明（主尊、背光与飞天、两对菩萨、四位供养人、两名执金刚力士、两只狮子、香炉、借来的两尊小僧像），不等于馆方 a–n 的实际分件。佛像不做变形，主尊整尊移动，不切分。"}, "works": [{"img": "w1.webp", "w": 718, "h": 1200, "who": "佚名犍陀罗雕塑家", "whoLat": "Unknown Gandharan sculptor", "title": "《立佛》", "meta": ["贵霜时期，150–200 年，片岩", "高 119.7 cm", "克利夫兰艺术博物馆（1972.43）"], "note": "出自今巴基斯坦犍陀罗；波浪卷发，袈裟厚如长袍。", "credit": "克利夫兰艺术博物馆开放获取, File:1972.43_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w2.webp", "w": 1100, "h": 1200, "who": "佚名马图拉雕塑家", "whoLat": "Unknown Mathura sculptor", "title": "《坐佛》", "meta": ["贵霜时期，3 世纪，砂岩", "63 × 58.5 cm", "克利夫兰艺术博物馆（1941.94）"], "note": "出自印度北部马图拉；头部已失，衣纹是一道道凸棱。", "credit": "克利夫兰艺术博物馆开放获取, File:1941.94_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w3.webp", "w": 1088, "h": 1200, "who": "佚名龟兹画工", "whoLat": "Unknown Kucha painter", "title": "《菩萨头像》（壁画残片）", "meta": ["600–650 年，壁画", "画面 16.8 × 15.5 cm", "克利夫兰艺术博物馆（1985.15）"], "note": "克孜尔石窟壁画；据题记，由德国吐鲁番考察队揭取带走。", "credit": "克利夫兰艺术博物馆开放获取, File:1985.15_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w4.webp", "w": 901, "h": 1200, "who": "佚名北魏雕塑家", "whoLat": "Unknown Northern Wei sculptor", "title": "《交脚弥勒菩萨》（造像）", "meta": ["北魏，约 470–480 年，砂岩，有彩绘残迹", "高 146.1 cm", "纽约，大都会艺术博物馆（22.134）"], "note": "馆方记原址为云冈石窟，尚待考证；1922 年购自巴黎。", "credit": "大都会艺术博物馆开放获取, File:DP170134.jpg — 摄影 大都会艺术博物馆，CC0"}], "chain": "之前：上一厅的九色鹿画在敦煌莫高窟的墙上，讲的是佛的前世。之后：洛阳南郊的龙门石窟，开凿最盛是 5 世纪末到 8 世纪中叶，佛像的样子还在变。下一厅离开佛堂，回到唐代人的日常。", "sources": [{"label": "大都会艺术博物馆 · 金铜弥勒佛龛藏品页", "claim": "Buddha Maitreya (Mile) Altarpiece，北魏正光五年（524），鎏金铜，高 76.8、宽 40.6、深 24.8 cm，Rogers Fund 1938，38.158.1a–n；馆方说明：弥勒为未来佛，下生人间；镂空背光环绕火焰与奏乐飞天；手势安抚信众、许其所愿；两尊胁侍菩萨立两侧，脚边另一对；四位俗装供养人捧供钵；执金刚力士守前角；台下两狮护法；座上刻铭记发愿人与日期，为亡子及亲属祈福；陈列中香炉后两尊小僧像借自 38.158.2（f、g）；铭文英译（Lippe 1961）：大魏正光五年九月十八日，新市县某人为亡子造弥勒像一躯，愿亡子与在家眷属永与佛会；来源 Abby Aldrich Rockefeller，1938 年售予大都会；馆方页面记为未陈列（Not on view），38.158.2 年代约 525–530", "url": "https://www.metmuseum.org/art/collection/search/42162"}, {"label": "大都会艺术博物馆 · 开放数据 API（佛龛）", "claim": "同上；isPublicDomain = true；主图 DP217575.jpg（3001 × 4000）", "url": "https://collectionapi.metmuseum.org/public/collection/v1/objects/42162"}, {"label": "大都会艺术博物馆 · 中国佛教造像（Denise Patry Leidy）", "claim": "“Works with powerful physiques and thin clothing derive from Indian prototypes, while sculptures that feature thin bodies with thick clothing evince a Chinese idiom. Many mix these visual traditions.”；佛教或早在公元前 2 世纪为中国所知，4 世纪前少见大规模造像", "url": "https://www.metmuseum.org/essays/chinese-buddhist-sculpture"}, {"label": "大都会艺术博物馆 · 南北朝时期（386–581）", "claim": "云冈石窟由北魏皇室在今山西大同附近开凿，造像照印度范本；早期“古拙”样式随南北交往增多而改变，孝文帝（471–499 在位）改制后尤甚；改制采用汉语、汉服与汉制，促成 6 世纪的艺术融合，见于龙门石窟样式", "url": "https://www.metmuseum.org/essays/period-of-the-northern-and-southern-dynasties-386-589"}, {"label": "王霞 · “秀骨清像”“褒衣博带”：论北魏石窟汉化造像样式的确立及成因", "claim": "《南京艺术学院学报（美术与设计版）》2012 年第 6 期，96–100 页：北魏石窟造像由西域样式发展为以“秀骨清像”“褒衣博带”为特征的中国化样式；“秀骨清像”风格源于南朝都城建康，本为宫廷画家的绘画风格；引《历代名画记》张怀瓘评陆探微原文；“褒衣博带”原为古代儒者装束，引《淮南子·氾论训》“岂必褒衣博带”；“褒衣博带”佛装在云冈中期已出现，有纪年的早期实例为云冈第 11 窟太和十三年（489）铭龛，迁洛后在龙门完全成形", "url": "https://ygx.sxu.edu.cn/db/%E6%9C%9F%E5%88%8A/njysxyxb-msysjb/njys2012/1206pdf/120627.pdf"}, {"label": "张彦远《历代名画记》卷六 · 陆探微条（维基文库）", "claim": "张怀瓘云：陆公参灵酌妙，动与神会，笔迹劲利，如锥刀焉。秀骨清像，似觉生动，令人懔懔，若对神明（维基文库繁体本卷第六，2026-09-30 核对；中国哲学书电子化计划亦收）", "url": "https://zh.wikisource.org/zh-hant/%E6%AD%B7%E4%BB%A3%E5%90%8D%E7%95%AB%E8%A8%98/%E5%8D%B7%E7%AC%AC%E5%85%AD"}, {"label": "大英百科全书 · 北魏孝文帝", "claim": "孝文帝 471 年即位，迁都洛阳，定汉语为朝廷官方语言，令贵族改穿汉服、改汉姓；迁都年份通行记为 494 年（太和十八年）", "url": "https://www.britannica.com/biography/Xiaowendi"}, {"label": "联合国教科文组织 · 龙门石窟", "claim": "龙门石窟在洛阳南郊，2300 多个窟龛、近 11 万尊造像、2800 方碑刻题记（“2,800 inscriptions carved on steles”）；开凿最盛在 5 世纪末到 8 世纪中叶", "url": "https://whc.unesco.org/en/list/1003/"}, {"label": "克利夫兰艺术博物馆 · 犍陀罗立佛", "claim": "Standing Buddha，150–200 CE，巴基斯坦犍陀罗，贵霜时期，片岩，高 119.7 cm，1972.43，CC0；馆方：融合地中海与南亚，最早一批表现佛像平静面容、浓密波浪卷发、厚重如罗马长袍的袈裟；来源 B. J. Lester-Smith（维也纳），1972 年售予克利夫兰", "url": "https://clevelandart.org/art/1972.43"}, {"label": "克利夫兰艺术博物馆 · 马图拉坐佛", "claim": "Seated Buddha，3 世纪（200s CE），印度北部马图拉，贵霜时期，砂岩，63 × 58.5 cm，1941.94，CC0；馆方：马图拉工匠重新诠释犍陀罗流行的希腊罗马式衣褶，衣纹更抽象，佛显出超人的力量；来源 Heeramaneck Galleries（纽约），1941 年售予克利夫兰；图中头部已失", "url": "https://clevelandart.org/art/1941.94"}, {"label": "克利夫兰艺术博物馆 · 克孜尔菩萨头像壁画残片", "claim": "Fragment with a Head of Bodhisattva，600–650，中亚克孜尔，壁画，画面 16.8 × 15.5 cm、整体 23.2 × 20.6 cm，1985.15，CC0；残片题记（馆方铭文栏）：“Zur Erinnerung”“Albert von Le Coq”“9/12/19”“Kizil”“the fourth expedition”“cave no. 60”；来源 Galerie Koller（苏黎世）、John Suidmak（伦敦），1984 年苏黎世拍卖", "url": "https://clevelandart.org/art/1985.15"}, {"label": "大都会艺术博物馆 · 交脚弥勒菩萨藏品页", "claim": "Bodhisattva (Maitreya) with crossed ankles，约 470–480 年，砂岩有彩绘残迹，高 146.1 cm，Rogers Fund 1922，22.134，CC0；馆方：最接近云冈第 5、25（?）窟的弥勒像；原址据卡片记为云冈第 25 窟，“尚需进一步考证”；来源 Paul Mallon（巴黎），1922 年售予大都会", "url": "https://www.metmuseum.org/art/collection/search/42711"}]};

;
(window.EH_ROOMS=window.EH_ROOMS||{})["sancai"]={"id": "sancai", "zh": "三彩", "lat": "Tang Dynasty", "yrs": "618 – 907 CE", "one": "釉在窑火里自己往下流，流出一匹唐马", "wall": "#2A211B", "wallWhy": "墙色取近墨的深赭：这匹马原是随葬的明器，本该待在墓室的黑暗里；压暗的暖褐也让琥珀、绿、乳白三种釉色各自立得住。马连踏板是一件立体的器物，四面都能看，本来没有框，所以本厅不加框，让它立在墙前。", "ink": "light", "frame": "none", "art": {"img": "cut/main_cut.webp", "w": 1771, "h": 1825, "who": "佚名唐代陶工", "whoLat": "Unknown Tang potter", "title": "《三彩马》（明器）", "short": "《三彩马》", "meta": ["唐，7 世纪末 – 8 世纪，三彩釉陶", "高 76.8 cm", "克利夫兰艺术博物馆（1955.295）"], "credit": "克利夫兰艺术博物馆开放获取, File:1955.295_full.tif — 摄影 克利夫兰艺术博物馆，CC0"}, "lede": "7 世纪末到 8 世纪，一位地位很高的唐人下葬，墓里放进一整队仪仗俑，这匹马是其中之一。", "work": "一匹马立在长方形踏板上，四蹄站稳，脖子高高挺起，头微微收着。马身是琥珀色的釉，鬃毛、小腿和上卷的短尾是乳白的；笼头、胸带、鞦带上挂着绿釉杏叶。鞍上搭一块浅黄的鞍袱，釉在上面垂成一道道竖纹。再看四条腿：琥珀釉越过膝盖往下淌，在白腿上拖出几道细细的釉泪，停在半路，没有流到蹄上。", "quote": ["凡丧葬则供其明器之属……三品以上九十事，五品以上六十事，九品已上四十事。当圹、当野、祖明、地轴、䩥马、偶人，其高各一尺。", "《唐六典》卷二十三，将作监甄官署条"], "origin": "绿釉、褐釉陶汉代就有，只是很少同用在一件上。到 7 世纪末，北方的窑场把绿、黄褐、乳白放到同一件器物上，主要在河南巩县（今巩义）和长安附近的铜川烧造；馆方认为这匹马可能出自河南。此后约七十年是三彩俑的盛期，绝大多数做成明器随葬。755 年安史之乱起，三彩俑几乎停烧。“唐三彩”这个名字不见于古书：清末修陇海铁路，洛阳邙山一带唐墓被毁，三彩流入古董市场，才有了这个叫法。", "traits": [["釉自己流", "三彩的釉常常只是大致刷上、泼上，不严格照着器物的分块走。低温铅釉在窑里熔开往下淌，颜色在交界处彼此渗开，流成什么样由火来定。"], ["两次入窑", "一般先把白胎素烧到 1000 ℃ 以上，冷却后上釉，再用低得多的温度釉烧。铅是助熔剂，铜呈绿，铁呈黄褐，少数还用昂贵的钴呈蓝。"], ["先游街，再入墓", "克利夫兰艺术博物馆的说明：明器下葬之前，先随送葬的队伍抬过街道。它们为死者备下来世所需，也表现子孙的孝心、财力与权势。"], ["丰满的马", "一般认为，唐代的马和人都以丰满为美：三彩马胸宽臀圆、脖颈挺拔，腿却细而有力。唐代还从西域引进良马，出行、仪仗和马球场上都少不了。"]], "special": {"title": "击鞠", "type": "polo", "text": "马上打球，唐人叫“打毬”，古书里也称“击鞠”，在都城长安很风行，女子也换上男装下场。它从哪里来，说法不一：有学者认为源自波斯，经西域传来；有人认为来自吐蕃；也有人据曹植“连翩击鞠壤”的诗句，认为汉末已有。本展不作裁决。现在骑上一匹马：按住催马，往哪边拖马就往哪边转；马有惯性，跑得越快越转不过急弯。到球跟前松手挥杖，挥得早晚和马跑多快，决定球往哪飞、飞多远。一局打完，再看看墙上这匹马。", "hints": {"start": "按住催马，往哪边拖，马就往哪边转", "startTouch": "手指按住催马，往哪边拖，马就往哪边转", "gallop": "马跑起来了", "turnWide": "跑得太快，转不过这个弯", "slowDown": "松开一点，让马慢下来再转", "near": "球就在马前，松手挥杖", "swing": "挥杖", "early": "挥早了，杖头扫空", "late": "挥晚了，球从马蹄边滚过去", "hit": "击中了", "far": "马跑得快，这一杖打得远", "soft": "马太慢，球只滚出一小段", "goal": "进门了", "wide": "偏了，没进门", "time": "还剩 {s} 秒", "end": "一局打完", "compare": "和墙上的马并排看", "again": "再打一局", "out": "球飞出了场外", "toWall": "球飞出场外，落到了墙上那匹马的踏板边：把它抓回场上，或等它自己飞回来", "toWallTouch": "球飞出场外，落到了墙上那匹马的踏板边：按住它甩回场上，或等它自己飞回来", "keys": "键盘：按住 ↑ 或 W 催马，A、D 转向，松开 ↑ 或按回车挥杖"}, "captions": {"score": "进门 {n} 球", "shots": "击球 {n} 次", "best": "最远一杖 {d} 步", "stick": "球杖：杖头弯如新月", "mine": "你骑的马", "orig": "墙上的三彩马", "origSource": "《三彩马》，唐，克利夫兰艺术博物馆", "verdict": "唐人把这样的马烧进明器，陪主人入墓", "ref": "马的毛色、鬃尾、鞍具照墙上这匹三彩马；骑手衣着参照章怀太子墓《马球图》，都是本展示意"}, "img": "main.webp", "imgW": 2400, "imgH": 2264, "cut": "cut/main_cut.webp", "cutBox": [367, 281, 1771, 1825], "facing": "left", "colors": {"amber": "#B17025", "green": "#5B6F3D", "cream": "#EAD8B9", "strap": "#2B211A"}, "horse": {"body": "琥珀釉", "mane": "乳白，披在近侧", "tail": "乳白短尾，梢头上卷，根部有绿釉", "legs": "膝下乳白，琥珀釉泪沿腿下淌；蹄琥珀釉", "tack": "笼头、胸带、鞦带为黑褐细带，挂绿釉杏叶；鞍桥前高后低，鞍下垂浅黄鞍袱"}, "points": {"eye": [640, 418], "muzzleTip": [378, 600], "poll": [706, 345], "withers": [1150, 720], "saddlePommel": [1205, 638], "saddleCantle": [1455, 715], "saddleSeat": [1370, 792], "tailRoot": [1935, 862], "tailTip": [2127, 930], "hoofFrontFar": [1010, 1940], "hoofFrontNear": [1125, 2020], "hoofHindFar": [1480, 1893], "hoofHindNear": [1640, 1985], "floorY": 2086}, "note": "坐标为 main.webp 像素（2400×2264）；points 取自 cut/layers.json；colors 为 glaze.webp 遮罩内 main.webp 的中位色（strap 为目测取样）；骑手与球杖原作上没有，为本展示意"}, "works": [{"img": "w1.webp", "w": 854, "h": 1200, "who": "佚名唐代陶工", "whoLat": "Unknown Tang potter", "title": "《兽面镇墓兽》（明器）", "meta": ["唐，8 世纪初，三彩釉陶", "92.3 × 43.8 × 41.9 cm", "克利夫兰艺术博物馆（2000.118.1）"], "note": "守在墓门口，驱邪，也不让死者的魂魄游走。", "credit": "克利夫兰艺术博物馆开放获取, File:2000.118.1_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w2.webp", "w": 1200, "h": 1153, "who": "佚名唐代工匠", "whoLat": "Unknown Tang artisan", "title": "《金银平脱花鸟镜》", "meta": ["唐，8 世纪，铜镜，漆地嵌金银片", "直径 19.2 cm", "克利夫兰艺术博物馆（1973.74）"], "note": "漆地上嵌薄金银片，花鸟带着波斯、中亚的味道。", "credit": "克利夫兰艺术博物馆开放获取, File:1973.74_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w3.webp", "w": 1200, "h": 445, "who": "颜真卿", "whoLat": "Yan Zhenqing, 709 – 785", "title": "《祭侄文稿》", "meta": ["唐乾元元年（758），纸本行书", "本幅 28.2 × 77 cm", "台北，台北故宫博物院（故书 00006000000）"], "note": "安史之乱中侄子殉难，他写下祭文草稿，涂改满纸。", "credit": "Wikimedia Commons, File:祭侄文稿卷.唐.顏真卿.纸本行书.台北故宫博物院藏 (cropped).tif — 来源 台北故宫博物院，公有领域"}, {"img": "w4.webp", "w": 1200, "h": 901, "who": "韩干", "whoLat": "Han Gan, active c. 742 – 756", "title": "《照夜白图》", "meta": ["唐，约 750 年，纸本水墨", "画心 30.8 × 34 cm", "纽约，大都会艺术博物馆（1977.78）"], "note": "唐玄宗的坐骑拴在桩上，身子滚圆，昂首嘶鸣。", "credit": "大都会艺术博物馆开放获取, File:DP153705.jpg — 摄影 大都会艺术博物馆，CC0"}], "chain": "之前：东汉的说唱俑同样是随葬的明器；上一厅北魏的佛像，还是秀骨清像的清瘦样子。之后：三彩的做法传到新罗和日本，有了新罗三彩、奈良三彩。唐亡以后进入五代，下一厅看一场画里的夜宴。", "sources": [{"label": "克利夫兰艺术博物馆 · 三彩马藏品数据", "claim": "主作品：Horse，late 600s–800，China, probably Henan province, Tang dynasty (618–907)；glazed earthenware, sancai (three-color) ware；Overall 76.8 cm；Anonymous Gift，1955.295；CC0；馆方说明：属一组表现仪仗行列的俑，同入一位高级人物的墓；马是来世必需的交通；绿、琥珀、透明白的三彩釉显示墓主地位高；图像 1955.295_full.tif 6361×6000", "url": "https://openaccess-api.clevelandart.org/api/artworks/1955.295"}, {"label": "克利夫兰艺术博物馆 · 三彩马藏品页", "claim": "同上，馆方网页", "url": "https://www.clevelandart.org/art/1955.295"}, {"label": "维基文库 · 《唐六典》卷二十三", "claim": "将作监甄官署：凡丧葬则供其明器之属（别敕葬者供，余并私备），三品以上九十事，五品以上六十事，九品已上四十事；当圹、当野、祖明、地轴、䩥马、偶人，其高各一尺；其余音声队与僮仆之属……以瓦、木为之，其长率七寸（引文省去夹注，以省略号标出）", "url": "https://zh.wikisource.org/zh-hans/%E5%94%90%E5%85%AD%E5%85%B8/%E5%8D%B723"}, {"label": "大英百科全书 · 中国陶瓷：隋唐", "claim": "7 世纪末至 8 世纪，北方窑工主要在长安附近的铜川和河南巩县烧造三彩器与俑：施化妆土，罩低温铅釉，以铜或铁着色成绿、黄、褐，偶有蓝，色彩任其交融、流淌", "url": "https://www.britannica.com/art/Chinese-pottery/The-Sui-581-618-and-Tang-618-907-dynasties"}, {"label": "大英百科全书 · 三彩", "claim": "三彩：以绿、黄、褐等低温铅釉装饰的中国陶器，唐代发展于中国北方", "url": "https://www.britannica.com/art/sancai-ware"}, {"label": "英文维基百科 · 三彩", "claim": "三彩为铅釉陶，需两次烧成；铜呈绿、铁呈黄褐，进口钴呈蓝、较贵；釉在交界处互相流渗，多数器物施色松散甚至随意，常不依浮雕与身体分块；汉代已有绿釉、褐釉而很少同用；全套三彩出现于 7 世纪末前不久，约 70 年后，随 755 年安史之乱，三彩俑几乎完全停烧；影响新罗、奈良", "url": "https://en.wikipedia.org/wiki/Sancai"}, {"label": "中文维基百科 · 唐三彩", "claim": "唐三彩二次烧成：白色黏土胎素烧 1000–1100 ℃，再施釉以 850–950 ℃ 釉烧；铜绿、铁赭黄、钴蓝，铅为助熔剂；“唐三彩”一词不见于古代文献，清末修陇海铁路毁洛阳邙山唐墓后大量出土；一般认为肥壮的马、骆驼与丰满的女俑反映唐人审美；影响新罗三彩、奈良三彩", "url": "https://zh.wikipedia.org/wiki/%E5%94%90%E4%B8%89%E5%BD%A9"}, {"label": "克利夫兰艺术博物馆 · 兽面镇墓兽", "claim": "Tomb Guardian with Animal Head，early 700s，probably Shaanxi, Xi'an；glazed earthenware, sancai；92.3 × 43.8 × 41.9 cm；2000.118.1；CC0；馆方说明：镇守墓门、驱邪，也不让死者魂魄游走；明器入墓前随送葬行列抬过街道，为死者备来世所需，也表现子孙的孝心、财力与权势", "url": "https://www.clevelandart.org/art/2000.118.1"}, {"label": "克利夫兰艺术博物馆 · 金银平脱花鸟镜", "claim": "Mirror with Phoenixes, Birds, Butterflies, and Floral Sprays，700s；bronze with silver and gold inlaid lacquer；直径 19.2 cm；1973.74；CC0；馆方说明：漆地嵌极薄金银片，花卉与衔枝凤鸟有明显的波斯、中亚风味，此类奢侈品曾为唐帝的外交礼物", "url": "https://www.clevelandart.org/art/1973.74"}, {"label": "台北故宫博物院 · 唐颜真卿祭侄文稿卷", "claim": "唐颜真卿祭姪文稿卷，行书，纸本，本幅 28.2 × 77 cm，故书00006000000；释文“维乾元元年岁次戊戌九月庚午朔三日壬申……祭于亡姪赠赞善大夫季明之灵”，文中多处涂去改写", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/3?dep=P"}, {"label": "台北故宫博物院 · 精选赏析：祭侄文稿", "claim": "颜真卿（709–785）；安史之乱中堂兄颜杲卿守常山，城破，杲卿与子季明罹难；本卷为起草文稿，删改涂抹可见其情怀起伏", "url": "https://theme.npm.edu.tw/selection/Article.aspx?sNo=04001003"}, {"label": "维基共享资源 · 祭侄文稿图片文件页", "claim": "图片文件及许可（公有领域，来源台北故宫博物院数位典藏）", "url": "https://commons.wikimedia.org/wiki/File:%E7%A5%AD%E4%BE%84%E6%96%87%E7%A8%BF%E5%8D%B7.%E5%94%90.%E9%A1%8F%E7%9C%9F%E5%8D%BF.%E7%BA%B8%E6%9C%AC%E8%A1%8C%E4%B9%A6.%E5%8F%B0%E5%8C%97%E6%95%85%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%99%A2%E8%97%8F_(cropped).tif"}, {"label": "大都会艺术博物馆 · 韩干《照夜白图》", "claim": "Night-Shining White，Han Gan（active ca. 742–756），ca. 750，Handscroll; ink on paper，Image 30.8 × 34 cm，1977.78，Purchase, The Dillon Fund Gift, 1977，公有领域（大都会开放 API）", "url": "https://www.metmuseum.org/art/collection/search/39901"}, {"label": "英文维基百科 · 照夜白图", "claim": "画的是唐玄宗（712–756 年在位）的坐骑，拴在桩上；约 750 年；身子滚圆、腿细，昂头张口似嘶鸣；1977 年入藏大都会", "url": "https://en.wikipedia.org/wiki/Night-Shining_White"}, {"label": "英文维基百科 · 马球", "claim": "马球大概沿丝绸之路传入中国，在唐都长安很流行，女子也打，须穿男装；英文 polo 出自巴尔蒂语“球”，与藏语 pulu 同源", "url": "https://en.wikipedia.org/wiki/Polo"}, {"label": "中文维基百科 · 马球", "claim": "马球古称“击鞠”，风行于唐代；有说始于汉代，引曹植《名都篇》，但把诗句误作“连骑击鞠壤”（通行本作“连翩击鞠壤”，见维基文库）；起源尚无定论，学者普遍认为可追溯到波斯，再传入吐蕃、中国等地", "url": "https://zh.wikipedia.org/wiki/%E9%A9%AC%E7%90%83"}, {"label": "研究之门 · 马球起源讨论（论文）", "claim": "关于马球起源的几种说法：波斯说、吐蕃说与中国本土说", "url": "https://www.researchgate.net/publication/382404247_Discussion_on_the_Origin_of_Polo"}, {"label": "陕西省人民政府 · 章怀太子墓《马球图》", "claim": "章怀太子李贤墓（706 年）墓道壁画《马球图》，1971 年出土，骑手着窄袖袍、戴幞头，持新月形球杖（展项骑手衣着与球杖的参照）", "url": "https://en.shaanxi.gov.cn/as/photos/201807/t20180720_1596344_wap.html"}, {"label": "英文维基百科 · 刘庭训墓三彩俑", "claim": "大英博物馆藏刘庭训（728 年卒）墓三彩俑一组 13 件（文中说唐代引进外来良马，也用于马球）：镇墓兽、天王、文武官、马、骆驼与牵马驼的俑，成组入葬；大型俑分件模制，再以泥浆粘合", "url": "https://en.wikipedia.org/wiki/Tang_dynasty_tomb_figures_of_Liu_Tingxun"}, {"label": "维基文库 · 曹植《名都篇》", "claim": "通行本诗句作“连翩击鞠壤，巧捷惟万端”，在“归来宴平乐”的宴饮之后；“鞠壤”是否指马球，学者看法不一", "url": "https://zh.wikisource.org/wiki/%E5%90%8D%E9%83%BD%E7%AF%87"}, {"label": "维基文库 · 封演《封氏闻见记》卷六“打毬”", "claim": "唐人封演立“打毬”条：唐太宗说“闻西蕃人好为打毬”；景龙中吐蕃使者在梨园与唐人对打，临淄王（玄宗）上场；开元、天宝中玄宗屡观打毬——唐人称马球为“打毬”", "url": "https://zh.wikisource.org/wiki/%E5%B0%81%E6%B0%8F%E8%81%9E%E8%A6%8B%E8%A8%98/%E5%8D%B7%E5%85%AD"}, {"label": "法国吉美国立亚洲艺术博物馆 · 女子马球俑", "claim": "约 750 年；馆方说明：马球（jiqiu）似经与波斯世界的往来传入唐廷；女骑手穿短袍、长裤、长靴，梳小髻", "url": "https://www.guimet.fr/en/our-collections/china/female-polo-player"}, {"label": "澎湃新闻 · 孙新民《洛阳唐三彩的考古学观察》", "claim": "河南省文物考古研究所前所长孙新民：1905–1909 年修陇海铁路开封至洛阳段，毁洛阳北邙山唐墓，三彩出土，古玩商运往北京，私下称“唐三彩”；安史之乱后墓葬中三彩数量急减，三彩俑类基本消失", "url": "https://www.thepaper.cn/newsDetail_forward_15312584"}]};

;
(window.EH_ROOMS=window.EH_ROOMS||{})["yeyan"]={"id": "yeyan", "zh": "夜宴", "lat": "Southern Tang", "yrs": "937 – 975 CE", "one": "满堂在听琵琶，主人似有心事", "wall": "#201A16", "wallWhy": "墙色取画里床榻、几案的黑漆，压成近墨的暖褐：这是一场夜里的宴会，屏风、床榻都是深色的，宾客的青黑衣衫和女伎的浅色衣裙靠它衬出来。手卷本来平放在案上从右往左展开看，所以本厅不加框，也不仿造它的装裱，只挂画心，照原样横陈。", "ink": "light", "frame": "none", "art": {"img": "t_win.webp", "w": 2600, "h": 1332, "who": "顾闳中（传）", "whoLat": "Gu Hongzhong, active 10th century", "title": "《韩熙载夜宴图》", "short": "《韩熙载夜宴图》", "meta": ["宋摹本，原作五代南唐，绢本设色", "28.7 × 335.5 cm", "北京，故宫博物院（新00147326）"], "credit": "Wikimedia Commons, File:韩熙载夜宴图.tif — 来源 书格，公有领域"}, "lede": "五代十国时，江南的南唐朝廷里有一位大臣叫韩熙载，家里常开夜宴。这一卷画的就是他家的一夜。", "work": "手卷从右往左展开，屏风和床榻把一夜隔成五段。卷首“听乐”：李家明的妹妹抱着琵琶弹奏，满座宾客都转向她；戴高帽、留长髯的韩熙载坐在榻上，身旁穿红袍的是状元郎粲。往左依次是观舞、暂歇、清吹、散宴，韩熙载每段都在：亲手擂鼓，洗手歇息，解衣盘坐听吹奏，最后执鼓槌送客。满堂热闹，他脸上却少有笑意。", "quote": ["乃命闳中夜至其第，窃窥之，目识心记，图绘以上之。", "《宣和画谱》卷七，北宋宣和年间编"], "origin": "韩熙载（902–970）生在北方，后唐时中过进士，父亲被杀后南奔江南，后来在南唐做官。他几次上书论北方的局势，都没有被采纳。晚年他官至侍郎，却蓄养歌伎、夜夜宴饮，有记载说他是有意放纵，以求自保。上面那段引文是北宋《宣和画谱》的说法；《五代史补》另说，南唐国主命画师把他的宴饮画出来赐给他，让他自愧。两说都出自后世，本展不作裁决。顾闳中的原作已失，故宫博物院认为眼前这卷当是南宋孝宗至宁宗朝（1163–1224）的摹本。", "traits": [["画出一个人的心事", "画里韩熙载的长髯、高帽与文献记载相合。故宫的说明指出，他擂鼓时双目凝视，听吹奏时心不在焉：画家画的不只是相貌，还有这个人的心事。"], ["屏风分段", "全卷像连环画，一段一个情节，每段用屏风、床榻隔开；又有人物隔着屏风与另一边招呼，把相邻两段连起来，五段合成完整的一夜。"], ["南唐画院", "南唐宫廷设有画院，顾闳中、周文矩都是待诏，专画人物。据记载，周文矩也奉命画过韩熙载夜宴，但没有流传下来，今天只剩顾闳中这一本，也是摹本。"], ["艳而不俗", "女伎的素妆艳服，衬着男宾青黑色的衣衫；几案床榻漆黑沉厚，帘幕、帐幔、枕席上又有细碎的花纹。颜色浓丽，整体却显得清雅，故宫说它“绚中出素”。"]], "special": {"title": "屏风移步", "type": "screens", "text": "这一卷用屏风、床榻把一夜分成五段：听乐、观舞、暂歇、清吹、散宴。拖动屏风，像推开一扇扇门，一段一段往里走；屏风有分量，推得快会滑过头。每一段里，韩熙载都在，衣着和神情却一直在变。在人群里把他找出来：戴高帽、留长髯的那一位。找到了，那一段就亮起来，旁边一行小字说他此刻在做什么。五段都找齐，再把他的五张脸并排看。", "hints": {"start": "拖动屏风，推开这一夜的第一段", "startTouch": "手指按住屏风，往一边推开", "heavy": "屏风有分量，慢一点推", "overshoot": "推过头了，往回拉一点", "find": "在这一段里找出韩熙载", "findTouch": "在这一段里找出韩熙载，点他一下", "look": "找戴高帽、留长髯的那一位", "miss": "不是他，再看看", "found": "找到了", "next": "推开下一扇屏风", "progress": "已找到 {n} / 5", "done": "五段都找齐了", "compare": "把他的五张脸并排看", "again": "合上屏风，从头再走一遍"}, "captions": {"facesTitle": "同一个人，五种神情", "facesNote": "五张脸都取自这一卷，从右往左依次是听乐、观舞、暂歇、清吹、散宴", "verdict": "五种神情里，看得出他的心思在哪里吗？", "source": "传顾闳中《韩熙载夜宴图》（宋摹本），故宫博物院"}, "sections": [{"id": "tingyue", "label": "听乐", "box": [12330, 0, 3670, 1358], "scene": "李家明的妹妹弹琵琶，满座宾客侧耳在听", "hxz": {"figure": [14504.52, 218.32, 320.65, 641.31], "face": [14610.27, 387.86, 90.4, 98.93], "caption": "坐在榻上，听人弹琵琶"}}, {"id": "guanwu", "label": "观舞", "box": [9830, 0, 2500, 1358], "scene": "家伎王屋山跳六幺舞，德明和尚拱手背立", "hxz": {"figure": [11615.21, 40.93, 317.24, 999.49], "face": [11698.11, 192.05, 102.34, 92.1], "caption": "亲手擂羯鼓，为六幺舞助兴"}}, {"id": "xiuxi", "label": "暂歇", "box": [6840, 0, 2990, 1358], "scene": "众人散坐，侍女捧盆送水", "hxz": {"figure": [7651.37, 341.12, 337.71, 532.15], "face": [7772.81, 458.81, 76.75, 98.93], "caption": "坐在床榻上歇息，正在洗手"}}, {"id": "qingchui", "label": "清吹", "box": [3470, 0, 3370, 1358], "scene": "五位女伎并坐吹奏", "hxz": {"figure": [6065.15, 129.63, 358.18, 764.11], "face": [6290.64, 290.3, 97.22, 90.4], "caption": "解衣盘坐椅上，听女伎合奏"}}, {"id": "songbie", "label": "散宴", "box": [0, 0, 3470, 1358], "scene": "宾客与女伎隔着屏风说笑", "hxz": {"figure": [1193.93, 54.58, 347.94, 1132.53], "face": [1312.64, 237.76, 71.64, 92.1], "caption": "手持鼓槌，送别宾客"}}], "screens": [{"id": "pine_screen", "between": ["qingchui", "songbie"], "box": [3080, 0, 790, 1270], "note": "两根青柱夹一扇松石屏；柱前立一男宾，屏后露一女伎"}, {"id": "tall_screen", "between": ["xiuxi", "qingchui"], "box": [6760, 0, 680, 1350], "note": "一扇青绢高屏（钤乾隆“古稀天子”圆印、“太上皇帝”大方印），带黑色屏座"}, {"id": "bed_screen", "between": ["xiuxi"], "box": [7400, 0, 1960, 1300], "note": "休憩段的床榻与围屏、红帐"}, {"id": "pillar_screen", "between": ["tingyue", "guanwu"], "box": [12300, 0, 120, 1230], "note": "一根青柱加屏座，柱后是画着枯树山石的屏风"}, {"id": "couch_screen", "between": ["tingyue"], "box": [14040, 0, 1410, 1250], "note": "听乐段韩熙载坐的大榻（黑漆围板）"}], "faces": ["cut/hr/face_tingyue.webp", "cut/hr/face_guanwu.webp", "cut/hr/face_xiuxi.webp", "cut/hr/face_qingchui.webp", "cut/hr/face_songbie.webp"], "note": "坐标为 main.webp 像素（16000 × 1358），box 为 [x, y, w, h]；手卷右→左读，sections 按右→左排列。段名依故宫博物院（听乐、观舞、暂歇、清吹、散宴）；id 与 cut/layers.json 一致（xiuxi = 暂歇，songbie = 散宴）。hxz.caption 是竖排小字，措辞取自故宫藏品说明。"}, "works": [{"img": "w1.webp", "w": 1200, "h": 636, "who": "阎立本", "whoLat": "Yan Liben, d. 673", "title": "《步辇图》（局部）", "meta": ["唐，绢本设色", "38.5 × 129 cm", "北京，故宫博物院（新00119106）"], "note": "唐太宗坐在步辇上，接见吐蕃使者禄东赞。", "credit": "Wikimedia Commons, File:Buliantu.jpg — 来源 中文维基百科，公有领域"}, {"img": "w2.webp", "w": 1200, "h": 374, "who": "张萱（原作）", "whoLat": "Zhang Xuan, active 8th century", "title": "《虢国夫人游春图》", "meta": ["宋摹本，原作唐，绢本设色", "51.8 × 148 cm", "沈阳，辽宁省博物馆"], "note": "八骑九人，杨贵妃的姐姐虢国夫人盛装出游。", "credit": "Wikimedia Commons, File:虢国夫人游春图.jpg — 公有领域"}, {"img": "w3.webp", "w": 1200, "h": 1060, "who": "周文矩（原作，传）", "whoLat": "Zhou Wenju, c. 907 – 975", "title": "《宫中图》（局部）", "meta": ["南宋摹本，1140 年以前，绢本水墨淡设色", "画心 28.5 × 168.6 cm", "克利夫兰，克利夫兰艺术博物馆（1976.1）"], "note": "卷首两位宫中女子奏乐，右边一人弹琵琶。", "credit": "克利夫兰艺术博物馆开放获取, File:1976.1_alt2_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w4.webp", "w": 1200, "h": 689, "who": "周文矩（传）", "whoLat": "Zhou Wenju, c. 907 – 975", "title": "《重屏会棋图》", "meta": ["宋摹本，原作五代南唐，绢本设色", "40.3 × 70.5 cm", "北京，故宫博物院（新00146475）"], "note": "南唐中主李璟看弟弟们下棋，身后屏风里又画着屏风。", "credit": "Wikimedia Commons, File:周文矩重屏会棋图卷.png — 来源 故宫博物院，公有领域"}], "chain": "之前：三彩马是唐墓里的明器；琵琶一类乐器经西域传入，到唐代已是宫廷宴乐里常见的声音。南唐承接唐的乐舞宴饮，到了江南更显精致。下一厅，听乐段琵琶女身后屏风上的山石树木走了出来，成了画的主角。", "sources": [{"label": "故宫博物院 · 顾闳中韩熙载夜宴图卷", "claim": "文物号 新00147326；五代顾闳中作（宋摹本），绢本设色，纵 28.7、横 335.5 cm；本幅无款；《宣和画谱》“命闳中夜至其第，窃窥之，目识心记，图绘以上之”与《五代史补》“命待诏画为图以赐之，使其自愧”两说；周文矩也曾作《韩熙载夜宴图》，今仅存顾本；全图分听乐、观舞、暂歇、清吹、散宴五段：听乐韩熙载与状元郎粲坐床榻上，听教坊副使李家明之妹弹琵琶；观舞王屋山跳六幺舞，韩熙载亲擂羯鼓，德明和尚拱手背立；暂歇韩与家伎坐床上休息、净手；清吹韩解衣盘坐椅上，欣赏五个歌女合奏；散宴韩手持鼓槌送别；每段以屏风隔扇分隔又相互联结；长髯、高帽与文献相合；擂鼓时双目凝视、面不露笑，听清吹时漫不经心；仕女素妆艳服与男宾青黑衣衫对照，家具深黑沉厚，“绚中出素”；当属南宋孝宗至宁宗朝（1163—1224）摹本；韩熙载（902—970）后唐同光间中进士，父被杀，926 年避难江南，仕南唐，屡上书不纳，时为兵部侍郎，“自汙”以自保（卷中《韩熙载行实》“竭其财，致伎乐殆百数，以自汙”）；顾闳中为南唐后主时画院待诏，擅画人物", "url": "https://www.dpm.org.cn/collection/paint/228200.html"}, {"label": "故宫名画记 · 顾闳中韩熙载夜宴图卷", "claim": "馆方高清图；其封面图（听乐段）与本厅主图配准比对，色彩、比例一致", "url": "https://minghuaji.dpm.org.cn/paint/detail?id=ebfcda63da386f527526ef7d780ce30f"}, {"label": "维基共享资源 · 主图文件页", "claim": "File:韩熙载夜宴图.tif，95930 × 3981，来源书格，公有领域（PD-Art）；本厅只挂画心", "url": "https://commons.wikimedia.org/wiki/File:%E9%9F%A9%E7%86%99%E8%BD%BD%E5%A4%9C%E5%AE%B4%E5%9B%BE.tif"}, {"label": "维基文库 · 《宣和画谱》卷七 顾闳中", "claim": "“顾闳中，江南人也。事伪主李氏为待诏……乃命闳中夜至其第，窃窥之，目识心记，图绘以上之。故世有《韩熙载夜宴图》”；北宋宣和年间内府编", "url": "https://zh.wikisource.org/zh-hant/%E5%AE%A3%E5%92%8C%E7%95%AB%E8%AD%9C/%E5%8D%B7%E4%B8%83"}, {"label": "维基文库 · 《五代史补》卷五 韩熙载", "claim": "“韩熙载仕江南，官至诸行侍郎……伪主知之，虽怒，以其大臣，不欲直指其过，因命待诏画为图以赐之，使其自愧，而熙载视之安然”；原文只称“伪主”“待诏”，未写是哪位国主、哪位画师", "url": "https://zh.wikisource.org/wiki/%E4%BA%94%E4%BB%A3%E5%8F%B2%E8%A3%9C/%E5%8D%B75"}, {"label": "大英百科全书 · 中国绘画：五代十国", "claim": "顾闳中是南方的人物画家，描绘李后主治下的宫廷生活；一件出色的摹本表现了大臣韩熙载的夜宴", "url": "https://www.britannica.com/art/Chinese-painting/Five-Dynasties-907-960-and-Ten-Kingdoms-902-978"}, {"label": "故宫博物院 · 阎立本步辇图卷", "claim": "文物号 新00119106；唐，阎立本作，绢本设色，纵 38.5、横 129 cm；绘唐太宗坐六名宫女抬的步辇，接见松赞干布派来的吐蕃使臣禄东赞（贞观十五年，641）；阎立本约卒于 673 年", "url": "https://www.dpm.org.cn/collection/paint/234620.html"}, {"label": "维基共享资源 · 步辇图文件页", "claim": "File:Buliantu.jpg，3053 × 853，公有领域；本厅裁取画中人物部分，色调按故宫名画记全卷图校正", "url": "https://commons.wikimedia.org/wiki/File:Buliantu.jpg"}, {"label": "中国新闻网 · 宋人摹《虢国夫人游春图》", "claim": "辽宁省博物馆藏宋代摹本，高 51.8、长 148 cm；画中八骑，连一名婴孩共九人；金章宗题签“天水摹张萱虢国夫人游春图”", "url": "https://www.chinanews.com.cn/m/cul/2015/02-11/7055997.shtml"}, {"label": "维基共享资源 · 虢国夫人游春图文件页", "claim": "File:虢国夫人游春图.jpg，4674 × 979，公有领域；本厅只取画心", "url": "https://commons.wikimedia.org/wiki/File:%E8%99%A2%E5%9B%BD%E5%A4%AB%E4%BA%BA%E6%B8%B8%E6%98%A5%E5%9B%BE.jpg"}, {"label": "克利夫兰艺术博物馆 · 宫中图 1976.1", "claim": "In the Palace（宫中圖），1140 年以前，据传为周文矩的原作摹写；南宋；绢本水墨淡设色；画心 28.5 × 168.6 cm；画宫中女子奏乐、照看孩童；CC0", "url": "https://www.clevelandart.org/art/1976.1"}, {"label": "故宫博物院 · 周文矩重屏会棋图卷", "claim": "文物号 新00146475；五代周文矩绘，绢本设色，纵 40.3、横 70.5 cm；徐邦达鉴定为宋人摹本；画南唐中主李璟与弟景遂、景达、景逿，景达、景逿对弈；背景屏风中又画屏风，故称“重屏”；周文矩（约 907—975），南唐画院翰林待诏，曾像顾闳中一样被派去窥绘韩熙载夜宴，所画未能传世", "url": "https://www.dpm.org.cn/collection/paint/230460.html"}, {"label": "维基共享资源 · 重屏会棋图文件页", "claim": "File:周文矩重屏会棋图卷.png，19580 × 3571，来源故宫博物院，公有领域；本厅只取画心", "url": "https://commons.wikimedia.org/wiki/File:%E5%91%A8%E6%96%87%E7%9F%A9%E9%87%8D%E5%B1%8F%E4%BC%9A%E6%A3%8B%E5%9B%BE%E5%8D%B7.png"}], "scroll": {"w": 16000, "h": 1358, "win": [12360.21, 0.0, 15010.23, 1358.0], "head": "right", "lo": "scroll/lo.webp", "loW": 1886, "loH": 160, "levels": [{"f": "scroll/a{i2}.webp", "w": 15698, "h": 1332, "tw": 1024}, {"f": "cut/mid/m{i2}.webp", "w": 23452, "h": 1990, "tw": 2048}]}};

