(window.EH_ROOMS=window.EH_ROOMS||{})["xishan"]={"id": "xishan", "zh": "谿山", "lat": "Northern Song", "yrs": "960 – 1127 CE", "one": "山成了主角，人小得像一粒芥子", "wall": "#2E2A22", "wallWhy": "墙色取千年旧绢的暗褐，比画上的绢再深一档：这幅画墨色沉，绢也老了，墙压得更暗，画才浮得出来，浅色文字也立得住。光是散的，不打聚光。它是一幅立轴，本该挂在墙上从下往上看，所以本厅照挂轴的样子挂，只挂画心；墙上的装裱为示意，不是原件的装裱。", "ink": "light", "frame": "mount", "art": {"img": "main.webp", "w": 1203, "h": 2400, "who": "范宽", "whoLat": "Fan Kuan, c. 960 – c. 1030", "title": "《谿山行旅图》", "short": "《谿山行旅图》", "meta": ["北宋，约 1000 年，绢本浅设色", "206.3 × 103.3 cm", "台北，台北故宫博物院（故画000826）"], "credit": "Wikimedia Commons, File:谿山行旅图轴.溪山行旅图.宋.范宽.绢本浅设色.台北故宫博物院藏.jpg — 来源 书格，公有领域"}, "lede": "北宋初年，关中画家范宽把一座大山迎面立在绢上；山脚下赶路的驮队，只有几粒豆子大。", "work": "谿（xī）同溪。画幅上大半是一座主峰，正面迎人立起，峰顶灌木丛生，像一簇簇菌子。山石用密密的短笔点出，像雨点打在石上，后人叫它“雨点皴”。主峰右侧一线瀑布直落下来。山腰以下一道白茫茫的云气，把大山推远；近处是巨石，中景的树丛里露出楼观的屋角，右下一队骡驴驮着货赶路，人和牲口都只有豆粒大。", "quote": ["山欲高，尽出之则不高，烟霞锁其腰则高矣。", "郭熙述、郭思辑《林泉高致·山水训》，北宋；郭熙晚于范宽"], "origin": "五代到北宋初，山水画自成一大画科，北方的荆浩、关仝、李成，江南的董源，各开一路。范宽是陕西华原人，字中立，据说性情宽缓，关中人便叫他“范宽”。他先学李成，后来叹道：“吾与其师于人者，未若师诸物也；吾与其师于物者，未若师诸心。”于是移居终南山、太华山，终日看山。北宋人把他与关仝、李成并提。明代董其昌在这幅画的诗塘上题：“北宋范中立谿山行旅图”，后来它进了清宫。", "traits": [["高远", "郭熙后来把看山的角度归成“三远”，其一是“自山下而仰山颠，谓之高远”。观者像站在山脚抬头，山就压在头顶。"], ["三段叠起", "北宋的大幅山水常把近景、中景、主山上下叠起。台北故宫认为，范宽有意推远主山、拉近中景，让渺小的行旅衬出主峰的巍峨。"], ["皴法", "画家用短点、短线擦出山石的纹理和体积，叫“皴”。范宽用密点；郭熙的石块像翻卷的云头，李唐的像斧头劈过，作品栏里都看得到。"], ["可游可居", "郭熙记下世人的公论：山水“有可行者，有可望者，有可游者，有可居者”，可游可居更好。画里有山路、有桥、有赶路的人，看画的人仿佛能走进去住下。"]], "special": {"title": "挂轴", "type": "scroll_hanging_pole", "text": "立轴平时卷起来收着，要看才挂上墙。挂高处用画叉：一根长竿，头上一个叉口，勾住挂绳往钉子上送。竿子长，竿头会晃，送不准，挂绳就滑下来。挂稳了松手，画轴自己往下放开。明人文震亨在《长物志》里说“悬画宜高”。挂得越高，站在下面仰着看，山越压顶。挂好以后，凑近山脚右下的树丛。1958 年，故宫（当时还在台中北沟）的李霖灿等人就在叶子中间找到了“范宽”两个小字。", "hints": {"start": "拿起画叉，勾住画轴的挂绳", "startTouch": "按住画叉，勾住画轴的挂绳", "lift": "慢慢举高，把挂绳送到墙上的钉子上", "sway": "竿子长，竿头在晃，稳一稳再送", "miss": "没挂上，再对准钉子", "slip": "挂绳滑下来了，再挑起来", "hooked": "挂上了，松开画叉", "unroll": "画轴自己往下放开", "settle": "晃了几下，停住了", "low": "挂得低了，山在眼前", "high": "挂得高，站在下面仰着看，山压在头顶", "rehang": "取下来，换一个高度再挂", "find": "凑近山脚右下的树丛，找找画家的名字", "findTouch": "放大山脚右下的树丛，找找画家的名字", "zoom": "再凑近一点，看叶子中间", "notHere": "这里只有叶子，再往右下找", "found": "找到了：叶子中间两个小字，“范宽”", "again": "取下画，再挂一次"}, "captions": {"pole": "画叉：长竿，头上开叉，勾挂绳用", "hook": "钉子", "cord": "挂绳", "yan": "惊燕：天头垂下的两条窄带", "mountNote": "装裱为示意", "heightLow": "低挂", "heightMid": "齐眉", "heightHigh": "高挂", "quote": "悬画宜高", "quoteSource": "文震亨《长物志》卷八，明", "sigTitle": "藏在树叶里的款", "sigNote": "1958 年 8 月 5 日，故宫人员（当时在台中北沟）在画面右下的树丛里发现“范宽”二字款；此前只能凭文献和明人的题字认定作者", "sigHint": "两字竖写，墨很淡，和叶子几乎分不开", "source": "范宽《谿山行旅图》，台北故宫博物院"}, "sig": {"box": [1118, 2035, 10, 20], "center": [1123, 2045], "boxSrc": [9830, 20520, 80, 170], "tolerance": 20, "note": "box/center 为 main.webp 像素（1203×2400）；boxSrc 为 Commons 原图像素（11105×24176），±20 px（原图）；画心在原图的范围 x 556–10534、y 3640–23548"}, "note": "惊燕、挂绳、画叉、钉子为示意，不是原件之物。“悬画宜高”出自文震亨《长物志》卷八“位置·悬画”（四库本：“悬画宜高，斋中仅可置一轴于上”）。款的位置据台北故宫“1958 年 8 月 5 日在画面右侧树丛中发现”与维基百科“右下骡队后方树丛”，框按 1:1 目验定。"}, "works": [{"img": "w1.webp", "w": 690, "h": 1200, "who": "荆浩（传）", "whoLat": "Jing Hao, active first half of 10th c.", "title": "《匡庐图》", "meta": ["旧题五代，绢本水墨", "185.8 × 106.8 cm", "台北，台北故宫博物院（故画000817）"], "note": "旧传荆浩作，馆方认为或是 12 世纪人追想的荆浩风格。", "credit": "台北故宫博物院开放资料, File:K2A000817N000000000PAA — 五代梁荊浩匡廬圖 軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w2.webp", "w": 1200, "h": 424, "who": "董源", "whoLat": "Dong Yuan, ? – 962", "title": "《潇湘图》", "meta": ["五代南唐，绢本设色", "50 × 141.4 cm", "北京，故宫博物院（新00147099）"], "note": "江南平缓的山、大片的水，与北方的大山是另一路。", "credit": "Wikimedia Commons, File:董源潇湘图卷.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w3.webp", "w": 823, "h": 1200, "who": "郭熙", "whoLat": "Guo Xi, c. 1023 – c. 1085", "title": "《早春图》", "meta": ["北宋熙宁五年（1072），绢本浅设色", "158.3 × 108.1 cm", "台北，台北故宫博物院（故画000053）"], "note": "写《林泉高致》的郭熙自己的画，满幅烟岚浮动。", "credit": "台北故宫博物院开放资料, File:K2A000053N000000000PAA — 宋郭熙早春圖 軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w4.webp", "w": 900, "h": 1200, "who": "李唐", "whoLat": "Li Tang, c. 1049 – after 1130", "title": "《万壑松风图》", "meta": ["北宋宣和六年（1124），绢本设色", "188.7 × 139.8 cm", "台北，台北故宫博物院（故画000896）"], "note": "北宋末的巨幅山水，近处的松林压过了主峰。", "credit": "Wikimedia Commons, File:Li Tang - Wind in Pines Among a Myriad Valleys.jpg — 来源 台北故宫博物院，公有领域"}], "chain": "之前：上一厅的夜宴里，山石树木只是琵琶女身后屏风上的画，是屋里的陈设。在范宽这里，山水自己成了画的主角，人退到山脚下。之后：山脚那队驮货的骡驴还在往前走，下一厅，北宋人从山里走进了城。", "sources": [{"label": "台北故宫博物院 · 宋范宽谿山行旅图 轴", "claim": "谿山行旅图：统一编号 故画000826N000000000；本幅 206.3 × 103.3 cm，绢；作者款识“范宽”在本幅（画幅右下树荫中）；诗塘董其昌题“北宋范中立谿山行旅图。董其昌观。”；鉴藏宝玺有乾隆、嘉庆、宣统诸玺，收传印有钱勰“忠孝之家”、梁清标等；技法细目“雨点皴”；主题含溪涧、瀑布、台阁、行旅、山径、骡驴、桥；馆方说明：范宽生卒不详，约 1025 年时还在世，晚年往来开封、洛阳；本幅公认为其真迹；以近、中、远三段式构图，推远主山、拉近中景，突显渺小行旅与主山巍峨的对比；影像授权 CC BY 4.0 / CC0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/1195?dep=P"}, {"label": "台北故宫博物院 · 精选赏析：谿山行旅图", "claim": "范宽，宋，绢本浅设色，轴，206.3 × 103.3 cm；巍峨高山顶立，山头灌木丛生结成密林，状若覃菌；树林中有楼观微露；一群驮队匆匆赶路；细如弦丝的瀑布直泻而下；画幅右下角树影中有“范宽”名款", "url": "https://theme.npm.edu.tw/selection/Article.aspx?sNo=04000959"}, {"label": "台北故宫博物院 · 甲子万年：百年院庆特展", "claim": "谿山行旅图是传世三件北宋山水巨作之一，约绘制于 1000 年左右；1958 年 8 月 5 日本院工作人员在画面右侧树丛中发现“范宽”两字签款", "url": "https://theme.npm.edu.tw/EnduringLegacyS203/page-2"}, {"label": "维基百科 · 谿山行旅图", "claim": "1958 年由台北故宫书画处技工牛性群与李霖灿在画右下骡队后方树丛中发现“范宽”二字，印证董其昌所题；山壁用雨点皴", "url": "https://zh.wikipedia.org/zh-hans/%E8%B0%BF%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9C%96"}, {"label": "台北故宫博物院 · 北沟传奇：故宫文物迁台后早期岁月", "claim": "1950 年 4 月雾峰北沟库房完工，文物入库，此后十五年存于台中北沟；1965 年在台北外双溪建馆。故 1958 年发现款时故宫尚在台中北沟", "url": "https://theme.npm.edu.tw/exh109/BeigouLegacy/"}, {"label": "大英百科全书 · Travelers Among Mountains and Streams", "claim": "Fan Kuan, c. 960 – c. 1030；北宋；ink and slight colour on silk，hanging scroll；台北故宫藏", "url": "https://www.britannica.com/topic/Travelers-Among-Mountains-and-Streams"}, {"label": "维基文库 · 《宣和画谱》卷十一", "claim": "范宽字中立，华原人；始学李成，叹曰“吾与其师于人者，未若师诸物也；吾与其师于物者，未若师诸心”；卜居终南、太华岩隈林麓之间；宜其与关、李并驰方驾；蔡卞题：关中人谓性缓为宽", "url": "https://zh.wikisource.org/wiki/%E5%AE%A3%E5%92%8C%E7%95%AB%E8%AD%9C/%E5%8D%B7%E5%8D%81%E4%B8%80"}, {"label": "维基文库 · 郭熙《林泉高致集》", "claim": "山水训：“山欲高，尽出之则不高，烟霞锁其腰则高矣”；“山有三远：自山下而仰山颠，谓之高远；自山前而窥山后，谓之深远；自近山而望远山，谓之平远”；“山水有可行者，有可望者，有可游者，有可居者……可行可望不如可居可游之为得”", "url": "https://zh.wikisource.org/wiki/%E6%9E%97%E6%B3%89%E9%AB%98%E8%87%B4%E9%9B%86"}, {"label": "维基文库 · 文震亨《长物志》卷八", "claim": "位置·悬画：“悬画宜高，斋中仅可置一轴于上”（四库本）；文震亨，明", "url": "https://zh.wikisource.org/wiki/%E9%95%B7%E7%89%A9%E5%BF%97_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%8D%B708"}, {"label": "人民日报 · 挂画雅趣", "claim": "宋代挂轴为宣和裱：上为天头，中有惊燕二条，左右框档，中接本幅，下为地头、轴杆", "url": "http://paper.people.com.cn/zgnyb/html/2022-06/13/content_25923364.htm"}, {"label": "搜狐 · 宋代如何借助道具挂画", "claim": "宋画中童子手持画叉挂画，画叉顶端呈 U 形，勾住悬挂的绳线", "url": "https://www.sohu.com/a/476083096_582661"}, {"label": "台北故宫博物院 · 五代梁荆浩匡庐图 轴", "claim": "匡庐图：统一编号 故画000817N000000000；本幅 185.8 × 106.8 cm，绢；右上传元文宗题“荆浩真迹神品”；旧传荆浩作；荆浩活动于 10 世纪上半；馆方认为下半部画法接近李唐《万壑松风》，可能是 12 世纪所追想的荆浩风格；影像 CC BY 4.0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/506?dep=P"}, {"label": "故宫博物院 · 董源潇湘图卷", "claim": "潇湘图：文物号 新00147099；五代南唐，董源作，绢本设色，纵 50 横 141.4 cm；本幅无款印，董其昌据《宣和画谱》定名；画史视为“南派”山水开山之作；五代至北宋初年是山水画的成熟阶段，后人概括为“北派”与“南派”两支；董源（？—962）", "url": "https://www.dpm.org.cn/collection/paint/234585.html"}, {"label": "台北故宫博物院 · 宋郭熙早春图 轴", "claim": "早春图：统一编号 故画000053N000000000；宋神宗熙宁五年（1072）；本幅 158.3 × 108.1 cm，绢；款“早春。壬子年郭熙画”；郭熙（1023—约 1085）；山石多用“云头皴”；影像 CC BY 4.0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/47?dep=P"}, {"label": "台北故宫博物院 · 宋李唐万壑松风图 轴", "claim": "万壑松风图：统一编号 故画000896N000000000；宋徽宗宣和六年（1124）；本幅 188.7 × 139.8 cm，绢；款“皇宋宣和甲辰春河阳李唐笔”；李唐约 1049—1130 后；小斧劈皴，深浅青绿烘染；扩大近景林木、缩小主峰，开南宋近景山水先声", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/33?dep=P"}, {"label": "维基共享资源 · 主图与作品栏图片文件页", "claim": "主图 File:谿山行旅图轴…台北故宫博物院藏.jpg（11105 × 24176，书格转载，公有领域；本展按台北故宫馆方色卡图对色）；File:董源潇湘图卷.png（来源故宫博物院名画记，公有领域）；File:Li Tang - Wind in Pines Among a Myriad Valleys.jpg（来源台北故宫网站，公有领域）", "url": "https://commons.wikimedia.org/wiki/File:%E8%B0%BF%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE%E8%BD%B4.%E6%BA%AA%E5%B1%B1%E8%A1%8C%E6%97%85%E5%9B%BE.%E5%AE%8B.%E8%8C%83%E5%AE%BD.%E7%BB%A2%E6%9C%AC%E6%B5%85%E8%AE%BE%E8%89%B2.%E5%8F%B0%E5%8C%97%E6%95%85%E5%AE%AB%E5%8D%9A%E7%89%A9%E9%99%A2%E8%97%8F.jpg"}]};

