(window.EH_ROOMS=window.EH_ROOMS||{})["bianjing"]={"id": "bianjing", "zh": "汴京", "lat": "Northern Song", "yrs": "960 – 1127 CE", "one": "从郊野到城门，一段一段展开", "wall": "#2E2A22", "wallWhy": "墙色取北宋旧绢的暗褐，比画上的绢再深一档，和上一厅的溪山是同一面墙：同一代人，从山里走进了城。手卷本来平放在案上，从右往左一段段展开看，所以本厅不加框，也不仿造它的装裱，只挂画心，照原样横陈。", "ink": "light", "frame": "none", "art": {"img": "t_win.webp", "w": 2600, "h": 1005, "who": "张择端", "whoLat": "Zhang Zeduan, active early 12th c.", "title": "《清明上河图》", "short": "《清明上河图》", "meta": ["北宋，绢本淡设色", "24.8 × 528 cm", "北京，故宫博物院（新00087177）"], "credit": "Wikimedia Commons, File:Alongtheriver QingMing.jpg — 来源 百度贴吧，公有领域"}, "lede": "北宋的都城汴京，就是今天的河南开封。宫廷画家张择端把都城东南一角和汴河两岸，画进了一卷五米多长的绢。", "work": "手卷从右往左展开。卷首是郊野，枯树疏林间，有人赶着五头驮炭的毛驴。往左，汴河上的船多起来，到了一座木拱桥，俗称虹桥：桥下一艘漕船正放倒桅杆，要穿过桥洞，船头的人撑篙抵住，桥上的人探身抛下绳子，两岸挤满了看的人。再往左是高大的城楼，一队骆驼正穿过城门，街上店铺一家挨着一家。", "quote": ["翰林张择端，字正道，东武人也。幼读书，游学于京师，后习绘事。本工其界画，尤嗜于舟车、市桥郭径，别成家数也。", "金张著《清明上河图》跋，大定二十六年（1186）"], "origin": "张择端生卒年不详，他的生平几乎只靠卷后金人张著的这段跋；连同这段跋，卷后共有十三家题记，钤印九十六方。画名里的“清明”指什么，说法不一：故宫博物院的说明写它画的是清明时节的汴京；有学者注意到画里有人摇扇、有人赤膊，酒旗上写着“新酒”，认为不只是春景；有学者认为“清明”是城东的清明坊；也有人读作“政治清明”。本展不作裁决。", "traits": [["以大观小", "北宋沈括批评李成把山上的亭台画成仰视的飞檐。他说画山水要像人看假山，从高处往下看，才能把重重山谷、屋后的街巷都收进一幅画。"], ["散点透视", "故宫博物院说这一卷用鸟瞰式全景，采取“散点透视法”：没有一个固定的视点，边展边看，走到哪一段，就像站在哪一段的上方。"], ["兼工带写", "界画靠界尺画直线，专画宫室楼台。张择端画屋木舟车，线条工整，敷墨设色却放得开，故宫称之为兼工带写，不同一般的界画。"], ["卧以游之", "南朝宗炳老病，怕再也看不遍名山，就把游过的山水画在屋里，说要“卧以游之”。手卷在案上一段段展开，看画的人也在画里走了一趟。"]], "special": {"title": "虹桥过船", "type": "bridge_mast", "text": "虹桥下这艘漕船，桅杆比桥洞高。画里，船上的人正放倒桅杆，船头有人撑篙抵住，桥上有人抛下绳子。现在由你来过这座桥：向下拖，拉绳放倒桅杆，桅杆有分量，放得太快会砸下来；按住，撑篙稳住船头。两件事轮流做：放早了，船头没人管，船被急流冲得打横；放晚了，桅杆撞上桥。桥上的人跟着你喊。水流、桅杆的分量和喊声都是本展设定，不是复原。", "hints": {"start": "急流正把船推向虹桥：向下拖，拉绳放倒桅杆", "startTouch": "急流正把船推向虹桥：手指向下拖，拉绳放倒桅杆", "current": "水急，船自己往桥下冲", "pull": "拉绳，桅杆一点点放下来", "heavy": "桅杆有分量，慢一点放", "tooFast": "放太快了，桅杆要砸下来", "dropped": "桅杆砸在船上了", "pole": "按住，撑篙稳住船头", "poleTouch": "手指按住，撑篙稳住船头", "swing": "船头偏了，快撑篙", "alternate": "放一段，撑一下，轮流来", "sideways": "放早了，船头没人管，船打横了", "tooLate": "放晚了，桅杆撞上了桥", "near": "桥洞就在前面", "clear": "桅杆放平了，船过得去", "through": "穿过桥洞了", "cheer": "桥上一片喝彩", "compare": "和画里的这一段并排看", "again": "再过一次桥", "keys": "键盘：按住 ↓ 或 S 放倒桅杆，按住 ↑ 或 W 撑篙"}, "captions": {"shouts": {"calm": ["船来了！", "慢点放！"], "warn": ["当心桅杆！", "稳住船头！", "快撑篙！", "抓住绳子！"], "danger": ["要撞桥了！", "船横过来了！"], "cheer": ["过去了！", "好！"]}, "shoutsNote": "桥上的喊声是本展设定，画上没有字", "time": "过桥用了 {s} 秒", "hits": "撞桥 {n} 次", "turns": "打横 {n} 次", "verdictGood": "桅杆放得稳，船头撑得住，一口气过了桥", "verdictHit": "桅杆碰了桥，桥上的人替你捏了一把汗", "verdictTurn": "船打横过，好在又撑正了", "orig": "原作：虹桥下，漕船正放倒桅杆，要穿过桥洞", "origSource": "张择端《清明上河图》，故宫博物院", "ref": "船、桥、人都照原作这一段；水流和桅杆的重量是本展示意"}, "img": "main.webp", "imgW": 16000, "imgH": 754, "hr": "cut/hr/h00–h17.webp 为画心全分辨率分块（F 坐标 1:1，每块 2048 宽），几何见 _wip/prep-bianjing/geom.json", "note": "坐标：main = main.webp 像素（16000 × 754，左上原点，框为 [x,y,w,h]）；F = 画心全分辨率（36784 × 1734），main = F × 0.434972。手卷从右往左读，卷首在 main x = 16000。框为目验近似，误差约 ±5 main 像素。", "scene": {"bridge": {"main": [7812.1, 12.2, 535.0, 413.2], "F": [17960, 28, 1230, 950], "label": "虹桥（木拱桥，桥身连桥上人群）"}, "arch": {"main": [7842.5, 116.6, 500.3, 304.5], "F": [18030, 268, 1150, 700], "label": "桥洞（拱下空间，左端落地约在 F y 970）"}, "crowd": {"main": [8016.5, 51.3, 304.5, 74.0], "F": [18430, 118, 700, 170], "label": "桥上探身围看的人"}, "rope": {"coil": {"main": [8068.7, 81.8, 26.1, 39.1], "F": [18550, 188, 60, 90]}, "line": {"main": [[8081.8, 99.2], [8142.7, 181.8]], "F": [[18580, 228], [18720, 418]]}, "label": "桥上人抛下的绳子：绳圈在栏杆边，绳子垂向船"}, "boat": {"main": [8116.6, 94.8, 434.9, 252.3], "F": [18660, 218, 1000, 580], "facing": "left", "label": "漕船，船头朝左对着桥洞"}, "bow": {"main": [8116.6, 229.7, 130.5, 117.4], "F": [18660, 528, 300, 270], "label": "船头：几个人持长篙撑抵"}, "mast": {"main": [[8338.4, 234.0], [8468.9, 60.0]], "F": [[19170, 538], [19470, 138]], "label": "桅杆（正在放倒，约 50° 斜向右上，桅顶带索具）：[根部, 桅顶]"}, "stern": {"main": [8490.6, 107.9, 60.9, 139.2], "F": [19520, 248, 140, 320], "label": "船尾"}}}, "works": [{"img": "w1.webp", "w": 1200, "h": 526, "who": "王希孟", "whoLat": "Wang Ximeng, active early 12th c.", "title": "《千里江山图》（局部）", "meta": ["北宋，约 1113 年，绢本设色", "51.5 × 1191.5 cm", "北京，故宫博物院（新00146004）"], "note": "蔡京跋说，他十八岁献上此卷，徽宗曾亲自指点。", "credit": "Wikimedia Commons, File:王希孟千里江山图卷.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w2.webp", "w": 1200, "h": 864, "who": "赵佶（宋徽宗）", "whoLat": "Zhao Ji (Emperor Huizong), 1082 – 1135", "title": "《瑞鹤图》（局部）", "meta": ["北宋政和二年（1112），绢本设色", "51 × 138.2 cm", "沈阳，辽宁省博物馆"], "note": "汴京宣德门上的群鹤，两只立在屋脊鸱尾上。", "credit": "Wikimedia Commons, File:Songhuizong5.jpg — 来源 中文维基百科，公有领域"}, {"img": "w3.webp", "w": 1200, "h": 404, "who": "苏轼", "whoLat": "Su Shi, 1037 – 1101", "title": "《黄州寒食诗帖》（局部）", "meta": ["北宋，诗作于 1082 年，纸本", "34.2 × 199.5 cm", "台北，台北故宫博物院（购书001001）"], "note": "谪居黄州第三年的寒食节，他写下两首诗。", "credit": "Wikimedia Commons, File:寒食帖.jpg — 来源 台北故宫博物院，公有领域"}, {"img": "w4.webp", "w": 636, "h": 1200, "who": "崔白", "whoLat": "Cui Bai, active 11th c.", "title": "《双喜图》", "meta": ["北宋嘉祐六年（1061），绢本", "193.7 × 103.4 cm", "台北，台北故宫博物院（故画000834）"], "note": "两只山喜鹊，一只腾空，一只俯身鼓噪，树下野兔昂首回顾。", "credit": "台北故宫博物院开放资料, File:K2A000834N000000000PAA.jpg — 摄影 國立故宮博物院，CC BY 4.0 @ www.npm.gov.tw"}], "chain": "之前：溪山脚下，一队驮货的骡驴走在行旅路上，大山正面立着。之后：宋人从热闹的街市回到书斋，看的东西越来越少，越来越静。下一厅，案头只放着一只天青色的汝窑水仙盆。", "sources": [{"label": "故宫博物院 · 张择端清明上河图卷", "claim": "文物号 新00087177；北宋张择端作，绢本淡设色，纵 24.8、横 528 cm；描绘清明时节汴京（今河南开封）东角子门内外和汴河两岸，东角子门位于汴京内城东南，全卷描绘“汴京东南城角这一典型的区域”；分三段：首段市郊，中段以上土桥（概称虹桥）为中心，“桥下一艘漕船正放倒桅杆欲穿过桥孔”，艄工紧张工作引众人围观；后段市区街道，有驼队，城门楼名东角子门；用笔兼工带写，设色淡雅，不同一般界画，“别成家数”；鸟瞰式全景法，手卷，“散点透视法”；后幅有金张著、明吴宽等 13 家题记，钤 96 方印；界画释义", "url": "https://www.dpm.org.cn/collection/paint/228226.html"}, {"label": "故宫名画记 · 张择端清明上河图卷", "claim": "同上藏品说明；张择端（生卒年不详），字正道，东武（今山东诸城）人，工界画，尤嗜舟车、市桥、郭径", "url": "https://minghuaji.dpm.org.cn/paint/detail?id=592d80e225aac624977fee2e19452c1f"}, {"label": "维基共享资源 · 主图文件页", "claim": "File:Alongtheriver QingMing.jpg，38414 × 1800，公有领域，来源百度贴吧；本厅只挂画心，已按故宫官网图校色", "url": "https://commons.wikimedia.org/wiki/File:Alongtheriver_QingMing.jpg"}, {"label": "维基百科 · 清明上河图", "claim": "金张著跋全文：“翰林张择端，字正道，东武人也。幼读书，游学于京师，后习绘事。本工其界画，尤嗜于舟车、市桥郭径，别成家数也……大定丙午清明后一日，燕山张著跋”（大定丙午即 1186 年；跋文全文据此转录，内容与故宫博物院藏品说明“别成家数”及余辉讲稿所述张著八十五字跋相合）", "url": "https://zh.wikipedia.org/zh-hans/%E6%B8%85%E6%98%8E%E4%B8%8A%E6%B2%B3%E5%9C%96"}, {"label": "故宫博物院 · 余辉《北宋张择端〈清明上河图〉揭秘》（故宫讲坛）", "claim": "故宫博物院研究馆员余辉讲稿：张择端生平“前人留下的唯一一点线索”是卷尾金代张著的八十五字跋，说他字正道，东武人，游学京师，后学界画；卷首是“送炭驴队”；虹桥下大船桅杆还没放下，船上有人拿长杆顶着桥身，船工在船头调整方向，桥上的人大声呼叫，“扔下两根绳子”；另说卷首的徽宗题签在明末被裱画师裁去", "url": "https://www.dpm.org.cn/forum_detail/99722.html"}, {"label": "光明网 · 祝勇《〈清明上河图〉的矛盾与统一》", "claim": "卷首两个赶脚者赶着五匹驴子，驮的是木炭；郑振铎、张安治等认为“清明”指清明节；孔宪易、高木森等注意到“新酒”酒旗、持扇者，彭慧萍论赤膊、短衣者，提出不只是春景；高木森认为“清明”是地名清明坊；另有“政治清明”说，余辉不同意此说", "url": "https://news.gmw.cn/2021-10/22/content_35250404.htm"}, {"label": "中新社“东西问” · 余辉：《清明上河图》中隐藏了哪些文化密码", "claim": "故宫博物院研究馆员余辉：此卷由北宋宫廷画家张择端所绘，描绘汴京（今河南开封）；郊外的驮炭驴队与护城河边的木炭市场呼应", "url": "https://m.newsduan.com/static/content/22xygh/2025-01-03/1324661680143211259.html"}, {"label": "维基文库 · 沈括《梦溪笔谈》卷十七", "claim": "“李成画山上亭馆及楼塔之类，皆仰画飞檐……此论非也。大都山水之法，盖以大观小，如人观假山耳。若同真山之法，以下望上，只合见一重山，岂可重重悉见，兼不应见其溪谷间事。又如屋舍，亦不应见其中庭及后巷中事……李君盖不知以大观小之法”", "url": "https://zh.wikisource.org/wiki/%E5%A4%A2%E6%BA%AA%E7%AD%86%E8%AB%87/%E5%8D%B717"}, {"label": "维基文库 · 《宋书》卷九十三 宗炳传", "claim": "“有疾还江陵，叹曰：老疾俱至，名山恐难遍睹，唯当澄怀观道，卧以游之。凡所游履，皆图之于室”", "url": "https://zh.wikisource.org/wiki/%E5%AE%8B%E6%9B%B8/%E5%8D%B793"}, {"label": "故宫博物院 · 王希孟千里江山图卷", "claim": "文物号 新00146004；北宋王希孟作，绢本设色，纵 51.5、横 1191.5 cm，王希孟传世唯一作品；蔡京跋：“政和三年四月八日赐。希孟年十八岁，昔在画学为生徒……上知其性可教，遂诲谕之，亲授其法。不逾半岁，乃以此图进”；政和三年（1113）可能即完成年代", "url": "https://www.dpm.org.cn/collection/paint/228354.html"}, {"label": "维基共享资源 · 千里江山图文件页", "claim": "File:王希孟千里江山图卷.png，153767 × 6110，来源故宫博物院名画记，公有领域（PD-scan）", "url": "https://commons.wikimedia.org/wiki/File:%E7%8E%8B%E5%B8%8C%E5%AD%9F%E5%8D%83%E9%87%8C%E6%B1%9F%E5%B1%B1%E5%9B%BE%E5%8D%B7.png"}, {"label": "中新社“东西问” · 辽宁省博物馆副馆长董宝厚谈《瑞鹤图》（北京日报客户端转载）", "claim": "《瑞鹤图》宋徽宗赵佶作，绢本设色，纵 51、横 138.2 cm，辽宁省博物馆藏；右图左书；绘汴梁宣德门上群鹤盘旋，两只立于屋脊两端鸱尾之上；题记“政和壬辰，上元之次夕”即 1112 年正月十六；20 只鹤，18 只盘旋", "url": "https://xinwen.bjd.com.cn/content/s67b2009ee4b068c68f0fe217.html"}, {"label": "维基共享资源 · 瑞鹤图文件页", "claim": "File:Songhuizong5.jpg，9079 × 1846，全卷（画与题记），公有领域；本厅只取画的部分", "url": "https://commons.wikimedia.org/wiki/File:Songhuizong5.jpg"}, {"label": "维基百科 · 宋徽宗", "claim": "赵佶，1082 年生，1135 年卒", "url": "https://zh.wikipedia.org/zh-hans/%E5%AE%8B%E5%BE%BD%E5%AE%97"}, {"label": "台北故宫博物院 · 北宋苏东坡书黄州寒食诗卷", "claim": "购书001001；苏轼（1037—1101）；元丰二年（1079）谪居黄州，第三年四月寒食日作《寒食雨二首》，其后书成此卷；纸本，34.2 × 199.5 cm", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/14714?dep=P"}, {"label": "维基共享资源 · 寒食帖文件页", "claim": "File:寒食帖.jpg，38700 × 1997，据台北故宫博物院原图拼接，公有领域；本厅取苏轼诗文部分", "url": "https://commons.wikimedia.org/wiki/File:%E5%AF%92%E9%A3%9F%E5%B8%96.jpg"}, {"label": "台北故宫博物院 · 宋崔白双喜图轴", "claim": "故画000834；绢；193.7 × 103.4 cm；款“嘉祐辛丑年崔白笔”（1061）；绘山喜鹊二，一展翅腾空，一俯身鼓噪，下有野兔昂首回顾", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=48&dep=P"}], "scroll": {"w": 16000, "h": 754, "win": [12614.18, 0.0, 14564.59, 754.0], "head": "right", "lo": "scroll/lo.webp", "loW": 3394, "loH": 160, "levels": [{"f": "scroll/a{i2}.webp", "w": 21319, "h": 1005, "tw": 1024}, {"f": "cut/hr/h{i2}.webp", "w": 36784, "h": 1734, "tw": 2048}]}};

