(window.EH_ROOMS=window.EH_ROOMS||{})["ruyao"]={"id": "ruyao", "zh": "汝窑", "lat": "Northern Song Ru Ware", "yrs": "c. 1086 – 1125 CE", "one": "窗光移过，天青里透出淡粉", "wall": "#3A3B38", "wallWhy": "墙色取烟灰色的暗壁，像书斋里窗光照不到的那面墙，好把釉色衬出来。这只盆放在案上看，不挂墙，也没有框，本厅不加框。原件不大，两只手就能捧起。", "ink": "light", "frame": "none", "art": {"img": "cut/main_cut.webp", "w": 1535, "h": 855, "who": "佚名汝窑窑工", "whoLat": "Unknown Northern Song Ru ware potter", "title": "《汝窑青瓷无纹水仙盆》", "short": "《汝窑水仙盆》", "meta": ["北宋，11 世纪晚期 – 12 世纪初，青瓷", "高 6.9 cm，口径 23.0 × 16.4 cm", "台北，台北故宫博物院（故瓷 017851）"], "credit": "國立故宮博物院開放資料, File:K1B017851N000000000PAC.jpg — 汝窯 青瓷無紋水仙盆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, "lede": "北宋晚期，汝州的窑场为宫廷烧造青瓷，为时很短。存世完整的汝窑不到一百件，这只盆是其中之一。", "work": "一只椭圆的盆：口沿向外撇开，盆壁深，平底下接四只云头形的足，近底绕着一道凸棱。通身只有一种颜色，不刻花，不描金，釉面上连一道细裂纹也没有。这一种颜色并不呆板：口沿和那道凸棱上釉层薄，透出一点淡粉；盆里底边积釉的地方，天青带一点淡碧。窗光慢慢移过，这些深浅就跟着变，像一块温润的玉。", "quote": ["渐老渐熟，乃造平淡。其实不是平淡，绚烂之极也。", "苏轼致侄书，原说作文，本展借来看器（《侯鲭录》卷八）"], "origin": "据南宋叶寘《坦斋笔衡》，北宋朝廷嫌定州白瓷“有芒，不堪用”，于是命汝州烧造青瓷。汝窑的窑址长期没有找到，直到 1986 年，上海博物馆的学者在宝丰县清凉寺村采到汝瓷标本；1987 年起，河南考古工作者在这里多次发掘，找到了专为宫廷烧瓷的窑炉和作坊。这只盆后来藏入清宫。乾隆皇帝爱不释手，命人在盆底刻上自己的诗，又配了一只带抽屉的木座，抽屉里放着一册他临摹宋人书画的小册子。", "traits": [["只靠一层釉", "传世汝窑绝大多数不刻花、不画彩，全凭一层釉。颜色也只有一种，深浅来自釉层的厚薄和器形的转折，光线一变，颜色跟着变。"], ["满釉支烧", "釉一直裹到足底，烧时用几枚小而尖的支钉把器物撑起，底上只留芝麻大小的钉痕。钉数依器形而定，椭圆的水仙盆是六个。"], ["开片", "釉和胎冷却时收缩不一，釉面会裂出细纹，叫开片。传世汝窑大多有开片，明人曹昭说“有蟹爪纹者真，无纹者尤好”。"], ["案头清玩", "南宋赵希鹄写书斋之乐：“明窗净几”，时时取出古人的书画来看，又摩挲商周的钟鼎。在他笔下，看书画和把玩古器，是在同一张案上做的事。"]], "special": {"title": "烧一只天青", "type": "celadon_kiln", "text": "汝窑的盆先素烧一次，上釉以后坐在支钉上，装进匣钵，再入窑烧。烧到高温时让窑里缺氧，釉里的铁才会发青；氧气多了，颜色就偏黄。宋代汝窑烧的是木柴，这里用拉风箱代替添柴和控风。火候、烧出的颜色和开片都是本展的示意，不是复原。", "hints": {"start": "把盆坐上支钉，装进匣钵", "load": "把匣钵放进窑里", "fire": "拉风箱，跟着火的节奏一拉一推", "good": "拉得正是时候，火旺起来了", "early": "拉早了，风箱顶着劲", "late": "拉晚了，火落下去了", "hot": "够热了，关小烟囱闸门，让火闷着烧", "damperEarly": "火还不够旺，先别关闸门", "reducing": "窑里缺氧了，釉里的铁开始发青", "tooLong": "闷得太久，火快灭了", "peek": "抽出火照看一看火候", "open": "开窑", "cool": "出窑，慢慢冷却", "crackle": "叮——你的盆开片了", "noCrackle": "冷透了，一道开片也没有：这很少见", "flip": "翻过来看底", "compare": "和墙上这只并排看", "again": "再烧一窑", "keys": "键盘：S 拉风箱，D 关小闸门，回车开窑"}, "captions": {"heat": "火候", "air": "窑里的空气", "airOx": "氧气足", "airRed": "缺氧，火在闷烧", "result": "你烧出的是{color}", "stats": "拉准了 {n} 下", "pins": "底上六个支钉痕，只有芝麻大", "mine": "你的盆", "orig": "墙上的原件", "origSource": "《汝窑青瓷无纹水仙盆》，北宋，台北故宫博物院", "origNote": "原件通体没有开片", "ref": "盆形照墙上的原件；火候与颜色的对应、开片与否，都是本展设定"}, "colors": [{"name": "米黄", "hex": "#C8B88C", "when": "火里氧气多，铁没有转青"}, {"name": "豆青", "hex": "#9FAF8A", "when": "闷得不够，青里带黄绿"}, {"name": "月白", "hex": "#C9D2CF", "when": "火候不足，釉色浅淡发白"}, {"name": "天青", "hex": "#9EB3B8", "when": "火够旺，又闷得正好：墙上这只的颜色"}], "img": "main.webp", "imgW": 2400, "imgH": 1795, "basinBox": [413, 632, 1519, 845], "glaze": {"lit": "#9EB3B8", "shade": "#808C8E", "inside": "#92A7A2", "lip": "#B9C2C1"}, "bottom": {"src": "https://iiifod.npm.gov.tw/iiif/2/K1B%2FK1B017851N000000000PCY/full/full/0/default.jpg", "w": 3240, "h": 2160, "credit": "國立故宮博物院開放資料, File:K1B017851N000000000PCY.jpg — 汝窯 青瓷無紋水仙盆 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw", "pins": [[1312, 692], [1824, 694], [904, 1010], [2244, 1066], [1304, 1394], [1794, 1414]], "poemBox": [1080, 740, 1050, 480], "seals": "比德、朗润（诗末两方印，在诗文左侧）"}, "note": "坐标为像素，左上原点；框写 [x, y, w, h]。basinBox、glaze 取自 main.webp（2400×1795）；bottom 为台北故宫底面照 PCY 视角（3240×2160）的坐标，图尚未放进厅目录，用时请下载为 s_bottom.webp 并按比例换算。colors 的色值与“火候—颜色”对应为本展示意；glaze 为 main.webp 中位色。原件不做任何变形，展项里烧的是“你的盆”。"}, "works": [{"img": "w1.webp", "w": 1200, "h": 900, "who": "佚名定窑窑工", "whoLat": "Unknown Northern Song Ding ware potter", "title": "《定窑白瓷婴儿枕》", "meta": ["北宋，12 世纪，白瓷（定窑）", "通高 18.8 cm，底长 31.0 cm，宽 13.2 cm", "台北，台北故宫博物院（故瓷 004923）"], "note": "同代北方名窑的白瓷，刻花、印花兼用，做成一个伏卧的孩子。", "credit": "國立故宮博物院開放資料, File:K1B004923N000000000PAB.jpg — 定窯 白瓷嬰兒枕 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w2.webp", "w": 1200, "h": 1075, "who": "佚名钧窑窑工", "whoLat": "Unknown Jun ware potter", "title": "《钧窑紫斑盖罐》", "meta": ["12 世纪（北宋或金），天蓝釉瓷，有紫斑（钧窑）", "高 9.5 cm，直径 12.1 cm", "克利夫兰，克利夫兰艺术博物馆（1957.36）"], "note": "同在河南：钧窑在天蓝釉上泼刷铜料，烧出晚霞般的紫斑。", "credit": "克利夫兰艺术博物馆开放获取, File:1957.36_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}, {"img": "w3.webp", "w": 900, "h": 1200, "who": "佚名南宋官窑窑工", "whoLat": "Unknown Southern Song Guan ware potter", "title": "《官窑青瓷琮式瓶》", "meta": ["南宋，12–13 世纪，青瓷（官窑）", "高 18.8 cm，口径 12.8 cm", "台北，台北故宫博物院（故瓷 016606）"], "note": "南渡后的官窑：仿玉琮造型，粉青厚釉，满布开片。", "credit": "國立故宮博物院開放資料, File:K1B016606N000000000PAB.jpg — 官窯 青瓷琮式瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w4.webp", "w": 900, "h": 1200, "who": "佚名龙泉窑窑工", "whoLat": "Unknown Southern Song Longquan ware potter", "title": "《龙泉窑青瓷凤耳瓶》", "meta": ["南宋，13 世纪，青瓷（龙泉窑）", "高 25.5 cm，口径 9.4 cm", "台北，台北故宫博物院（故瓷 017827）"], "note": "浙江龙泉的粉青，釉厚而润，两只凤耳模印而成。", "credit": "國立故宮博物院開放資料, File:K1B017827N000000000PAB.jpg — 龍泉窯 青瓷鳳耳瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}], "chain": "之前：唐代越州已烧青瓷，南宋人引陆龟蒙诗“九秋风露越窑开”，说唐时已有“秘色”。之后：宋室南渡，在临安先后设修内司、郊坛下官窑，接着烧青瓷；清雍正朝，景德镇奉旨仿汝。下一厅也到南宋：画上大片留白，只剩一江寒水。", "sources": [{"label": "台北故宫博物院 · 汝窑青瓷无纹水仙盆", "claim": "主作品：汝窯 青瓷無紋水仙盆，故瓷017851N000000000；北宋，西元11世纪晚期–12世纪初；高6.9、口径23.0×16.4、足径19.3×12.9 cm；天青纯净、没有开片；椭圆形，侈口、深壁、平底，下接云头形四足；棱角转折之处微呈浅粉；底有六枚支钉痕，胎米黄；传世可见汝窑水仙盆六件，五件在台北故宫、一件在大阪市立东洋陶磁美术馆；引曹昭《格古要论》“有蟹爪纹者真，无纹者尤好”；乾隆摩挲把玩，加刻御制诗并重配带抽屉的木座；底刻诗文与“比德”“朗润”二印；600 万像素图 CC BY 4.0，标示“汝窯 青瓷無紋水仙盆。國立故宮博物院，台北，CC BY 4.0 @ www.npm.gov.tw”；主图为 PAC 视角 3059×2288，底面图 PCY 视角 3240×2160", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=34&dep=U"}, {"label": "台北故宫博物院 · 精选赏析：汝窑青瓷无纹水仙盆", "claim": "平底凸出窄边棱，四云头形足；底边釉积处略含淡碧色；口缘与棱角釉薄处呈浅粉色；裹足支烧，底有六个细支钉痕；釉面纯洁无纹片，此种传世稀少", "url": "https://theme.npm.edu.tw/selection/Article.aspx?sNo=04001033"}, {"label": "台北故宫博物院 · 开放资料 IIIF 清单", "claim": "水仙盆 82 个视角的 IIIF 清单（含 PAC 正侧面、PCY 底面）", "url": "https://digitalarchive.npm.gov.tw/Integrate/GetJson?cid=34&dept=U"}, {"label": "大英博物馆 · 汝窑笔洗鉴定新闻稿（2021）", "claim": "汝窑只在约 1086–1125 年间短期烧造，专供北宋宫廷；存世已知不足 100 件", "url": "https://www.britishmuseum.org/sites/default/files/2021-10/Rare_Ru_ware_at_British_Museum_confirmed_by_forensic_experts.pdf"}, {"label": "故宫博物院 · 汝窑", "claim": "烧造年代约在北宋哲宗元祐元年（1086）到徽宗崇宁五年（1106）；多裹足支烧，底留细小支钉痕；釉面有细小纹片（蟹爪纹）；传世品极少（与大英博物馆 1086–1125 之说并存，本厅 yrs 用 c. 1086 – 1125，墙文不写具体年）", "url": "https://www.dpm.org.cn/lemmas/239400.html"}, {"label": "中新社 · 专访汝窑遗址发现者范冬青", "claim": "1986 年上海博物馆派员到宝丰清凉寺实地调查，采到汝窑标本，确认窑址；1987 年公布“汝窑的发现”（河南省文物考古研究所 1987 年 10 月起试掘）", "url": "https://www.sh.chinanews.com.cn/wenhua/2023-03-20/109299.shtml"}, {"label": "河南省文物考古研究院 · 清凉寺汝官窑遗址展示馆开馆", "claim": "汝窑在北宋晚期（哲宗、徽宗时期）为皇宫烧造贡瓷；该院 1987 年起对宝丰县大营镇清凉寺村窑址调查、试掘，至 2016 年共 14 次发掘，发现汝窑中心烧造区；2000 年度全国十大考古新发现", "url": "https://hnswwkgyjy.cn/NewsView.php?News_ID=388"}, {"label": "平顶山市文物局 · 清凉寺汝官窑遗址", "claim": "1987–2016 年十四次发掘，发现 20 多座烧制御用汝瓷的窑炉及作坊遗迹；2001 年列为第五批全国重点文物保护单位", "url": "https://wglj.pds.gov.cn/contents/12739/241477.html"}, {"label": "中国社会科学院历史研究所 · 刘明杉《历史谜团：汝窑窑址寻踪》", "claim": "御用汝瓷先素烧一次再施釉烧制；椭圆小窑、木柴为燃料；支烧具有垫饼和垫圈，支钉小而尖，钉痕细小如芝麻；支钉数依器形而定，水仙盆等椭圆器底部六个支烧痕；匣钵外涂耐火泥；以火照测窑温；1987 年河南省考古研究所首次试掘", "url": "http://lishisuo.cssn.cn/xsyj/gdwhs/202001/t20200116_5078680.shtml"}, {"label": "维基文库 · 陶宗仪《南村辍耕录》卷二十九", "claim": "引南宋叶寘《坦斋笔衡》：“本朝以定州白磁器有芒不堪用，遂命汝州造青窑器……汝窑为魁”；政和间京师自置官窑；中兴渡江后于修内司置窑造青器，后于郊坛下另立新窑；并引陆龟蒙“九秋风露越窑开”，谓唐世已有秘色", "url": "https://zh.wikisource.org/zh-hans/%E5%8D%97%E6%9D%91%E8%BC%9F%E8%80%95%E9%8C%84_(%E5%9B%9B%E9%83%A8%E5%8F%A2%E5%88%8A%E6%9C%AC)/%E5%8D%B7%E4%B9%8B%E4%BA%8C%E5%8D%81%E4%B9%9D"}, {"label": "维基文库 · 赵令畤《侯鲭录》卷八", "claim": "苏轼与二郎侄书：“凡文字，少小时须令气象峥嵘，采色绚烂，渐老渐熟，乃造平淡。其实不是平淡，绚烂之极也。”（原讲作文，本展借来看器）", "url": "https://zh.wikisource.org/zh-hans/%E4%BE%AF%E9%AF%96%E9%8C%B2_(%E5%9B%9B%E5%BA%AB%E5%85%A8%E6%9B%B8%E6%9C%AC)/%E5%85%A8%E8%A6%BD"}, {"label": "维基文库 · 赵希鹄《洞天清录》序", "claim": "“明窗净几……时取古人妙迹，以观鸟篆蜗书，奇峰远水；摩娑钟鼎，亲见商周。”（序中讲法书名画、古琴旧砚、钟鼎，不涉瓷器；墙上只借来说宋人书斋）", "url": "https://zh.wikisource.org/zh-hans/%E6%B4%9E%E5%A4%A9%E6%B8%85%E9%8C%84"}, {"label": "维基文库 · 《礼记·聘义》", "claim": "“夫昔者君子比德于玉焉：温润而泽，仁也。”水仙盆底乾隆诗末印文“比德”（未上墙，供展项与转场参考）", "url": "https://zh.wikisource.org/zh-hans/%E7%A6%AE%E8%A8%98/%E8%81%98%E7%BE%A9"}, {"label": "英文维基百科 · 汝窑", "claim": "汝窑约 1100 年前后为宫廷短期烧造，存世完整器不足 100 件；绝大多数素面，极少数有印花；釉裹足，以三至五枚小支钉支烧，底留芝麻状钉痕；许多有细开片，有证据表明最受推崇的是无开片者，开片并非有意；大英博物馆称烧造约二十或四十年，在 1086 与 1106 或 1125 年之间；清雍正朝以宫中藏品送景德镇仿制；台北这件无开片水仙盆", "url": "https://en.wikipedia.org/wiki/Ru_ware"}, {"label": "中文维基百科 · 汝窑", "claim": "开片由釉与胎的冷热收缩比例不同而成；目前公布的汝窑传世品中无纹片者只有台北故宫青瓷无纹水仙盆一件；汝官窑多采裹足支烧，椭圆洗、水仙盆用六支钉", "url": "https://zh.wikipedia.org/zh-cn/%E6%B1%9D%E7%AA%91"}, {"label": "英文维基百科 · 青瓷", "claim": "青瓷的颜色来自釉中少量氧化铁在高温还原气氛中由三价铁转为二价铁；颜色随还原程度、釉厚、温度而变，从淡绿、蓝到黄都有", "url": "https://en.wikipedia.org/wiki/Celadon"}, {"label": "台北故宫博物院 · 定窑白瓷婴儿枕", "claim": "定窯 白瓷嬰兒枕，故瓷004923N000000000，北宋，西元12世纪；通高18.8、底径长31.0、宽13.2 cm；孩童伏卧榻上；兼采刻花、印花；底刻乾隆三十八年（1773）御制诗；图像 PAB 视角 CC BY 4.0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=72&dep=U"}, {"label": "克利夫兰艺术博物馆 · 钧窑盖罐", "claim": "Jar with Cover，1100s，China, Henan province, Yuxian, Northern Song dynasty (960–1127) or Jin dynasty (1115–1234)；porcelaneous stoneware with blue glaze and splashes of purple, Jun ware；直径 12.1 cm，高 9.5 cm；1957.36；CC0；馆方说明：紫斑是在釉上泼或刷含铜的料再烧成，像日落时的紫色霞光", "url": "https://www.clevelandart.org/art/1957.36"}, {"label": "克利夫兰艺术博物馆 · 开放获取数据 1957.36", "claim": "同上，馆方开放 API；图像 1957.36_print.jpg 3400×3045", "url": "https://openaccess-api.clevelandart.org/api/artworks/1957.36"}, {"label": "台北故宫博物院 · 官窑青瓷琮式瓶", "claim": "官窯 青瓷琮式瓶，故瓷016606N000000000，南宋，西元12–13世纪；高18.8、口径12.8、底径12.4 cm；仿五节玉琮形制；粉青厚釉，开片密布；图像 PAB 视角 CC BY 4.0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=19&dep=U"}, {"label": "台北故宫博物院 · 龙泉窑青瓷凤耳瓶", "claim": "龍泉窯 青瓷鳳耳瓶，故瓷017827N000000000，南宋，西元13世纪；高25.5、口径9.4、足径9.6 cm；凤耳模印后接于颈；釉色粉青敦厚；图像 PAB 视角 CC BY 4.0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=49&dep=U"}]};

