(window.EH_ROOMS=window.EH_ROOMS||{})["hanjiang"]={"id": "hanjiang", "zh": "寒江", "lat": "Southern Song", "yrs": "1127 – 1279 CE", "one": "只画一叶小舟，空白成了江", "wall": "#C9CCC4", "wallWhy": "墙色取月白里带一点烟青，是全馆最亮、最空的一面墙：这幅画只在绢上画了一叶小舟，其余全是空白，墙也跟着退后，只留冲淡的平光。画幅很小，本厅不把它放大铺满，四周留出大片空处。它今天装成一幅挂轴，墙上的装裱为示意，不是原件的装裱。", "ink": "dark", "frame": "mount", "art": {"img": "main.webp", "w": 2400, "h": 1277, "who": "马远（传）", "whoLat": "Ma Yuan, active c. 1190 – 1225", "title": "《寒江独钓图》", "short": "《寒江独钓图》", "meta": ["南宋，13 世纪，绢本墨画淡彩", "26.7 × 50.6 cm", "东京，东京国立博物馆（TA-140）"], "credit": "Wikimedia Commons, File:Angler on a Wintry Lake, by Ma Yuan, 1195.jpg — 来源 e国宝（国立文化财机构），公有领域"}, "lede": "南宋的宫廷画院里，山水越画越空。这幅传为马远所作的小画，把空白留给了一整条江。", "work": "绢上只有一叶小舟。渔人弓着身子坐在船的一头，双手握竿，竿上装着一个线轮，钓丝斜斜垂进水里。船的另一头高高翘起，舱里堆着一只圆顶的竹编物和一捆草束。船边、钓丝入水处画了几道极细的水纹，此外四面都是空绢：没有岸，没有远山，也分不出哪里是水、哪里是天。江有多宽、有多冷，都留给看画的人。", "quote": ["空本难图，实景清而空景现；神无可绘，真境逼而神境生。位置相戾，有画处多属赘疣；虚实相生，无画处皆成妙境。", "笪重光《画筌》，清康熙年间"], "origin": "马远生在钱塘，即南宋都城临安，家里从北宋起几代人都是宫廷画院的画家。他大约在光宗、宁宗两朝供职，是画院待诏。这幅画右下角有一方“辛未坤宁秘玩”印，坤宁殿是宁宗恭圣皇后的居所，可见它曾藏在宫中。东京国立博物馆指出，舟的上方有一道绢的接缝，原本可能是更大的画面，后来被裁成现在的样子。今天看到的这片空白，有多少出自画家本意，本展不作裁决。", "traits": [["马一角", "马远的山水常把山石集中在画面一边、一角，另一边大片留空，人称“马一角”。他承家学，又学李唐而自出新意：北宋满幅的大山，到这里退到了角上。"], ["计白当黑", "清人包世臣记邓石如论书：字画疏处可以走马，密处不使透风，“常计白以当黑”。这原是讲书法的布白，借来看画也通：没画的地方同样算进构图。"], ["帝后题画", "南宋画院的画常和宫里的字配在一起：宁宗在马远《踏歌图》上抄录王安石的诗，杨皇后为《水图》题写图名。画家作画，帝后题字，诗与画出自同一座宫廷。"], ["减笔", "同一时期的梁楷做过画院待诏，后来离开画院。他的《泼墨仙人》只用几笔淡墨、浓墨，就画出一个醉醺醺的仙人。笔墨越减，留给观者的越多。"]], "special": {"title": "点空成水", "type": "blank_water_fishing", "text": "这幅画里的水，只在船边画了几道细线，其余全是空绢。握住钓竿甩一竿：线落在空白处，那里就荡开几圈淡淡的水纹，笔意照画里船边那几道。水纹一圈圈扩开，碰到看不见的岸又弹回来，你才量出这条没画出来的江有多宽。线落在舟上、人身上，就不起水纹。线落下后等一等，竿梢一颤，就跟着节奏收线、放线。水纹只画在这件复制品上，关上就没了。", "labels": {"cast": "甩竿", "reel": "收线"}, "hints": {"start": "按住拖动蓄力，松开，把线甩出去", "startTouch": "手指按住往后拉，松开，把线甩出去", "keys": "键盘：按住 ↓ 蓄力，松开甩线；竿梢一颤后，按住 ↑ 收线，松开放线", "keysAim": "A、D 转竿", "aim": "往空白处甩", "weak": "力气小了，线落在船边", "cast": "线飞出去了", "water": "落进空白，水纹荡开了", "out": "落到画外去了：江在画外还在，水纹从画边荡进来", "boat": "落在船上了，不起水纹，收回来再甩", "figure": "落在渔人身上了，收回来再甩", "seal": "落在印上了：印是盖在绢上的，不是江，收回来再甩", "shore": "水纹碰到看不见的岸，弹了回来", "measure": "这一竿量出：江面至少宽 {w}", "wait": "等一等", "bite": "竿梢一颤", "reel": "收线", "slack": "放线", "tooFast": "收得太急，线绷紧了，放一放", "tooSlow": "线松了，接着收", "steady": "一收一放，跟上了", "snap": "线断了：它往外冲的时候，你还在收", "slip": "线松得太久，它脱钩走了", "miss": "竿梢颤了几回都没收住，它走了", "caught": "收上来一尾小鱼，又放回了江里", "landed": "线收回来了", "again": "换一处空白，再甩一竿"}, "captions": {"unit": "厘米（按原画尺寸折算；看不见的两岸位置是本展设想）", "casts": "甩了 {n} 竿", "widest": "量到最宽 {w}", "shores": "水纹碰岸 {n} 次", "fish": "钓起 {n} 尾", "verdict": "整片空白都是水，而且有边、有宽", "side": "往左右去的水纹一去不回：江还在往两头流", "ripple": "水纹画法照原作船边的细线", "reel": "画里的钓竿上装着一个线轮；据李约瑟《中国科学技术史》，这是已知最早画出渔轮的图像", "source": "传马远《寒江独钓图》，南宋，东京国立博物馆"}, "img": "main.webp", "imgW": 2400, "imgH": 1277, "pxPerCm": 47.43, "zones": {"note": "坐标为 main.webp（2400×1277）像素 [x, y, w, h]，目测于 25 px 网格，误差约 ±5 px；详见 notes.md", "figure": [700, 668, 135, 152], "boat": [676, 645, 875, 228], "reel": [672, 744, 30, 28], "rod": [[722, 756], [686, 757], [586, 773]], "line": [[586, 773], [560, 800], [520, 828], [460, 850], [400, 868], [352, 877]], "lineEntry": [352, 877], "ripples": [[330, 850, 380, 125], [560, 845, 950, 65], [1480, 720, 360, 100]], "seal": [2250, 1135, 150, 142]}}, "works": [{"img": "w1.webp", "w": 887, "h": 1200, "who": "李唐", "whoLat": "Li Tang, c. 1049 – after 1130", "title": "《万壑松风图》", "meta": ["北宋宣和六年（1124），绢本设色", "188.7 × 139.8 cm", "台北，台北故宫博物院"], "note": "北宋的满幅：主峰顶天，松、瀑、云挤满画面。", "credit": "台北故宫博物院开放资料, File:K2A000896N000000000PGZ.jpg — 宋李唐萬壑松風圖 軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w2.webp", "w": 702, "h": 1200, "who": "马远", "whoLat": "Ma Yuan, active c. 1190 – 1225", "title": "《踏歌图》", "meta": ["南宋，绢本设色", "192.5 × 111 cm", "北京，故宫博物院（新00146618）"], "note": "山路上六个人踏歌而行，顶上是宁宗的题字。", "credit": "Wikimedia Commons, File:马远踏歌图轴.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w3.webp", "w": 1200, "h": 770, "who": "马远", "whoLat": "Ma Yuan, active c. 1190 – 1225", "title": "《水图》（洞庭风细）", "meta": ["南宋，绢本淡设色，十二段之一", "每段 26.8 × 41.6 cm", "北京，故宫博物院（新00146619）"], "note": "只画水：细鳞般的波纹，远处水天一色。", "credit": "Wikimedia Commons, File:马远水图卷.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w4.webp", "w": 682, "h": 1200, "who": "梁楷", "whoLat": "Liang Kai, active late 12th – early 13th c.", "title": "《泼墨仙人》", "meta": ["南宋，纸本水墨，册页", "48.7 × 27.7 cm", "台北，台北故宫博物院"], "note": "几笔湿墨成了衣袍，五官只用几根细线勾出。", "credit": "台北故宫博物院开放资料, File:K2A001292N000000002PAB.jpg — 名畫琳瑯 冊 宋梁楷潑墨仙人 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}], "chain": "之前：上一厅的汝窑把颜色减到一色，这一厅把山水减到一角。之后：马远、夏圭的画风被称为“马夏”，传到日本，影响了周文、雪舟。下一厅到了元代，山水多从绢上转到了纸上，笔墨本身成了主角。", "sources": [{"label": "东京国立博物馆（e国宝）· 寒江独钓图", "claim": "寒江独钓图（絹本淡彩寒江独釣図）：传马远笔，南宋 13 世纪，绢本墨画淡彩，26.7×50.6，1 幅（挂轴），东京国立博物馆 TA-140，重要文化财；舟的略上方有绢的接缝，原本可能是更大画面；有源自宁宗妃恭圣皇后所居坤宁殿的“辛未坤宁秘玩”印（e国宝 IIIF 清单与解说）", "url": "https://emuseum.nich.go.jp/detail?langId=zh&webView=&content_base_id=100823&content_part_id=0"}, {"label": "东京国立博物馆 · ColBase 寒江独钓图", "claim": "ColBase：寒江独釣図，伝馬遠筆，南宋時代・13世紀，絹本墨画淡彩，本紙 縦26.7 横50.6，TA-140；解说称现在推测原本是更大的画面，被巧妙裁成现状", "url": "https://colbase.nich.go.jp/collection_items/tnm/TA-140"}, {"label": "维基共享资源 · 主图文件页", "claim": "File:Angler on a Wintry Lake, by Ma Yuan, 1195.jpg，5906×3159，来源 emuseum.jp，公有领域；文件名里的 1195 年无馆方依据，本展不用", "url": "https://commons.wikimedia.org/wiki/File:Angler_on_a_Wintry_Lake,_by_Ma_Yuan,_1195.jpg"}, {"label": "故宫博物院 · 马远踏歌图轴", "claim": "《踏歌图》轴，南宋马远，绢本设色，纵 192.5、横 111 cm，新00146618；画中六人；上方五言绝句为宁宗赵扩抄录北宋王安石诗（“垄上踏歌行”）；马远构图多用边角，有“马一角”之称，在本图中不十分明显；马远小传（生卒年不详，活跃于 13 世纪初，祖籍河中，生于钱塘（今杭州），曾祖、祖父、伯、兄及本人均为画院待诏，活动于光宗、宁宗年间，山水始承家学，后学李唐而自出新意；大致活动于光宗、宁宗年间）", "url": "https://www.dpm.org.cn/collection/paint/234559.html"}, {"label": "故宫博物院 · 马远水图卷", "claim": "《水图》卷，南宋马远，绢本淡设色，共十二段，每段纵 26.8、横 41.6 cm，新00146619；第一段残缺无图名，其余图名“洞庭风细”等；“洞庭风细”波浪如鳞，近大远小以至水天一色", "url": "https://www.dpm.org.cn/collection/paint/229607.html"}, {"label": "故宫名画记 · 马远水图卷", "claim": "名画记称“每段图均有宁宗杨皇后题”（主图与 w3 图源）；故宫官网则说第一段残缺无图名，墙上只写“杨皇后为《水图》题写图名”", "url": "https://minghuaji.dpm.org.cn/paint/appreciateDetail?id=df3320e6acc646118a50505d5562a132&type=1191"}, {"label": "大都会艺术博物馆 · 马远《观瀑图》", "claim": "马远生卒写法：Chinese, active ca. 1190–1225", "url": "https://www.metmuseum.org/art/collection/search/40086"}, {"label": "英文维基百科 · 马远", "claim": "马远约生于 1160–65 年，卒于 1225 年；1189 年后入光宗画院，受宁宗赏识；“一角”构图；与夏圭合称马夏；影响浙派及日本周文、雪舟", "url": "https://en.wikipedia.org/wiki/Ma_Yuan_(painter)"}, {"label": "英文维基百科 · 渔轮", "claim": "据李约瑟《中国科学技术史》第 4 卷第 2 分册第 100 页及图版 CXLVII，已知最早的渔轮图像出自马远《寒江独钓图》（仅此转引，展项字幕写“据李约瑟”）", "url": "https://en.wikipedia.org/wiki/Fishing_reel"}, {"label": "维基文库 · 笪重光《画筌》", "claim": "“空本难图，实景清而空景现；神无可绘，真境逼而神境生。位置相戾，有画处多属赘疣；虚实相生，无画处皆成妙境。”（原文繁体，引文据此转简体）", "url": "https://zh.wikisource.org/zh-hant/%E7%95%AB%E7%AD%8C"}, {"label": "荣宝斋 · 笪重光《画筌》境界论的内涵及其意义", "claim": "《画筌》为清笪重光所著山水画论，康熙年间刊行", "url": "https://www.rongbaozhai.cn/index.php?m=shukan&c=index&a=show&shukanid=8&modelid=28&showid=59"}, {"label": "光明日报 ·“计白当黑”：邓石如的书、印、诗", "claim": "包世臣《艺舟双楫·述书上》记邓石如语：“字画疏处可以走马，密处不使透风，常计白以当黑，奇趣乃出”，原讲书法篆刻", "url": "https://epaper.gmw.cn/gmrb/html/2019-10/11/nw.D110000gmrb_20191011_1-16.htm"}, {"label": "台北故宫博物院 · 宋李唐万壑松风图", "claim": "宋李唐万壑松风图轴：宣和六年（1124），本幅 188.7×139.8 cm，绢本设色；李唐约 1049–1130 年后；石壁款“皇宋宣和甲辰春河阳李唐笔”；斧劈皴；李唐约三十年后在南方重入高宗画院", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=33&dep=P"}, {"label": "台北故宫博物院 · 宋梁楷泼墨仙人", "claim": "名画琳琅册 宋梁楷泼墨仙人：本幅 48.7×27.7 cm，纸本；款“梁楷”；乾隆题诗；梁楷嘉泰年间（1201–1204）任画院待诏；仙人烂醉之态，衣裙以淋漓水墨写出，头部与五官用细线钩描；减笔；开放资料署名须写“名畫琳瑯 冊 宋梁楷潑墨仙人。國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw”", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=14658&dep=P"}, {"label": "台北故宫博物院（Google 艺术与文化）· 泼墨仙人", "claim": "Liang Kai (fl. late 12th–early 13th c.)；48.7×27.7 cm，名画琳琅册第二开，纸本水墨；梁楷 1210 年任画院待诏、赐金带不受，挂于院内而去；此开据说是他纵酒作画时期之作，属减笔", "url": "https://artsandculture.google.com/asset/immortal-in-splashed-ink-liang-kai-fl-late-12th-early-13th-c/FgFbbKapEvMSLg?hl=en"}, {"label": "大英百科全书 · 马远", "claim": "马远与夏圭的画风形成“马夏派”：不对称构图、简化墨色；此派在日本受到推重，深刻影响室町时代水墨画家周文、雪舟及早期狩野派", "url": "https://www.britannica.com/biography/Ma-Yuan-Chinese-painter"}, {"label": "英文维基百科 · 夏圭", "claim": "夏圭活跃于 1195–1224 年，承李唐，与马远合称马夏派", "url": "https://en.wikipedia.org/wiki/Xia_Gui"}, {"label": "维基共享资源 · 踏歌图文件页", "claim": "File:马远踏歌图轴.png，7831×13391，来源故宫名画记，公有领域", "url": "https://commons.wikimedia.org/wiki/File:%E9%A9%AC%E8%BF%9C%E8%B8%8F%E6%AD%8C%E5%9B%BE%E8%BD%B4.png"}, {"label": "维基共享资源 · 水图卷文件页", "claim": "File:马远水图卷.png，127821×3400，来源故宫名画记，公有领域；本厅取第二段“洞庭风细”", "url": "https://commons.wikimedia.org/wiki/File:%E9%A9%AC%E8%BF%9C%E6%B0%B4%E5%9B%BE%E5%8D%B7.png"}]};

