(window.EH_ROOMS=window.EH_ROOMS||{})["fuchun"]={"id": "fuchun", "zh": "富春", "lat": "Yuan Dynasty", "yrs": "1271 – 1368 CE", "one": "一支干笔，在纸上写出富春江", "wall": "#E3DDCF", "wallWhy": "墙色取元人纸本的纸白，和上一厅寒江的月白亮度相近，但暖一档：画从绢换到了纸。手卷本来平放在案上，从右往左一段段展开看，所以本厅不加框，也不仿造它的装裱，只挂画心，照原样横陈。", "ink": "dark", "frame": "none", "art": {"img": "t_win.webp", "w": 2600, "h": 1259, "who": "黄公望", "whoLat": "Huang Gongwang, 1269 – 1354", "title": "《富春山居图》（无用师卷）", "short": "《富春山居图》", "meta": ["元至正十年（1350），纸本水墨", "33 × 636.9 cm", "台北，台北故宫博物院（故画001016）"], "credit": "台北故宫博物院开放资料, File:K2A001016N000000000PAA–PAW.jpg（23 段拼合） — 元黃公望富春山居圖　卷。國立故宮博物院，台北，CC BY 4.0 @ www.npm.gov.tw"}, "lede": "至正七年（1347），黄公望和道友无用师一同回到富春山居，在一卷纸上起笔，断断续续画了三四年。", "work": "手卷从右往左看。一条江贯穿全卷：卷首是坡岸丛树和几间村舍，往左江面开阔，远渚一抹；再往左群峰连绵，松林间藏着山坳，然后是长长的平沙坡陀、远汀疏林和一两只渔舟，最后一座孤峰收住。山石用一道道又长又干的淡墨顺着山势拖下，叫披麻皴，纸上擦出细碎的飞白。卷首江面上方的行楷是乾隆命梁诗正写的，判这卷为仿本，后来公认判错了。", "quote": ["无用过虑有巧取豪敚者，俾先识卷末，庶使知其成就之难也。", "黄公望《富春山居图》卷末自题，至正十年（1350）"], "origin": "元朝建立后几十年不开科举，到 1315 年才重开，许多读书人不再以做官为出路，在书斋里写字作画。元初赵孟頫倡导“古意”，把书法的用笔带进画里，一改南宋画院的旧习。文人画家偏爱纸：纸吃墨快，笔的轻重快慢、干湿浓淡都留得下来。黄公望在大都做过书吏，曾入狱，后来隐居苏南和富春山，是全真教徒。后人把他和吴镇、倪瓒、王蒙并称“元四家”，他居首。", "traits": [["书画同源", "赵孟頫在《秀石疏林图》卷后自题：“石如飞白木如籀……方知书画本来同。”画石用写飞白的笔法，画树用写篆籀的笔法，画是写出来的。"], ["从绢到纸", "绢面细密，适合一层层渲染；纸吸墨快，一笔下去，轻重快慢、干湿浓淡都留在纸上，干笔一擦就见飞白。元代文人作画多选纸。"], ["逸笔草草", "倪瓒说自己的画“不过逸笔草草，不求形似，聊以自娱耳”。画不为宫廷，也不为主顾，先给自己和几个朋友看。"], ["题在画上", "元人把诗和题记直接写在画面空处，字也是构图的一部分。后来的收藏者再加题跋、钤印，一卷画上叠着它几百年的流传。"]], "special": {"title": "卷着烧过", "type": "burnt_scroll_reroll", "text": "清顺治七年（1650），收藏者吴洪裕临终要拿此卷殉葬，投进火里，侄子从火中把它抢了出来。卷首一段烧坏，后来分成两卷：前面一小段叫《剩山图》，今藏浙江省博物馆；后面的长卷就是墙上的无用师卷。学者余辉据火痕数出两段上共五处火洞，后人补过笔墨，火洞越往里越小。无用师卷卷首的天空里有三块形状相似的斑痕，相隔都约 18 厘米，越往里越淡。把这段复制品卷起来，看它们会不会叠成一处。", "hint": {"mouse": "在桌上往右拖，把纸卷起来（松手它还会滚一阵）；也可以按住“卷起”，或按 D（A 是摊开）。再把下面那一小段《剩山图》拖到卷首接上，或按回车。", "touch": "手指在桌上横着往右推，把纸卷起来；或按住“卷起”。再把下面那一小段《剩山图》拖到卷首接上，或点“合璧”。"}, "labels": {"roll": "卷起", "unroll": "摊开", "join": "合璧", "split": "分开"}, "endLabel": "卷端（示意）", "lines": {"start": "这是无用师卷卷首一段的复制品，右端是卷首。往右拖，把它卷起来。", "first": "第 1 块斑痕卷进去了。记住它在卷上的位置。", "land": "第 {n} 块斑痕卷上来，正好落在前一块上面。", "edge": "卷到卷首，三块斑痕叠成了一处，卷首的断口也转到这里。它们像是卷着的时候，从卷外同一处一层层透进去的。", "fire": "如果是卷着烧，火先烧外面几圈，越往里越轻：斑痕正是越往里越淡。", "back": "摊开了：斑痕又一块块分开。", "joined": "《剩山图》接回卷首。两段此后分开流传，一在杭州浙江省博物馆，一在台北故宫；2011 年夏，两段在台北合璧展出。", "joinedRoll": "接上以后，《剩山图》在更外面几圈；据余辉推算，它外面还有四十多厘米画面，整段烧没了。", "split": "两段又分开了。", "rolledNoJoin": "卷首还卷着，接不上：先摊开一点。"}, "note": "纸卷是本展制作的复制品：斑痕位置按台北故宫藏卷实测，卷的粗细按斑痕间距推算（一圈约 18 厘米，直径约 6 厘米），卷端剖面为示意，层距放大；斑痕是火痕是本展的推断（余辉也指出火洞越往里越小）。《剩山图》图像：浙江省博物馆藏，维基共享资源，公有领域。", "scorch": {"note": "无用师卷卷首三块斑痕，main.webp 像素 [x, y, w, h]（目验，±15 px）；右→左 = 卷外→卷里；见 notes.md", "main": [[15495, 160, 115, 225], [15040, 165, 120, 225], [14615, 180, 95, 210]], "cmFromHead": [17.8, 35.8, 53.4]}}, "works": [{"img": "w1.webp", "w": 1200, "h": 742, "who": "黄公望", "whoLat": "Huang Gongwang, 1269 – 1354", "title": "《剩山图》", "meta": ["元，纸本水墨", "31.8 × 51.4 cm", "杭州，浙江省博物馆"], "note": "一座大山几乎占满画幅，山脚是村舍和江岸。", "credit": "Wikimedia Commons, File:富春山居圖(剩山圖).jpg — 来源 台北故宫“山水合璧”特展网页，公有领域"}, {"img": "w2.webp", "w": 1200, "h": 519, "who": "赵孟頫", "whoLat": "Zhao Mengfu, 1254 – 1322", "title": "《秀石疏林图》", "meta": ["元，纸本水墨", "27.5 × 62.8 cm", "北京，故宫博物院（新00147132）"], "note": "古木、新竹、秀石，全用水墨，不设色。", "credit": "Wikimedia Commons, File:赵孟頫秀石疏林图卷.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w3.webp", "w": 578, "h": 1200, "who": "倪瓒", "whoLat": "Ni Zan, 1301 – 1374", "title": "《容膝斋图》", "meta": ["1372 年（明洪武五年），纸本水墨", "74.7 × 35.5 cm", "台北，台北故宫博物院（故画000299）"], "note": "一河两岸，空亭无人；两年后补题赠友。", "credit": "台北故宫博物院开放资料, File:K2A000299N000000000PAA.jpg — 元倪瓚容膝齋圖　軸。國立故宮博物院，台北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w4.webp", "w": 496, "h": 1200, "who": "王蒙", "whoLat": "Wang Meng, 1308 – 1385", "title": "《葛稚川移居图》", "meta": ["元，纸本设色", "139 × 58 cm", "北京，故宫博物院（新00133388）"], "note": "山重岭复，满纸皴擦，和倪瓒正相反。", "credit": "Wikimedia Commons, File:王蒙葛洪移居图轴.png — 来源 故宫博物院名画记，公有领域"}], "chain": "之前：南宋画院在绢上层层渲染，马远把山水画得越来越空。之后：明代沈周临过这一卷，董其昌收藏过它；清初“四王”奉黄公望为正宗，四人都反复仿他。元人在纸上“写”出来的山水，成了此后几百年文人画的底子。", "sources": [{"label": "台北故宫博物院 · 元黄公望富春山居图卷", "claim": "故画001016；黄公望；元顺帝至正十年（1350）；本幅纸，33 × 636.9 cm，拖尾 32.5 × 324.8 cm；黄公望自题全文（至正七年归富春山居、无用师偕往、阅三四载、“无用过虑有巧取豪敚者，俾先识卷末，庶使知其成就之难也”、十年庚寅书于云间夏氏知止堂）；梁诗正奉敕书乾隆御识（行楷书，写在本幅，称此卷“其伪赝鼎无疑”）；董其昌隔水跋（藏之画禅室）；沈周、文彭、邹之麟等跋；CC BY 4.0 署名文字；馆方说明：至正七年偕道友郑无用回到富春，历三四年作成此卷，由六纸接成", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/1194?dep=P"}, {"label": "台北故宫博物院 · 富春山居图 IIIF 清单", "claim": "主图来源：23 段馆方分段图（PAA–PAW）与全卷缩略图，CC BY 4.0；本展拼合画心，未调色；卷首三块斑痕位置据此实测（距画心右缘约 17.8、35.8、53.4 cm，间距约 17–18 cm）", "url": "https://digitalarchive.npm.gov.tw/Integrate/GetJson?cid=1194&dept=P"}, {"label": "故宫博物院 · 黄公望", "claim": "黄公望 1269—1354，字子久，号大痴道人，常熟人；早年在大都监察御史院当书吏，曾入狱，后隐逸于苏南和富春山，全真教徒；取法董源、巨然，又得赵孟頫“古意”；“元四家”之首", "url": "https://www.dpm.org.cn/lemmas/240417.html"}, {"label": "故宫名画记 · 黄公望", "claim": "同上（书吏、入狱、隐逸苏南和富春山、全真教、元四家之首）", "url": "https://minghuaji.dpm.org.cn/author/detail?id=14"}, {"label": "澎湃新闻 · 余辉《〈富春山居图〉“火前本”汇考》", "claim": "1650 年遭火焚；据《剩山图》和无用师卷的火痕边线，共有五处可辨的火洞和补绘笔墨，第三个火洞烧在两本之间，火洞向内越来越小，无用师卷前段有“两处半渐趋狭小的火洞”；包首及前隔水几乎全部焚毁，卷首 40 多厘米画面遭焚；无用师卷是黄公望为其师弟无用师所绘（2022-12-30）", "url": "https://www.thepaper.cn/newsDetail_forward_21325375"}, {"label": "维基百科 · 富春山居图", "claim": "1347–1350 年作；1650 年吴洪裕欲以此卷殉葬投入火中，侄子从火中救出，画卷烧成一大一小两段；《剩山图》31.8 × 51.4 cm；2011 年 6 月两段在台北故宫合璧展出（侄子名各书作吴静庵、吴贞度、吴子文，本展不写）", "url": "https://zh.wikipedia.org/wiki/%E5%AF%8C%E6%98%A5%E5%B1%B1%E5%B1%85%E5%9C%96"}, {"label": "中国新闻网 · 山水合璧：富春山居图特展", "claim": "2011 年 6 月至 9 月，台北故宫“山水合璧——黄公望与富春山居图特展”，浙江省博物馆藏《剩山图》与无用师卷合璧展出", "url": "https://www.chinanews.com.cn/tw/z/fcsjt2011/index.shtml"}, {"label": "浙江省博物馆 · 剩山图卷", "claim": "《剩山图》卷为《富春山居图》卷烬余本之前段，纸本墨笔，纵 31.8、横 51.4 cm；火痕宛然可辨", "url": "http://www.zhejiangmuseum.com/zjbwg/collection/collect_detail.html?id=2642"}, {"label": "故宫博物院 · 赵孟頫秀石疏林图卷", "claim": "新00147132；元；纸本墨笔；纵 27.5、横 62.8 cm；以飞白法写石、篆书法写树，纯用水墨；尾纸自题“石如飞白木如籀，写竹还于八法通。若也有人能会此，方知书画本来同”（本展按名画记高清图目验原迹，落款“子昂重题”）", "url": "https://www.dpm.org.cn/collection/paint/231246.html"}, {"label": "故宫名画记 · 赵孟頫秀石疏林图卷", "claim": "高清全卷图（含尾纸自题），w2 与原迹核对所用", "url": "https://minghuaji.dpm.org.cn/paint/detail?id=tqr72jhbh5t5f0b7awsi6sghvajc18z3"}, {"label": "故宫博物院 · 王蒙葛稚川移居图轴", "claim": "新00133388；元；纸本设色；纵 139、横 58 cm；画葛洪携家移居罗浮山途中；重山复岭，皴擦点染", "url": "https://www.dpm.org.cn/collection/paint/234561.html"}, {"label": "台北故宫博物院 · 元倪瓒容膝斋图轴", "claim": "故画000299；创作时间明太祖洪武五年（1372）；本幅纸，74.7 × 35.5 cm；壬子（1372）七月五日云林生写；甲寅（1374）三月四日补题赠仁仲医师，容膝斋为仁仲燕居之所", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/610?dep=P"}, {"label": "故宫博物院 · 倪瓒", "claim": "倪瓒 1301—1374，无锡人；自谓“逸笔草草，不求形似”；与黄公望、吴镇、王蒙并称“元四家”", "url": "https://www.dpm.org.cn/lemmas/240613.html"}, {"label": "故宫名画记 · 元代绘画简介", "claim": "元初赵孟頫等托古改制，一改南宋旧习；重视书法趣味，诗、书、画结合；强调“古意”；“元四家”黄公望、吴镇、倪瓒、王蒙", "url": "https://minghuaji.dpm.org.cn/page/detail?id=7&dynasty=18"}, {"label": "大都会艺术博物馆 · 元代革命展", "claim": "元代文人以纸为表现个人笔墨的首选材料（正式作品仍多用绢）；赵孟頫以书法用笔和画上题字主张书画相通", "url": "https://www.metmuseum.org/exhibitions/listings/2010/yuan-revolution"}, {"label": "大英百科 · 教育史：蒙古时期", "claim": "元仁宗（爱育黎拔力八达）1313 年下诏恢复科举，1315 年首科殿试，取进士 300 人", "url": "https://www.britannica.com/topic/education/The-Mongol-period-1206-1368"}, {"label": "故宫博物院 · 沈周仿黄公望富春山居图卷", "claim": "沈周曾仿（临）《富春山居图》", "url": "https://www.dpm.org.cn/collection/paint/234367.html"}, {"label": "大英百科 · 王时敏", "claim": "王时敏的主要作品是他毕生研习黄公望的结晶；“四王”代表承董其昌之说的“正统派”", "url": "https://www.britannica.com/biography/Wang-Shimin"}, {"label": "大都会艺术博物馆 · 清代的传统派", "claim": "清初在董其昌门人王时敏带领下形成正统派（“四王”），以一批古代大师为楷模；王时敏毕生研习黄公望，王原祁的构图也取自黄公望", "url": "https://www.metmuseum.org/essays/the-qing-dynasty-1644-1911-the-traditionalists"}, {"label": "维基共享资源 · 剩山图文件页", "claim": "File:富春山居圖(剩山圖).jpg，7260 × 900，公有领域，来源台北故宫 2011 特展网页；w1 只裁画心", "url": "https://commons.wikimedia.org/wiki/File:%E5%AF%8C%E6%98%A5%E5%B1%B1%E5%B1%85%E5%9C%96(%E5%89%A9%E5%B1%B1%E5%9C%96).jpg"}, {"label": "维基共享资源 · 秀石疏林图文件页", "claim": "File:赵孟頫秀石疏林图卷.png，38518 × 3315，公有领域，来源故宫名画记；w2 只裁画心", "url": "https://commons.wikimedia.org/wiki/File:%E8%B5%B5%E5%AD%9F%E9%A0%AB%E7%A7%80%E7%9F%B3%E7%96%8F%E6%9E%97%E5%9B%BE%E5%8D%B7.png"}, {"label": "维基共享资源 · 葛稚川移居图文件页", "claim": "File:王蒙葛洪移居图轴.png，6586 × 15923，公有领域，来源故宫名画记", "url": "https://commons.wikimedia.org/wiki/File:%E7%8E%8B%E8%92%99%E8%91%9B%E6%B4%AA%E7%A7%BB%E5%B1%85%E5%9B%BE%E8%BD%B4.png"}, {"label": "维基共享资源 · 剩山图（展项用图）文件页", "claim": "File:Dwelling in the Fuchun Mountains (first half).JPG，浙江省博物馆藏，公有领域（展项 s_shengshan.webp）", "url": "https://commons.wikimedia.org/wiki/File:Dwelling_in_the_Fuchun_Mountains_(first_half).JPG"}], "scroll": {"w": 16000, "h": 818, "win": [6874.7, 0.0, 8564.21, 818.0], "head": "right", "lo": "scroll/lo.webp", "loW": 3129, "loH": 160, "levels": [{"f": "scroll/a{i2}.webp", "w": 24623, "h": 1259, "tw": 1024}, {"f": "cut/hr/h{i2}.webp", "w": 37589, "h": 1922, "tw": 2048}]}};

