(window.EH_ROOMS=window.EH_ROOMS||{})["qinghua"]={"id": "qinghua", "zh": "青花", "lat": "Yuan Blue-and-White", "yrs": "c. 1330 – 1368 CE", "one": "画时是黑的，进窑烧成了蓝", "wall": "#20242B", "wallWhy": "墙色取深靛色的暗壁，把釉的白和钴的蓝都衬出来，蓝白对比是这一厅的主角。罐是立着、绕着看的器物，原本就没有框，本厅不加框。光从一侧慢慢走过釉面，好让人一层一层往上看纹样。", "ink": "light", "frame": "none", "art": {"img": "cut/main_cut.webp", "w": 1528, "h": 1690, "who": "佚名景德镇窑工", "whoLat": "Unknown Jingdezhen potter", "title": "《青花缠枝牡丹纹狮耳罐》", "short": "《青花狮耳罐》", "meta": ["元，14 世纪，景德镇青花瓷", "高 39.4 cm，宽 37.5 cm，口径 15.6 cm", "克利夫兰，克利夫兰艺术博物馆（1962.154）"], "credit": "克利夫兰艺术博物馆开放获取, File:1962.154_full.tif — 摄影 克利夫兰艺术博物馆，CC0"}, "lede": "14 世纪，江西景德镇的窑工用远道运来的钴料，在白瓷坯上作画。克利夫兰艺术博物馆称这只罐是元代青花的典型。", "work": "一只大罐，肩上一对狮头耳。纹样从口到底一层层分开：口沿回纹，颈上海浪，肩上缠枝莲，再下是一圈如意形的“云肩”，里面画凤凰穿花；腹部最宽处绕着一整圈缠枝牡丹，下面一道卷草，最下一排变形莲瓣。层层画满，几乎不留白。蓝色并不均匀：叶尖、花心这些料下得浓的地方，蓝里透出黑褐的斑点。", "quote": ["谢诗如芙蓉出水，颜如错彩镂金。", "钟嵘《诗品》引汤惠休；宗白华借来说两种美，本展借来看青花"], "origin": "元朝把中国和伊朗连在同一个蒙古帝国里，商路畅通。克利夫兰艺术博物馆认为，这只罐的钴料来自伊朗，很可能出自卡尚；最迟在 1330 年代，景德镇已在烧造这类青花，既供宫廷和民间使用，也销往海外。云肩里凤凰穿花这套纹样，同时期伊朗伊儿汗国的装饰里也能见到。罐肩的白釉上刻着“宫”“南”二字，馆方推测它曾存放在某座宫殿的固定位置。", "traits": [["分带，画满", "元青花常把器身分成一道道纹带，主纹与边饰交替，从口沿一直画到足。和宋代名窑多凭一层釉的素净相反，它要的是繁密和浓艳。"], ["釉下一次烧成", "钴料画在未上釉的坯上，外面罩一层透明釉，入窑高温一次烧成。蓝色封在釉层底下，不怕磨，也不会褪。"], ["远道而来的蓝", "元代青花多用从西亚运来的钴料，蓝色浓艳。后来景德镇改用国产钴料，蓝色渐渐变得淡雅。"], ["为远方而烧", "元青花大量销往西亚和东南亚。伊朗阿德比尔神祠旧藏（今多在德黑兰）和土耳其托普卡帕宫，都有成批的中国青花。"]], "special": {"title": "看不见颜色地画", "type": "cobalt_blind_paint", "text": "窑工在晾干的素坯上用钴料作画。坯会吸水，笔一落下，料就渗进去，擦不掉，也改不了。料在坯上发灰发黑，看不出蓝，浓淡全凭手上的轻重和经验。画完罩一层透明釉，入窑高温烧过，开窑才知道蓝得多浓、晕成了什么样。这里的转盘、笔、窑和烧出的颜色都是本展的示意，不是复原。", "hints": {"start": "一只晾干的素坯坐上转盘，笔已经蘸好了料", "spin": "转一转坯，找个地方下笔", "paint": "在坯上拖动，画一笔", "paintTouch": "手指在坯上拖动，画一笔", "load": "重新蘸料：料浓，烧出来深；料淡，烧出来浅", "dry": "笔上的料快干了，再蘸一次", "heavy": "这一笔下得重，料积起来了", "light": "这一笔很淡，几乎看不出来", "noUndo": "料已经吃进坯里，这一笔收不回了", "done": "画好了就罩釉", "glaze": "罩上一层透明釉，你的画看不清了", "fire": "入窑，高温烧透", "open": "开窑", "reveal": "这才是它真正的颜色", "compare": "和墙上这只并排看", "again": "再画一只", "keys": "键盘：Q / E 转动坯，1 2 3 换料的浓淡，回车 罩釉入窑；W/S 移笔，按住 B 落笔"}, "captions": {"raw": "素坯", "pigment": "钴料（未烧）", "loadLevels": ["淡", "中", "浓"], "strokes": "已落 {n} 笔", "fired": "烧成", "spots": "料积得最厚的 {n} 处，烧出了黑褐色的斑点", "bleed": "浓料的边缘在釉下微微晕开", "mine": "你的罐", "orig": "墙上的原件", "origSource": "《青花缠枝牡丹纹狮耳罐》，元，克利夫兰艺术博物馆", "origNote": "原件叶尖、花心料浓处也有这样的黑斑", "ref": "罐形照墙上的原件；未烧钴料的灰黑、烧成的蓝、晕散与黑斑的程度，都是本展设定"}, "pigment": {"raw": "#4A4A4E", "rawLight": "#8C8B8E", "note": "未烧的钴料在素坯上呈灰黑色（示意色）"}, "body": {"raw": "#D9D4CB", "fired": "#C9D0CB", "note": "raw 为素坯哑光的灰白（示意色）；fired 为 main.webp 釉白中位色 (201,208,203)"}, "fired": [{"level": "淡", "hex": "#7F98BE", "when": "料淡，烧成浅蓝"}, {"level": "中", "hex": "#29558C", "when": "料适中，烧成浓艳的蓝：main.webp 蓝色中位约 (41,76,121)"}, {"level": "浓", "hex": "#16263A", "when": "料积得太厚，蓝里透黑，见原件叶尖的黑斑（示意）"}], "img": "main.webp", "imgW": 2400, "imgH": 2295, "jarBox": [445, 375, 1520, 1680], "bands": [{"name": "口沿回纹", "box": [870, 412, 650, 76]}, {"name": "颈部海浪", "box": [925, 512, 550, 100]}, {"name": "肩部缠枝莲", "box": [725, 675, 1025, 225]}, {"name": "云肩凤凰穿花", "box": [525, 937, 1350, 425]}, {"name": "腹部缠枝牡丹", "box": [575, 1362, 1263, 388]}, {"name": "卷草", "box": [760, 1762, 880, 50]}, {"name": "变形莲瓣", "box": [838, 1825, 800, 200]}], "ironSpots": [[663, 1359, 105, 100], [826, 1385, 122, 96], [948, 1578, 175, 54], [1183, 1494, 115, 87], [935, 1670, 82, 58], [1529, 1502, 94, 78], [1538, 1632, 119, 94], [1231, 769, 52, 76], [711, 1046, 61, 63]], "note": "坐标为 main.webp 像素（2400×2295），左上原点，框写 [x, y, w, h]。颜色、晕散、黑斑程度为本展示意；原件不变形，展项里画的是“你的罐”，只在面板里与原件并排比，不上墙。"}, "works": [{"img": "w1.webp", "w": 1012, "h": 1200, "who": "佚名景德镇窑工", "whoLat": "Unknown Jingdezhen potters", "title": "《青花云龙纹象耳瓶》", "meta": ["元至正十一年（1351），青花瓷，一对", "高 63.6 cm、63.8 cm", "伦敦，大英博物馆展出（大维德藏品 B.613、B.614）"], "note": "颈上题记写明至正十一年供奉道观，人称“大维德瓶”。", "credit": "Wikimedia Commons, File:The David Vases, 1351.jpg — 摄影 BabelStone，CC BY-SA 3.0"}, {"img": "w2.webp", "w": 1200, "h": 901, "who": "佚名景德镇窑工", "whoLat": "Unknown Jingdezhen potter", "title": "《青花鱼藻纹大盘》", "meta": ["元，14 世纪中，青花瓷", "直径 45.7 cm", "纽约，大都会艺术博物馆（1987.10）"], "note": "盘心一尾鱼穿过水草，外圈一周缠枝花。", "credit": "大都会艺术博物馆开放获取, File:DP-14609-052.jpg — 摄影 大都会艺术博物馆，CC0"}, {"img": "w3.webp", "w": 689, "h": 1200, "who": "佚名景德镇窑工", "whoLat": "Unknown Jingdezhen potter", "title": "《青花四爱图梅瓶》", "meta": ["元，青花瓷", "高 38.7 cm，口径 6.4 cm，底径 13 cm", "武汉，湖北省博物馆"], "note": "四格画四位文人的雅好，这一面是林逋梅鹤。", "credit": "Wikimedia Commons, File:湖北省博物馆藏品之青花四爱图梅瓶.jpg — 摄影 Liuxingy，CC BY-SA 4.0"}, {"img": "w4.webp", "w": 900, "h": 1200, "who": "佚名景德镇窑工", "whoLat": "Unknown Jingdezhen potter", "title": "《青花龙纹罐》", "meta": ["明宣德（1426–1435），青花瓷", "高 48.3 cm，直径 48.3 cm", "纽约，大都会艺术博物馆（37.191.1）"], "note": "肩上从右往左横写“宣德年製”，器上的字成了年号款。", "credit": "大都会艺术博物馆开放获取, File:DP-32251-001.jpg — 摄影 大都会艺术博物馆，CC0"}], "chain": "之前：唐代巩县窑已在白地上用钴料画蓝花，但没有流行开来。之后：明代景德镇有御器厂专为宫廷烧瓷，永乐、宣德年间仍多用进口钴料，蓝色依旧浓重。下一厅回到纸上：徐渭的墨葡萄，藤不再守着边线。", "sources": [{"label": "克利夫兰艺术博物馆 · 狮耳罐（Jar with Lion-Head Handles）", "claim": "主作品：1962.154，Jar with Lion-Head Handles（青花雙獅頭罐），1300s，景德镇，元；porcelain with underglaze painted decoration；Overall 39.4 x 37.5 cm，口径 15.6 cm；John L. Severance Fund；CC0。馆方说明：元代青花的典型；此类器最迟 1330 年代已烧造，供宫廷、民间与海外贸易；钴料自伊朗输入，很可能来自卡尚；云肩凤凰穿花纹样见于伊儿汗国（1256–1353）装饰；肩部白釉上刻“宮”“南”二字，提示曾存放于宫中某处", "url": "https://www.clevelandart.org/art/1962.154"}, {"label": "克利夫兰艺术博物馆 · 开放获取 API", "claim": "同上数据的机读版本；图像 1962.154_full.tif 10875×10400，CC0", "url": "https://openaccess-api.clevelandart.org/api/artworks/1962.154"}, {"label": "大英博物馆 · 大维德瓶（PDF,B.614）", "claim": "大维德瓶之一；大英博物馆藏品页：高 63.8 cm，径 19.6 cm（大维德中国艺术基金会藏品，大英博物馆展出）", "url": "https://www.britishmuseum.org/collection/object/A_PDF-B-614"}, {"label": "大英博物馆 · 大维德瓶（PDF,B.613）", "claim": "大维德瓶之二；大英博物馆藏品页：高 63.6 cm，径 22 cm", "url": "https://www.britishmuseum.org/collection/object/A_PDF-B-613"}, {"label": "英文维基百科 · 大维德瓶", "claim": "一对，景德镇，高 63.5 cm；颈部题记记张文进于至正十一年四月供奉星源（今婺源）道观；象头耳；大英博物馆称其为最早的纪年青花（引 Krahl & Harrison-Hall 2009、Scott 1989、Kessler 2012）", "url": "https://en.wikipedia.org/wiki/David_Vases"}, {"label": "维基共享资源 · 大维德瓶图片文件页", "claim": "The David Vases, 1351.jpg，摄影 BabelStone，CC BY-SA 3.0，2119×1877", "url": "https://commons.wikimedia.org/wiki/File:The_David_Vases,_1351.jpg"}, {"label": "大都会艺术博物馆 · 青花鱼藻纹盘（Plate with fish）", "claim": "1987.10，mid-14th century，元，景德镇，Porcelain painted with cobalt blue under transparent glaze，Diam. 45.7 cm，Purchase, Mrs. Richard E. Linburn Gift, 1987，公有领域", "url": "https://www.metmuseum.org/art/collection/search/39638"}, {"label": "大都会艺术博物馆 · 青花龙纹罐（Jar with dragon）", "claim": "37.191.1，early 15th century，明宣德款及宣德时期（1426–35），H. 48.3 cm，Diam. 48.3 cm，Gift of Robert E. Tod, 1937，公有领域；肩部“宣德年製”四字款经本展放大原图目验", "url": "https://www.metmuseum.org/art/collection/search/39666"}, {"label": "湖北省博物馆 · 元青花四爱图梅瓶", "claim": "2006 年出土于湖北钟祥郢靖王墓；通高 38.7 cm，口径 6.4 cm，底径 13 cm；肩饰凤穿牡丹；腹部四个菱形开光画王羲之爱鹅、陶渊明爱菊、林和靖爱梅鹤、周敦颐爱莲", "url": "https://www.hbww.org.cn/p/11500.html"}, {"label": "维基共享资源 · 四爱图梅瓶图片文件页", "claim": "湖北省博物馆藏品之青花四爱图梅瓶.jpg，摄影 Liuxingy，CC BY-SA 4.0，归入“湖北省博物馆藏品”分类；本展裁去画面右侧观众", "url": "https://commons.wikimedia.org/wiki/File:%E6%B9%96%E5%8C%97%E7%9C%81%E5%8D%9A%E7%89%A9%E9%A6%86%E8%97%8F%E5%93%81%E4%B9%8B%E9%9D%92%E8%8A%B1%E5%9B%9B%E7%88%B1%E5%9B%BE%E6%A2%85%E7%93%B6.jpg"}, {"label": "维基文库 · 钟嵘《诗品》卷中", "claim": "宋光禄大夫颜延之条：湯惠休曰：“謝詩如芙蓉出水，顏如錯彩鏤金。”顏終身病之", "url": "https://zh.wikisource.org/wiki/%E8%A9%A9%E5%93%81/%E5%8D%B7%E4%B8%AD"}, {"label": "《文史哲》2018 年第 3 期 · 高迎刚论“错彩镂金”“芙蓉出水”", "claim": "摘要：宗白华明确提出“错彩镂金”和“芙蓉出水”代表中国美学史上两种不同的美感或美的理想", "url": "https://www.lhp.sdu.edu.cn/info/1108/2200.htm"}, {"label": "英文维基百科 · 景德镇瓷器", "claim": "14 世纪起钴料定期从波斯输入；后来在中国境内找到钴矿，国产料含锰比例不同；明代景德镇分御器厂（官窑）与民窑两套体系", "url": "https://en.wikipedia.org/wiki/Jingdezhen_porcelain"}, {"label": "中文维基百科 · 青花瓷", "claim": "永宣青料高铁处在蓝色区域出现黑色结晶斑点；成化起改用平等青，发色淡雅，不再出现黑斑", "url": "https://zh.wikipedia.org/wiki/%E9%9D%92%E8%8A%B1%E7%93%B7"}, {"label": "弗利尔美术馆 · Pope《十四世纪青花：伊斯坦布尔托普卡帕宫藏一组中国瓷器》（1952）", "claim": "托普卡帕宫藏大批 14 世纪中国青花；阿德比尔神祠旧藏约 800 件“今在德黑兰考古博物馆”（今伊朗国家博物馆）；蓝色中“料过量处有少许黑斑”", "url": "https://asia-archive.si.edu/wp-content/uploads/2017/06/blue-white.pdf"}, {"label": "日本堺市文化财 · 学艺员小解说《青花》", "claim": "青花用氧化钴颜料在白坯上画纹，罩透明釉烧成；颜料原本呈黑色或茶褐色，烧成后才发出青色（“顔料は元々黒色か茶色を呈していますが、焼成することによって綺麗な青色に発色”）", "url": "https://www.city.sakai.lg.jp/kanko/rekishi/bunkazai/bunkazai/machikado_yakimono/machikado_yakimono_kaisetsu/koremade_kaisetsu.files/seika_kaisetsu.pdf"}, {"label": "Gotheborg · “Heaped and piled”", "claim": "早期青花料下得厚处，钴料穿出釉面，形成深色乃至黑紫色斑点，主要见于 14–15 世纪", "url": "https://gotheborg.com/glossary/heapedandpiled.shtml"}, {"label": "英文维基百科 · 青花瓷", "claim": "14 世纪钴料自波斯输入后青花在中国瓷器上广泛使用；阿德比尔神祠藏瓷（捐献年份各书记 1607–1608 或 1612）；黑石号沉船出水巩县窑白地蓝花盘（约 825–850 年）", "url": "https://en.wikipedia.org/wiki/Blue_and_white_pottery"}, {"label": "英文维基百科 · 釉下彩", "claim": "釉下彩画在未上釉的坯上，罩透明釉后烧成", "url": "https://en.wikipedia.org/wiki/Underglaze"}]};

