(window.EH_ROOMS=window.EH_ROOMS||{})["xieyi"]={"id": "xieyi", "zh": "写意", "lat": "Ming Dynasty", "yrs": "1368 – 1644 CE", "one": "葡萄不勾边，墨就是画家的脾气", "wall": "#E6E2D8", "wallWhy": "墙取明代粉墙的灰白，比画上的旧纸略亮一档，墨色在它前面沉得住。光是书斋里平淡的窗光，不打聚光；花窗的格影只落在墙上，不落在画上。这是一幅立轴，所以照挂轴的样子挂，只挂画心；墙上的装裱为示意，不是原件的装裱。", "ink": "dark", "frame": "mount", "art": {"img": "main.webp", "w": 927, "h": 2400, "who": "徐渭", "whoLat": "Xu Wei, 1521 – 1593", "title": "《墨葡萄图》", "short": "《墨葡萄图》", "meta": ["明，约 16 世纪后期，纸本墨笔", "165.4 × 64.5 cm", "北京，故宫博物院（新00052537）"], "credit": "Wikimedia Commons, File:徐渭水墨葡萄图轴.png — 来源 故宫名画记，公有领域"}, "lede": "明代后期，绍兴人徐渭用一纸湿墨写了一架葡萄，又在左上角题诗，说自己笔下的明珠没处卖。", "work": "一根老藤从右上方斜伸进画面，往左下垂去，墨里夹着丝丝白痕；细藤一路垂到纸底。叶子是一团团泼开的淡墨，浓墨趁湿点进去，墨色在叶里化开，深浅不一。葡萄不勾轮廓，一颗颗墨点或浓或淡，挤成一串串挂在叶间；最低的一颗像将落未落的水滴。左上角一大块是徐渭的行草七言诗，款署“天池”，下钤一方印。", "quote": ["半生落魄已成翁，独立书斋啸晚风。笔底明珠无处卖，闲抛闲掷野藤中。", "徐渭《墨葡萄图》自题，明"], "origin": "明代中期，苏州的沈周、文徵明把山水和花卉画成了文人自己的日子。在水墨写意花卉上，徐渭接着梁楷、林良、沈周一路往下走，后人把他和陈淳并称“青藤、白阳”。徐渭生于 1521 年，浙江山阴人，屡试不第，曾入总督胡宗宪幕府，参与抗倭；胡宗宪获罪后，他几度发狂，1566 年杀妻入狱，获释后靠卖字画度日，1593 年在贫困中去世。他自评“吾书第一，诗二，文三，画四”。", "traits": [["墨分五色", "唐代张彦远说：“运墨而五色具，谓之得意。”只用一种墨，靠水的多少、落笔的先后，分出浓淡干湿的层次。后人把这层意思概括为“墨分五色”。"], ["破墨", "前一笔还湿着，再叠一笔浓淡不同的墨，后笔把前笔“破”开，墨色互相渗化。故宫的说明说，这幅画的叶和果是淡墨加胶矾挥洒，晕散的效果极好。"], ["以书入画", "故宫说明说徐渭“以草书笔法作画”。藤蔓像草书的长画，一笔拖出；笔走得快、墨跟不上，就在墨里留下丝丝白痕，书画家叫它“飞白”。"], ["书为心画", "扬雄说“言，心声也；书，心画也”，原指文辞，后人借来说书法。徐渭死后，袁宏道初见他的字画，说“磊块不平之气，字画之中，宛宛可见”。"]], "special": {"title": "笔底明珠", "type": "ink_bleed_grapes", "text": "徐渭的葡萄不勾轮廓，一颗颗都是墨落在纸上自己化开的。这里铺一张吸水的生纸，你来点几颗。笔按住不动，墨就顺着纸的纤维往外洇，按得越久，葡萄越大越湿；笔里水多，墨色就淡。前一笔还没干，再叠一笔湿墨，后一笔把前一笔破开，这叫破墨；水把墨推开，边上冲出一圈深色的水线。按下去快快一甩，就甩出一根藤，提得越快，藤梢越干，露出飞白。每一下都不一样，没有对错。点完可以和原作的葡萄对照着看。", "labels": {"water": "笔里的水", "waterLow": "少", "waterMid": "中", "waterHigh": "多", "clear": "换一张纸", "compare": "对照原作", "back": "回到纸上"}, "hints": {"start": "在纸上按住不动，墨就开始洇开", "startTouch": "手指按在纸上不动，墨就开始洇开", "keys": "键盘：按住 F 落笔，1、2、3 换水量，C 换一张纸", "hold": "按得越久，这颗葡萄越大越湿", "lift": "提笔了，墨还在纸里慢慢走", "waterLow": "水少，墨浓，洇得慢", "waterMid": "水不多不少，墨色居中", "waterHigh": "水多，墨淡，洇得快、走得远", "breakInk": "湿墨破开半干的墨，边上冲出一圈水线：这就是破墨", "dry": "这一笔落在已干的墨上，只叠深了一层，没有水线", "flick": "按下去快快一甩，甩出一根藤", "flyWhite": "提得快，藤梢干了，露出飞白", "slowFlick": "甩得慢，藤是湿的，没有飞白", "cluster": "葡萄挤成一串了，像画里挂在叶间的那几串", "compare": "看看徐渭的葡萄：浓淡、大小、水线，也是这样一下一下留下的", "again": "每一下都不一样，没有对错，再点几颗"}, "captions": {"paper": "生纸：吸水，墨落上去会顺着纤维洇开", "breakInk": "破墨：湿墨推开前一笔，边缘积成水线", "flyWhite": "飞白：笔快墨少，笔毛之间露出纸白", "compareTitle": "原作局部", "quote": "笔底明珠无处卖", "quoteSource": "徐渭《墨葡萄图》自题，明", "note": "这张纸只在展项里，关上就没了，原作上不留你的墨", "source": "徐渭《墨葡萄图》，北京故宫博物院"}, "compare": [{"label": "右侧上方的一串", "box": [715, 980, 95, 115]}, {"label": "右侧中段的一串", "box": [550, 1135, 115, 110]}, {"label": "左下的一串", "box": [55, 1755, 135, 130]}, {"label": "最低的一颗，像水滴", "box": [664, 2194, 32, 34]}, {"label": "叶边的水线", "box": [20, 1430, 190, 175]}, {"label": "老藤，笔快处的飞白", "box": [430, 560, 497, 190]}], "note": "compare 的 box 为 main.webp 像素 [x, y, w, h]（927×2400），按 1:1 目验定，±10 px；可在查看器里推近到这些框。叶果“淡墨加胶矾挥洒”据故宫名画记说明；展项的纸与洇墨是模拟，不是复原徐渭的纸和墨。"}, "works": [{"img": "w1.webp", "w": 1200, "h": 391, "who": "文徵明", "whoLat": "Wen Zhengming, 1470 – 1559", "title": "《惠山茶会图》", "meta": ["明正德十三年（1518），纸本设色", "21.9 × 67 cm", "北京，故宫博物院（新00101129）"], "note": "苏州文人到无锡惠山泉边喝茶，画的是有日期的一天。", "credit": "Wikimedia Commons, File:文徵明惠山茶会图卷.png — 来源 故宫名画记，公有领域"}, {"img": "w2.webp", "w": 347, "h": 1200, "who": "徐渭", "whoLat": "Xu Wei, 1521 – 1593", "title": "《榴实图》", "meta": ["明，纸本墨笔", "91.4 × 26.6 cm", "台北，台北故宫博物院（故画000566）"], "note": "也是一枝湿墨，题诗说石榴籽“颗颗明珠走”。", "credit": "台北故宫博物院开放资料, File:K2A000566N000000000PAA — 明徐渭榴實 軸 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w3.webp", "w": 1200, "h": 796, "who": "佚名景德镇御窑工匠", "whoLat": "Jingdezhen imperial kilns", "title": "《斗彩鸡缸杯》", "meta": ["明成化（1465–1487），瓷，青花加釉上彩", "高 3.8 cm，口径 8.1 cm", "台北，台北故宫博物院（故瓷005189）"], "note": "青花先勾出花卉湖石，再在线里填红、黄、绿等彩。", "credit": "台北故宫博物院开放资料, File:K1B005189N000000000PAB — 鬥彩雞缸杯 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w4.webp", "w": 800, "h": 1200, "who": "佚名木匠", "whoLat": "Unknown Chinese craftsman", "title": "《黄花梨四出头官帽椅》", "meta": ["明末清初，17 世纪，黄花梨木", "121.9 × 58.4 × 47.6 cm", "纽约，大都会艺术博物馆（1997.92）"], "note": "书斋里的椅子：线条简净，几乎不加雕饰。", "credit": "大都会艺术博物馆开放获取, File:1997_92_O2_sf.jpg — 来源 大都会艺术博物馆，CC0"}], "chain": "之前：上一厅的元青花罐上，缠枝牡丹一圈圈绕在两道弦纹之间，规规矩矩，循环往复。到了徐渭，藤叶冲出了格子，湿墨满纸，画成了一个人的脾气。之后：明亡以后，下一厅的八大山人把满纸的墨收成寥寥几笔，大片的纸空着。", "sources": [{"label": "故宫博物院 · 故宫名画记：徐渭水墨葡萄图轴", "claim": "《水墨葡萄图》轴，明，徐渭绘，纸本，墨笔，纵 165.4 cm、横 64.5 cm；本幅自题“半生落魄已成翁，独立书斋啸晚风。笔底明珠无处卖，闲抛闲掷野藤中。天池。”钤“湘管斋”印；清代李佐贤、陈希濂等收藏；以草书笔法作画，叶、果用淡墨加胶矾挥洒，墨气淋漓，晕散效果极好；诗见《徐文长集》卷十一；画中题字受米芾行书风格影响；徐渭 1521—1593，山阴人，号天池山人、青藤道士；水墨大写意花卉继承梁楷、林良、沈周，与陈道復（陈淳）并称“青藤、白阳”（撰稿 杨丹霞）", "url": "https://minghuaji.dpm.org.cn/paint/detail?id=i64tf10rqz8la0jtzkz7tcp9shmg9vfw"}, {"label": "故宫博物院 · 藏品：徐渭水墨葡萄图轴", "claim": "文物号 新00052537；纸本墨笔，纵 165.4 厘米、横 64.5 厘米；题字受米芾行书风格影响", "url": "https://www.dpm.org.cn/collection/paint/231318.html"}, {"label": "故宫博物院 · 明代绘画概述（院藏资料 PDF）", "claim": "《墨葡萄图》轴作于晚年，以草书笔法画出藤蔓，草书题七绝；徐渭曾助胡宗宪抗倭，胡宗宪因严嵩案入狱后徐渭落魄，靠卖画维持生计；袁宏道称其字画中“强心铁骨与夫一种磊块不平之气……宛宛可见”", "url": "https://www.dpm.org.cn/Uploads/pdf/1952/T00024_00.pdf"}, {"label": "识典古籍 · 《明史》卷二百八十八 文苑四 徐渭传", "claim": "渭知兵，宗宪擒徐海、诱王直皆预其谋；及宗宪下狱，渭惧祸，遂发狂，自残皆不死；已又击杀继妻，论死系狱，里人张元忭力救得免", "url": "https://www.shidianguji.com/zh/book/LS0024/chapter/LS0024_1711"}, {"label": "中国社会科学院文学研究所 · 徐渭为“公安派先驱”说质疑", "claim": "引袁宏道《徐文长传》：袁宏道到越地，见人家单幅上署“田水月”者，“强心铁骨，与夫一种磊块不平之气，字画之中宛宛可见”；其时徐渭已卒数年", "url": "http://literature.cass.cn/ztzl/xsyjzt/xszm/202305/t20230509_5630355.shtml"}, {"label": "维基共享资源 · 主图文件页", "claim": "主图文件 6432 × 16303，公有领域，来源故宫名画记", "url": "https://commons.wikimedia.org/wiki/File:%E5%BE%90%E6%B8%AD%E6%B0%B4%E5%A2%A8%E8%91%A1%E8%90%84%E5%9B%BE%E8%BD%B4.png"}, {"label": "大英百科全书 · Xu Wei", "claim": "Xu Wei，1521 年生于山阴（今绍兴），1593 年卒；屡试不第；1566 年刺死妻子入狱，后以精神失常获释；死于贫困；画用大片水墨与迅疾的线", "url": "https://www.britannica.com/biography/Xu-Wei"}, {"label": "台北故宫博物院 · 明徐渭榴實 軸", "claim": "故画000566，本幅 91.4 × 26.6 cm，纸；自题“山深熟石榴，向日笑開口；深山少人收，顆顆明珠走。文長”；馆方说明：徐渭尝自言“吾书第一，诗二，文三，画四”；写意石榴一枝，水墨淋漓；影像 CC BY 4.0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/3357?dep=P"}, {"label": "故宫博物院 · 文徵明惠山茶会图卷", "claim": "新00101129；纸本设色，纵 21.9 cm、横 67 cm；本幅未署款，钤“文徵明印”“悟言室印”；蔡羽序记作于正德十三年（1518），文徵明 49 岁；正德十三年二月十九日文徵明与蔡羽、王守、王宠、汤珍等至无锡惠山品茗赋诗；松林中茅亭泉井，围井而坐、展卷吟哦、童子煮茶；文徵明 1470—1559", "url": "https://www.dpm.org.cn/collection/paint/228278.html"}, {"label": "维基共享资源 · 惠山茶会图文件页", "claim": "全卷图 29878 × 1868，公有领域，来源故宫名画记；本展只裁本幅", "url": "https://commons.wikimedia.org/wiki/File:%E6%96%87%E5%BE%B5%E6%98%8E%E6%83%A0%E5%B1%B1%E8%8C%B6%E4%BC%9A%E5%9B%BE%E5%8D%B7.png"}, {"label": "台北故宫博物院 · 鬥彩雞缸杯（故瓷005189）", "claim": "明成化 1465–1487；高 3.8 cm、口径 8.1 cm、底径 4.0 cm；外壁湖石花卉间两组鸡群，各为雌雄二鸡带三雏，花卉湖石以釉下青花勾勒，再填红、黄、绿、褐诸色；底青花“大明成化年製”款；影像 CC BY 4.0，署名“鬥彩雞缸杯。國立故宮博物院，台北，CC BY 4.0 @ www.npm.gov.tw”", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail/2178?dep=U"}, {"label": "台北故宫博物院 · 3D 赏析：明成化鬥彩雞缸杯", "claim": "斗彩是在青花点线上加填各种釉上彩料后再入窑烧成；景德镇珠山成化官窑遗址出土只施青花的鸡缸杯半成品；明神宗时已有“一双值钱十万”之说", "url": "https://theme.npm.edu.tw/3d/Content.aspx?sno=04001036&fromCnt=0"}, {"label": "大都会艺术博物馆 · Yokeback armchair", "claim": "1997.92；17th century，late Ming–early Qing；Wood (huanghuali, Dalbergia odorifera)；H. 121.9、W. 58.4、D. 47.6 cm；Purchase, The Dillon Fund Gift, 1997；公有领域（开放 API）", "url": "https://www.metmuseum.org/art/collection/search/39493"}, {"label": "超星慕课 · 张彦远《历代名画记》卷二 论画体工用拓写", "claim": "“草木敷荣，不待丹碌之采……是故运墨而五色具，谓之得意。意在五色，则物象乖矣。”（“墨分五色”是后人的概括）", "url": "https://mooc1.chaoxing.com/mooc-ans/ztnodedetailcontroller/visitnodedetail?courseId=232021007&knowledgeId=701632598"}, {"label": "中国哲学书电子化计划 · 扬雄《法言·问神》", "claim": "“故言，心声也。书，心画也。声画形，君子小人见矣！”此处“书”指写下的文辞，后人借来论书法", "url": "https://ctext.org/yangzi-fayan/juan-wu/zh"}]};

