(window.EH_ROOMS=window.EH_ROOMS||{})["bada"]={"id": "bada", "zh": "八大山人", "lat": "Early Qing", "yrs": "1644 – 1722 CE", "one": "一大片空纸，一点墨是眼睛", "wall": "#E6E2D8", "wallWhy": "墙色取明清粉墙的灰白，比画纸再淡一档、再冷一点：这幅画大半是空纸，墙若暖若暗，空白就被吃掉了；墙淡，纸的米色和焦墨才分得开，深色文字也立得住。光是书斋窗光，平而散，不打聚光。它是一幅立轴，所以照挂轴的样子挂，只挂画心；墙上的装裱为示意，不是原件的装裱。", "ink": "dark", "frame": "mount", "art": {"img": "main.webp", "w": 868, "h": 2400, "who": "八大山人（朱耷）", "whoLat": "Bada Shanren (Zhu Da), 1624 or 1626 – 1705", "title": "《荷石水鸟图》", "short": "《荷石水鸟图》", "meta": ["清（无纪年），纸本墨笔", "127 × 46 cm", "北京，故宫博物院（新00146234）"], "credit": "Wikimedia Commons, File:朱耷荷石水鸟图轴.png — 来源 故宫名画记，公有领域"}, "lede": "清初，明朝宗室的后人八大山人在一张窄长的纸上，只画了几片荷叶、一块石头和一只单脚站着的水鸟。", "work": "画幅左边大半是空纸。右上一丛荷叶用淡墨扫出，一根荷梗从里面斜挑上去；另一根梗弯下来，挂着一片倒垂的荷叶，几团湿墨像要往下滴。荷叶下一块石头，中间鼓、底下收窄，像站不稳；石顶一只水鸟缩着脖子，只用一只脚站着。故宫的说明说它似在休憩，“更似在冷眼观望”。左上角署款“八大山人写”，下钤两方白文印。", "quote": ["夫画者，从于心者也。", "石涛《苦瓜和尚画语录·一画章》，清初"], "origin": "八大山人本名朱耷，是明朝宁王朱权的后代，生在南昌。1644 年明亡，四年后他削发为僧。1680 年前后他有过一段发狂、不说话的日子，有人认为是真病，也有人认为是装出来的。康熙二十三年（1684）起，他自号“八大山人”，晚年把这四字草书连写，看着像“哭之”，又像“笑之”。后人把他和石涛、髡残、弘仁并称“清初四僧”。他画里那股孤冷，学者多认为与遗民的身世有关。", "traits": [["空出来的纸", "八大的画常常大半是空纸，墨只落在一角。空白不是没画完：一只鸟、一块石放进去，四周的空纸就成了水、成了天，也成了距离和冷清。"], ["一只眼睛", "八大的鸟和鱼，眼睛往往是全画最要紧的一笔：一个圈，一点墨，眼珠常顶在眼眶一角，像斜着眼看人。整幅画的神气都聚在这一点上。"], ["看着险，其实稳", "石头头重脚轻，鸟只用一只脚站，荷叶倒挂着，处处像要倒。可是墨的轻重、位置算得准，整幅画稳稳地挂在那里。"], ["四僧与四王", "清初画坛有两路人。八大、石涛、髡残、弘仁这些出过家的遗民画家各走各的路；王原祁等“四王”学宋元古法，讲究规矩，受到朝廷看重。"]], "special": {"title": "一点定一张纸", "type": "balance_scroll", "text": "八大的画看着很险：石头头重脚轻，鸟单脚站着，大半张纸空着，挂起来却很稳。这里有一张空白立轴，挂绳系偏了，纸是歪的。按住纸面落墨，按得越久墨越重，纸会往墨重的一边摆，摆几下才停。试试用最少的墨把它挂正：落对了地方，一点墨就能压住一大片空白。", "hints": {"start": "这张纸挂歪了。按住纸面落墨，按得越久墨越重；用最少的墨把它挂正", "startTouch": "这张纸挂歪了。手指按住纸面落墨，按得越久墨越重；用最少的墨把它挂正", "ink": "墨在洇开，越按越重", "wrong": "越压越歪了，墨要落到另一边", "over": "压过头了，歪到另一边去了。落下的墨收不回来", "near": "快正了", "wait": "差不多正了，等它停稳", "far": "墨离挂绳越远，越能把纸压住", "settled": "定了", "grab": "放手，它会自己摆回来", "keys": "键盘：W A S D 移笔，按住回车落墨；F 拨一下，R 洗掉重来，N 再挂一张"}, "captions": {"sheet": "第 {i} 张", "tilt": "歪 {d}°", "straight": "正", "ink": "用墨 {n} 分", "blank": "留白 {p}%", "result": "用了 {n} 分墨；这张纸最少约 {m} 分就能挂正。", "rateBest": "几乎是最少的墨。", "rateOk": "墨不算多。", "rateMore": "墨用多了。同样一点墨，离挂绳越远越有分量。", "verdict": "八大的石头头重脚轻，鸟单脚站着，看着险，其实很稳。", "again": "洗掉重来", "next": "再挂一张", "ref": "立轴、挂绳和墨的“分量”是本展的示意；墙上的原作照原样挂着"}, "note": "展项是示意：立轴按单点悬挂的刚体摆动，墨按面积计重；八大并没有这样算过。“看着险，其实稳”是本展对画面的描述，不是八大的原话。"}, "works": [{"img": "w1.webp", "w": 1070, "h": 425, "who": "八大山人", "whoLat": "Bada Shanren (Zhu Da), 1624 or 1626 – 1705", "title": "《鱼石图》（局部）", "meta": ["清，17 世纪中后期，纸本墨笔，手卷", "画心 29.6 × 158.4 cm", "克利夫兰，克利夫兰艺术博物馆（1953.247）"], "note": "两条小鱼游过怪石，四周一笔水也没画。", "credit": "克利夫兰艺术博物馆开放资料, File:1953.247_print.jpg — Fish and Rocks, Bada Shanren，CC0"}, {"img": "w2.webp", "w": 1200, "h": 586, "who": "髡残", "whoLat": "Kuncan, 1612 – c. 1673", "title": "《春景图》", "meta": ["清康熙五年（1666），纸本设色，册页改装成卷", "31.8 × 64.5 cm", "克利夫兰，克利夫兰艺术博物馆（1966.367）"], "note": "“四僧”里的髡残，山石树木画得又密又毛。", "credit": "克利夫兰艺术博物馆开放资料, File:1966.367_print.jpg — Spring Landscape, Kuncan，CC0"}, {"img": "w3.webp", "w": 1200, "h": 491, "who": "石涛", "whoLat": "Shitao, 1642 – c. 1707", "title": "《搜尽奇峰图》（局部）", "meta": ["清康熙三十年（1691），纸本墨笔，手卷", "42.8 × 285.5 cm", "北京，故宫博物院（新00010499）"], "note": "卷首自题“搜尽奇峰打草稿”。", "credit": "Wikimedia Commons, File:石涛搜尽奇峰图卷.png — 来源 故宫名画记，公有领域"}, {"img": "w4.webp", "w": 644, "h": 1200, "who": "王原祁", "whoLat": "Wang Yuanqi, 1642 – 1715", "title": "《仿倪瓒设色山水图》", "meta": ["清康熙四十六年（1707），纸本淡设色，立轴", "画心 80.6 × 43.8 cm", "克利夫兰，克利夫兰艺术博物馆（1954.583）"], "note": "“四王”之一，照着元人倪瓒的格局添了淡彩。", "credit": "克利夫兰艺术博物馆开放资料, File:1954.583_print.jpg — Landscape after Ni Zan, Wang Yuanqi，CC0"}], "chain": "之前：徐渭的《墨葡萄图》满纸湿墨，藤和葡萄挤得满满当当；到了八大，只剩一大片空纸和寥寥几笔。之后：这只鸟站在石上，石下没有影子；下一厅，一位从意大利来的宫廷画家，在清宫的画里画出了光和影子。", "sources": [{"label": "故宫博物院 · 朱耷荷石水鸟图轴", "claim": "《荷石水鸟图》轴，清，朱耷绘，纸本墨笔，纵 127 厘米、横 46 厘米，文物号 新00146234；图绘荷叶下一只水鸟栖于孤石上，单足独立，“似在休憩，更似在冷眼观望这冰凉的世界”；款署“八大山人写”，钤白文印“可得神仙”“八大山人”，鉴藏印“虚斋珍玩”等 3 方。朱耷（1624—1705），明宁献王朱权后裔，南昌人；顺治五年（1648）落发为僧；康熙二十三年（1684）始号八大山人；晚年“八大山人”四字连缀写，似“哭之”“笑之”；与石涛、弘仁、髡残合称“清初四僧”", "url": "https://www.dpm.org.cn/collection/paint/232837.html"}, {"label": "维基共享资源 · 朱耷荷石水鸟图轴（故宫名画记）", "claim": "主图文件 6139 × 16787 px，公有领域，来源故宫名画记", "url": "https://commons.wikimedia.org/wiki/File:朱耷荷石水鸟图轴.png"}, {"label": "故宫博物院 · 清初四僧专题", "claim": "故宫“四僧”专题分列弘仁、髡残、八大山人、石涛四人", "url": "https://www.dpm.org.cn/subject_monks/sts.html"}, {"label": "大英百科全书 · 中国绘画：清代", "claim": "朱达（八大山人）与道济（石涛）都出自明宗室；八大在 1680 年代有过一段真病或装出来的疯癫与失语，此后画风极端，画中鸟鱼目光古怪；髡残画风密而缠绕，承王蒙；王翚、王原祁等董其昌一路的正统画家受清廷重用，与不受朝廷赞助的“个性派”遗民画家相对", "url": "https://www.britannica.com/art/Chinese-painting/Qing-dynasty-1644-1911-12"}, {"label": "克利夫兰艺术博物馆 · 八大山人《鱼石图》", "claim": "Fish and Rocks（魚石圖），mid- to late 1600s，手卷，纸本墨笔，画心 29.6 × 158.4 cm，1953.247，CC0；八大画中的鱼常朝上看，游在没有画出的水里；馆方认为此卷或有自况之意，鱼像失了位置的遗民；八大生卒 1626–1705", "url": "https://www.clevelandart.org/art/1953.247"}, {"label": "克利夫兰艺术博物馆 · 髡残《春景图》", "claim": "Spring Landscape（春景圖），1666，双开册页改装为手卷，纸本设色，31.8 × 64.5 cm，1966.367，CC0；髡残（1612–约 1673）为“四僧”之一，以粗犷荒率的山水著称", "url": "https://www.clevelandart.org/art/1966.367"}, {"label": "故宫博物院 · 石涛搜尽奇峰图卷", "claim": "《搜尽奇峰图》卷，清，石涛作，纸本墨笔，纵 42.8 厘米、横 285.5 厘米，文物号 新00010499；卷首自题“搜尽奇峰打草稿”；卷尾长题署“时辛未二月”（1691）；50 岁游京师时作；馆方另记石涛生卒为 1642—约 1718", "url": "https://www.dpm.org.cn/collection/paint/234551.html"}, {"label": "维基共享资源 · 石涛搜尽奇峰图卷（故宫名画记）", "claim": "w3 图像文件，74164 × 5247 px，公有领域，来源故宫名画记；本展取卷首一段", "url": "https://commons.wikimedia.org/wiki/File:石涛搜尽奇峰图卷.png"}, {"label": "克利夫兰艺术博物馆 · 王原祁《仿倪瓒设色山水图》", "claim": "Landscape after Ni Zan（仿倪瓚設色山水圖），1707，立轴，纸本淡设色，画心 80.6 × 43.8 cm，1954.583，CC0；王原祁（1642–1715）为康熙朝官员，正统派，循董其昌所推的古法；倪瓒少用色，王原祁在树、屋、山上加了青绿与赭石；自题“丁亥清和扈从归舟写设色云林”", "url": "https://www.clevelandart.org/art/1954.583"}, {"label": "中国哲学书电子化计划 · 苦瓜和尚画语录", "claim": "（清）石涛撰《苦瓜和尚画语录》，“一画章第一”：“……夫画者，从于心者也。山川人物之秀错……”", "url": "https://ctext.org/wiki.pl?if=gb&chapter=623580&remap=gb"}]};

