(window.EH_ROOMS=window.EH_ROOMS||{})["baijun"]={"id": "baijun", "zh": "百骏", "lat": "Qing · Yongzheng", "yrs": "1723 – 1735 CE", "one": "线里长出明暗，蹄下落了影子", "wall": "#2B1D18", "wallWhy": "墙色取清宫紫檀家具的暗红褐，是全馆最富丽的一面墙，但不用红和金。手卷本来平放在案上，从右往左一段段展开看，所以本厅不加框，也不仿造它的装裱，只挂画心。这一厅第一次有一道从一侧照来的光：画里的马本来就有明暗和影子。", "ink": "light", "frame": "scroll", "art": {"img": "t_win.webp", "w": 2600, "h": 1298, "who": "郎世宁", "whoLat": "Giuseppe Castiglione, 1688 – 1766", "title": "《百骏图》", "short": "《百骏图》", "meta": ["清雍正六年（1728），绢本设色", "94.5 × 776.2 cm", "台北，台北故宫博物院（故画000916）"], "credit": "Wikimedia Commons, File:A Hundred Steeds.jpg — 来源 台北故宫，公有领域"}, "lede": "郎世宁是意大利米兰人、耶稣会修士，1715 年来到中国，在清宫作画五十一年。雍正六年（1728），他把一百匹马画进了一卷近八米长的绢。", "work": "手卷从右往左展开。卷首两棵大松树顶天立地，树下支着帐篷，牧人坐在草地上歇息，近处几匹马或低头吃草，或静静站着。往左，马群散在平原和林间，有的躺倒打滚，有的在河边洗浴、涉水。中段一个穿绿袍的牧人骑在马上，高举长长的套马杆追马。马身用深浅颜色一层层染出圆的体积，蹄下有淡淡的影子。地平线一路保持在画高的三分之二处。", "quote": ["西洋人善勾股法，故其绘画，于阴阳远近不差锱黍。所画人物屋树，皆有日影……但笔法全无，虽工亦匠，故不入画品。", "邹一桂《小山画谱》卷下“西洋画”"], "origin": "郎世宁在康熙朝画的作品没有留下来。据清宫内务府档案，雍正二年（1724）三月，皇帝命他画百骏图一卷。宫廷作画要先起稿呈览，这卷的稿本今藏纽约大都会艺术博物馆，构图与正本相符。稿子上的马只勾了轮廓，到了绢上，郎世宁用中国的绢、颜料和毛笔，把西洋的明暗一层层染进去。他在宫里常和中国画家合作，台北故宫称之为“中西合璧”的院画新体。", "traits": [["阴阳远近", "明暗，清人叫“阴阳”；近大远小，叫“远近”。西洋画用几何算出透视，用一个固定的光源定下哪面亮、哪面暗、影子落向哪边。"], ["骨法用笔", "南朝谢赫论画有六法，第二条是“骨法用笔”。中国画的形靠线立起来，线本身的力道就是画的品格；西洋画的形，靠明暗塑出来。"], ["收着的影子", "郎世宁有意控制阴影：明暗只用来塑出马的实体，不在画里造强光深影。台北故宫说，这一卷是他整合两种画风的折冲成果。"], ["正面受光", "郎世宁给帝后画像，按乾隆的审美，让脸正面受光，减弱明暗，只保留五官结构和透视的准确。西法进了宫，也按宫里的眼光改。"]], "special": {"title": "套马", "type": "lasso_pole", "text": "卷中段，一个穿绿袍的牧人骑在马上，高举一根长长的套马杆，杆梢的绳圈张在头顶，前面三匹马正在奔逃；卷里另有牧人持杆追马。现在换你来套：马带着自己的影子跑过草地，按住举杆，松手甩出去，绳圈要落在马头前面。早了、晚了都落空，马受惊会掉头；套中了要压住杆子，马会拖着你走一段才停。马照郎世宁的画法画，奔跑的动作参照迈布里奇的连续摄影；杆的弹性和马的力气是本展示意。也可以去掉影子，看看还分不分得清远近。", "hints": {"start": "按住瞄准，草地上的圈是绳圈要落的地方；松手，长杆甩出去", "startTouch": "在草地上按住瞄准，圈是绳圈要落的地方；松手，长杆甩出去", "wind": "杆子举起来了，按得越久甩得越远", "lead": "马在跑：圈要放在马头前面，等它跑进来", "flying": "绳圈飞出去了", "early": "早了：绳圈落下时，马还没跑到", "late": "晚了：马头已经过去了", "wide": "偏了：绳圈落在马的一侧", "short": "没举够就松手，绳圈飞不到那么远", "spook": "马受惊了，掉头跑开", "caught": "套中了！按住，把杆子压住", "caughtTouch": "套中了！手指按住，把杆子压住", "brace": "压住了，马在绳上打转，慢下来了", "dragged": "马拖着你在草地上走", "held": "拉住了", "heldDrag": "拉住了：马拖着你走了 {d} 步", "slip": "没压住，马挣脱了", "away": "它跑出了画框，跑到墙边去了", "next": "又一匹马跑过来了", "noShadow": "影子没了：绳圈离地多高、马离你多远，一下子难看清了", "keys": "键盘：W A S D 或 ↑ ↓ 移动落点，按住回车举杆，松开甩出；套中后按住回车压杆"}, "captions": {"caught": "套住 {n} 匹", "miss": "落空 {n} 次", "drag": "最远被拖 {d} 步", "shadowOff": "去掉影子", "shadowOn": "放回影子", "verdict": "马有体积，地上有影子：郎世宁用西洋的明暗画马，看上去像真能套住一样", "ref": "奔跑的动作参照迈布里奇的连续摄影（1878），马按郎世宁的画法画：有明暗，有投影；不是从画里抠出来的", "orig": "原作：卷中段，绿袍牧人骑马举杆，绳圈张在头顶", "origSource": "郎世宁《百骏图》，台北故宫博物院"}, "coats": [{"name": "白马", "base": "#DAD3CA", "mane": "#C8C0B4", "dapple": false, "sock": false, "pie": false}, {"name": "黑白花马", "base": "#2D2D2C", "mane": "#262624", "dapple": false, "sock": true, "pie": true}, {"name": "枣骝马", "base": "#6A4636", "mane": "#2E2420", "dapple": false, "sock": false, "pie": false}, {"name": "青马", "base": "#4E4D4B", "mane": "#2E2E2E", "dapple": false, "sock": false, "pie": false}, {"name": "黄骠马", "base": "#8F7761", "mane": "#4A3A2E", "dapple": false, "sock": false, "pie": false}, {"name": "黄白花马", "base": "#B69473", "mane": "#6B4A35", "dapple": false, "sock": false, "pie": true}], "img": "main.webp", "imgW": 8000, "imgH": 977, "note": "坐标为 main.webp 像素（8000 × 977，左上原点，框为 [x,y,w,h]）；original.jpg = main × 2.07。手卷从右往左读，卷首在 x = 8000。框为目验近似，误差约 ±5 px。coats 的 base 为 main.webp 马身 9×9 中位色，mane 为目测；名称为本展所取。画里影子的方向见 notes.md，本字段不给 shadow，由 cut/layers.json 提供。", "scene": {"lassoRider": {"box": [3820, 464, 78, 77], "label": "绿袍牧人骑枣骝马，高举套马杆，马朝左"}, "lassoPole": {"line": [[3857, 459], [3875, 423]], "label": "套马杆：[手, 杆梢与绳圈相接处]"}, "lassoLoop": {"box": [3875, 404, 27, 20], "label": "杆梢张开的绳圈（在牧人头顶右上方）"}, "fleeing": {"box": [3574, 474, 232, 65], "label": "前面奔逃的三匹马（黄骠、青、白），朝左"}, "rider2": {"box": [4742, 486, 62, 57], "label": "第二个白衣牧人，骑花马冲下坡，手持杆绳"}, "rider3": {"box": [5961, 484, 111, 68], "label": "第三个牧人骑马持杆，追前面一匹白马（白马约 6072–6120）"}}}, "works": [{"img": "w1.webp", "w": 1200, "h": 836, "who": "郎世宁", "whoLat": "Giuseppe Castiglione, 1688 – 1766", "title": "《百骏图》（稿本）", "meta": ["约 1723–1725 年，纸本水墨", "94 × 789.3 cm", "纽约，大都会艺术博物馆（1991.134）"], "note": "画正本之前先起的稿，这是卷首一段。", "credit": "大都会艺术博物馆开放资料, File:DP355638.jpg — 摄影 大都会艺术博物馆，CC0"}, {"img": "w2.webp", "w": 593, "h": 1200, "who": "郎世宁", "whoLat": "Giuseppe Castiglione, 1688 – 1766", "title": "《聚瑞图》", "meta": ["清雍正元年（1723），绢本设色", "173 × 86.1 cm", "台北，台北故宫博物院（故画000803）"], "note": "他现存最早的纪年作品，瓷瓶用白色点出高光。", "credit": "台北故宫博物院开放资料, File:K2A000803N000000000PAA.jpg — 摄影 國立故宮博物院，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w3.webp", "w": 1200, "h": 1008, "who": "郎世宁等", "whoLat": "Giuseppe Castiglione, 1688 – 1766, and others", "title": "《哨鹿图》", "meta": ["清乾隆六年（1741），绢本设色", "267.5 × 319 cm", "北京，故宫博物院"], "note": "前列骑白马的第三人，是三十岁的乾隆。", "credit": "Wikimedia Commons, File:郎世宁哨鹿图轴.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w4.webp", "w": 800, "h": 1200, "who": "佚名景德镇窑工匠", "whoLat": "Unknown artisans, Jingdezhen kilns", "title": "《珐琅彩锦鸡蒜头瓶》", "meta": ["清乾隆（1736–1795），瓷胎珐琅彩", "18.6 × 10.5 cm", "克利夫兰，克利夫兰艺术博物馆（1971.145）"], "note": "锦鸡羽毛有明暗，馆方说可见郎世宁的影响。", "credit": "克利夫兰艺术博物馆开放资料, File:1971.145_print.jpg — 摄影 克利夫兰艺术博物馆，CC0"}], "chain": "之前：八大山人的鸟立在石上，石下没有影子，中国画一般不画投影。之后：郎世宁在宫里又画了三十多年，西洋的明暗也从绢上画到了宫里的瓷器上。下一厅，案上是一只乾隆朝的洋彩转旋瓶。", "sources": [{"label": "台北故宫博物院 · 神笔郎世宁（图成百骏）", "claim": "《百骏图》卷，绢本设色，纵 94.5、横 776 cm，雍正六年（1728）；卷首两棵据满画幅纵高的松树，段落为平原牧放、林间散马、河岸浴马、涉水过险、瞭望千里河山；据清宫内务府档案，雍正二年（1724）三月令郎世宁作百骏图一卷；作画经过绘制样稿呈览的程序；大都会《百骏图稿本》与本卷构图相符；地平线维持在画卷三分之二高度；常以深染明暗区分色块营造立体感，马匹虽有线条勾勒，但更多以色块形塑立体；“有意地控制物象阴影……却不营造画中剧烈光影作用”，是整合两种画风的“折冲成果”", "url": "https://theme.npm.edu.tw/exh104/giuseppecastiglione/ch/page-4.html"}, {"label": "台北故宫博物院 · 神笔郎世宁（展览概述）", "claim": "郎世宁（1688–1766）生于意大利米兰，十九岁在热那亚加入耶稣会；1715 年（康熙五十四年）抵达中国，同年底赴北京供职清宫，入值内廷长达五十一年，乾隆三十一年病逝；与如意馆画画人合作，创造“中西合璧”的院画新体；康熙朝画迹皆未存留；雍正元年（1723）绘《聚瑞图》，六年（1728）完成《百骏图》", "url": "https://theme.npm.edu.tw/exh104/giuseppecastiglione/ch/index.html"}, {"label": "台北故宫博物院 · 神笔郎世宁（抵华前后）", "claim": "1688 年 7 月 19 日生于米兰，1707 年于热那亚加入耶稣会，1715 年 8 月 20 日抵达澳门；《聚瑞图》轴，绢本设色，纵 173、横 86.1 cm，纪年雍正元年（1723），为郎世宁最早纪年作品，以白色颜料画出高光，增强瓷瓶立体效果", "url": "https://theme.npm.edu.tw/exh104/giuseppecastiglione/ch/page-2.html"}, {"label": "台北故宫博物院 · 神笔郎世宁（图写朝仪）", "claim": "郎世宁所绘肖像，在乾隆皇帝审美观指导下，保留人物脸部结构准确与透视关系，以正面受光，减弱明暗差别", "url": "https://theme.npm.edu.tw/exh104/giuseppecastiglione/ch/page-5.html"}, {"label": "国家文化记忆库 · 清郎世宁百骏图 卷", "claim": "台北故宫藏，统一编号 故画000916N000000000；清世宗雍正六年（1728）；本幅 94.5 × 776.2 cm；关键词：马、松、圉人、帐篷、江河、湖海、杨柳", "url": "https://catalog.digitalarchives.tw/item/00/11/12/58.html"}, {"label": "维基共享资源 · 主图文件页", "claim": "File:A Hundred Steeds.jpg，16560 × 2022，公有领域，来源为台北故宫郎世宁主题网；本厅挂整卷画心", "url": "https://commons.wikimedia.org/wiki/File:A_Hundred_Steeds.jpg"}, {"label": "大都会艺术博物馆 · One Hundred Horses（藏品数据）", "claim": "1991.134，Giuseppe Castiglione (Lang Shining)，datable to 1723–25，Handscroll; ink on paper，Image 94 × 789.3 cm，Purchase, Friends of Asian Art Gifts, 1991，Public Domain；卷首段图像 DP355638", "url": "https://collectionapi.metmuseum.org/public/collection/v1/objects/44632"}, {"label": "大都会艺术博物馆 · One Hundred Horses（藏品页）", "claim": "同上，馆方网页：这卷是郎世宁稿本中独一无二的例子，是台北故宫《百骏图》的范本；几乎全用欧洲画法，但用的是毛笔而非钢笔，草木用排线（cross-hatching）", "url": "https://www.metmuseum.org/art/collection/search/44632"}, {"label": "哥伦比亚大学“亚洲教育者” · Giuseppe Castiglione", "claim": "郎世宁先在纸上画稿，定好每个细节再移到绢上；稿本以西洋方式画成；正本是近八米的绢本手卷；文中说部分树枝底面皴擦较密、马蹄下有淡淡的影子，透露了西洋固定光源的画法；又说稿本里的草木按欧洲方式以明暗塑形（该页说稿本用欧洲钢笔，与大都会说法不一致，墙文不写用什么笔）", "url": "https://www-1.gsb.columbia.edu/qing/art-castiglione.html"}, {"label": "维基文库 · 邹一桂《小山画谱》卷下", "claim": "“西洋画”条：“西洋人善勾股法，故其绘画，于阴阳远近不差锱黍。所画人物屋树，皆有日影。其所用颜色与笔，与中华绝异……但笔法全无，虽工亦匠，故不入画品。”", "url": "https://zh.wikisource.org/wiki/%E5%B0%8F%E5%B1%B1%E7%95%AB%E8%AD%9C"}, {"label": "维基文库 · 谢赫《古画品录》", "claim": "“六法者何？一气韵生动是也，二骨法用笔是也，三应物象形是也，四随类赋彩是也，五经营位置是也，六传移模写是也。”", "url": "https://zh.wikisource.org/wiki/%E5%8F%A4%E7%95%AB%E5%93%81%E9%8C%84"}, {"label": "国家文化记忆库 · 清郎世宁聚瑞图 轴", "claim": "台北故宫藏，故画000803N000000000；雍正元年（1723）；本幅 173 × 86.1 cm；青瓷瓶插并蒂莲与双穗禾，“轮廓几不可见，设色有强烈的明暗感”；郎世宁现存最早纪年作品", "url": "https://catalog.digitalarchives.tw/item/00/11/12/26.html"}, {"label": "台北故宫博物院开放资料 · 聚瑞图图像（IIIF）", "claim": "K2A000803N000000000PAA，1904 × 3676，开放资料 CC BY 4.0；本厅去掉四周绫边，只取画心", "url": "https://iiifod.npm.gov.tw/iiif/2/K2A%2FK2A000803N000000000PAA/full/full/0/default.jpg"}, {"label": "故宫博物院名画记 · 郎世宁哨鹿图轴", "claim": "绢本设色，纵 267.5、横 319 cm；绘于乾隆六年（1741），记录皇帝到木兰行围的实况；前列骑白马、佩红锦撒袋的第三人为三十岁的乾隆；系郎世宁与中国画家及法国画家王致诚等合作完成", "url": "https://minghuaji.dpm.org.cn/paint/detail?id=7ec7fe9bd60d4b8c96a95fa972f453d9"}, {"label": "维基共享资源 · 哨鹿图文件页", "claim": "File:郎世宁哨鹿图轴.png，19019 × 16036，来源故宫博物院名画记，公有领域；本厅用 1600 宽缩本", "url": "https://commons.wikimedia.org/wiki/File:%E9%83%8E%E4%B8%96%E5%AE%81%E5%93%A8%E9%B9%BF%E5%9B%BE%E8%BD%B4.png"}, {"label": "克利夫兰艺术博物馆 · Vase with Golden Pheasants", "claim": "1971.145，馆方中文名“珐琅彩錦雞花卉蒜頭瓶”；1736–95，景德镇窑，乾隆款及乾隆时期；瓷，透明釉上彩绘珐琅彩（falangcai）；18.6 × 10.5 cm；馆方说花鸟以珐琅彩精细描绘，造型、明暗与色彩晕染反映了经由传教士画家传来的欧洲影响，尤其是郎世宁；CC0", "url": "https://www.clevelandart.org/art/1971.145"}], "scroll": {"w": 8000, "h": 977, "win": [6043.5, 0.0, 8000.0, 977.0], "head": "right", "lo": "scroll/lo.webp", "loW": 1310, "loH": 160, "levels": [{"f": "scroll/a{i2}.webp", "w": 10631, "h": 1298, "tw": 1024}, {"f": "cut/hr/h{i2}.webp", "w": 16560, "h": 2022, "tw": 2048}]}};

;
(window.EH_ROOMS=window.EH_ROOMS||{})["yangcai"]={"id": "yangcai", "zh": "洋彩", "lat": "Qing Imperial Yangcai Porcelain", "yrs": "1736 – 1795 CE", "one": "黄金烧出的粉红，镂空里藏着会转的瓶", "wall": "#C4C0B7", "wallWhy": "墙取北京白灰墙的浅灰。尾声几厅从宫里的墙一路走到美术馆的白墙，这一厅在半路上；浅墙也衬得出蓝地描金和粉红。这只瓶是清宫旧藏的陈设瓷，放在案上看，本厅不加框。", "ink": "dark", "frame": "none", "art": {"img": "cut/main_cut.webp", "w": 910, "h": 1732, "who": "佚名景德镇御窑厂工匠", "whoLat": "Unknown Jingdezhen imperial kiln artisans", "title": "《洋彩玲珑转旋瓶》", "short": "《洋彩转旋瓶》", "meta": ["清乾隆（1736–1795），瓷胎洋彩描金", "高 37.7 cm，口径 13.2 cm，足径 12.4 cm", "台北，台北故宫博物院（故瓷 008824）"], "credit": "國立故宮博物院開放資料, File:K1B008824N000000000PAB.jpg — 洋彩玲瓏轉旋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, "lede": "乾隆要御窑烧出前朝没有的新瓷。乾隆八年（1743），督陶官唐英交上九种新品，有镂空的双层套瓶，也有能旋转的机巧。台北故宫把这类转心瓶归为唐英的新创。", "work": "瓶由颈、腹、内瓶、底座四件分别烧成，再一件件套合。颈、肩和足是蓝地描金的番莲、如意与蕉叶；中段的瓶腹整个镂空，绕腹两对粉红的龙口衔莲花与灵芝，相向游在彩花丛里。镂孔后面还有一只白地内瓶，画着红蝙蝠和五彩云。瓶颈与内瓶连在一起，转动瓶颈，内瓶跟着转，镂孔里的云和蝙蝠就换了位置。", "quote": ["洋彩器皿，新仿西洋法琅画法，山水、人物、花卉、翎毛，无不精细入神。", "《景德镇陶录》卷三，一般认为录自唐英《陶成纪事碑记》（1735）"], "origin": "康熙朝宫中画珐琅用的彩料，多半从欧洲进口。雍正六年（1728），宫中作坊学会自己提炼，又把新料交给景德镇御窑厂。从此，御窑也能在瓷上画出宫中珐琅彩那样的效果。唐英把这类仿西洋珐琅画法的御窑彩瓷叫作“洋彩”；乾隆七年（1742），一批洋彩被皇帝列为“头等”。新料用清水、胶水或油都能调，乾隆朝又调出亮黄、嫩绿、粉绿这些像糖果一样的新色。", "traits": [["粉红出自黄金", "洋彩的粉红以胶体金呈色：极细的金微粒散在玻璃质的彩料里，透出玫瑰色。一般认为这一配方康熙末年从欧洲传来，欧洲人也用它烧金红玻璃。"], ["由浓到淡的渲染", "新彩料里有一种不透明的白，能和别的颜色调出深浅。花瓣、龙鳞可以由浓到淡地晕开，带出明暗，这是西洋画法进了瓷器。"], ["满、密、工", "乾隆朝的官窑爱把地子画满：锦地、描金、镂空层层相套，一件器上常同时用几种彩和工艺，求的是和康熙、雍正两朝都不一样的新样。"], ["会动的瓷", "转心瓶、转足碗要把几件分别烧成，再榫接套合，让内瓶或碗身能在外壳、圈足上转动。皇帝要新奇，御窑就把瓷做成了机巧。"]], "special": {"title": "转一转瓶颈", "type": "rotating_core", "text": "这只瓶的颈和内瓶连在一起，底座和镂空的瓶腹扣死不动。拖动瓶颈，内瓶跟着转，镂孔里的红蝙蝠和五彩云跟着换位置；松手后它会慢慢停下。内瓶一圈的花纹由台北故宫拍的三张内瓶照片接成，接缝处是示意；转动的手感也是本展的设定。", "hints": {"start": "拖动瓶颈，转动里面的内瓶", "startTouch": "按住瓶颈，左右拖", "keys": "键盘：A、D 转动内瓶", "spinning": "内瓶在转，瓷与瓷轻轻摩擦", "settle": "停住了：镂孔里换了一片云和蝙蝠", "fast": "转得太快，花纹糊成一片；慢一点看", "again": "再转一圈", "apart": "拆开看四件", "together": "装回去"}, "captions": {"outer": "外层：镂空瓶腹，两对口衔莲花与灵芝的龙", "inner": "内瓶：白地上画红蝙蝠与五彩云（云蝠纹）", "neck": "瓶颈与内瓶连成一体", "base": "底座与瓶腹扣合，不转", "angle": "内瓶转过 {deg}°", "seam": "接缝处为示意", "mark": "底心红料书“大清乾隆年製”六字三行篆款", "source": "内瓶花纹：台北故宫藏品照片 PAO、PAE、PAG，接成一圈"}, "parts": [{"name": "颈", "note": "蓝地描金；套在内瓶口上，转颈即转内瓶", "photo": "PAT"}, {"name": "瓶腹", "note": "外层镂空，两对粉红的龙口衔莲花与灵芝", "photo": "PAS"}, {"name": "内瓶", "note": "白地画云蝠纹，底心套在底座的凸心上", "photo": "PAO"}, {"name": "底座", "note": "蓝地描金；内口两个小凸翼与瓶腹扣合", "photo": "PAK"}], "assembly": ["底座摆正，把内瓶内凹的底心套在底座的凸心上", "套上镂空瓶腹，转一下，让瓶腹底圈的小凹口扣住底座的凸翼", "最后把瓶颈套在内瓶口沿上：颈和内瓶从此一起转"], "photos": {"note": "台北故宫这件瓶共 23 个角度（PAA–PAW），全部 CC BY 4.0；下列为展项可用的几张，图像 URL 为馆方 IIIF 最大尺寸", "PAO": {"what": "内瓶单拍（正）", "url": "https://iiifod.npm.gov.tw/iiif/2/K1B%2FK1B008824N000000000PAO/full/max/0/default.jpg"}, "PAE": {"what": "内瓶立在底座上", "url": "https://iiifod.npm.gov.tw/iiif/2/K1B%2FK1B008824N000000000PAE/full/max/0/default.jpg"}, "PAG": {"what": "内瓶单拍（另一面，倒置）", "url": "https://iiifod.npm.gov.tw/iiif/2/K1B%2FK1B008824N000000000PAG/full/max/0/default.jpg"}, "PAH": {"what": "内瓶与底座近景", "url": "https://iiifod.npm.gov.tw/iiif/2/K1B%2FK1B008824N000000000PAH/full/max/0/default.jpg"}, "PAW": {"what": "拆开的四件并排", "url": "https://iiifod.npm.gov.tw/iiif/2/K1B%2FK1B008824N000000000PAW/full/max/0/default.jpg"}, "PAN": {"what": "底面款识", "url": "https://iiifod.npm.gov.tw/iiif/2/K1B%2FK1B008824N000000000PAN/full/max/0/default.jpg"}, "credit": "國立故宮博物院開放資料, File:K1B008824N000000000PAO.jpg — 洋彩玲瓏轉旋瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, "files": {"core": "s_core.webp", "holes": "s_holes.webp", "geo": "s_geo.json"}, "note": "内瓶花纹、外层镂孔、四件结构均照台北故宫藏品页说明与馆方照片；内瓶一圈的展开图由三张照片接成，接缝与转动阻尼为示意。键盘不用空格（空格归引擎）。"}, "works": [{"img": "w1.webp", "w": 960, "h": 1200, "who": "佚名玻璃工，银饰马特乌斯·鲍尔二世", "whoLat": "Matthäus Baur II, c. 1653–1728", "title": "《金红玻璃带盖杯》", "meta": ["1695–1700，金红玻璃，银鎏金配件", "16.8 × 8.6 × 8.9 cm", "纽约，大都会艺术博物馆（27.185.309a, b）"], "note": "欧洲的金红玻璃，同样以金呈色。", "credit": "大都会艺术博物馆开放获取, File:DP-24644-001.jpg — 摄影 大都会艺术博物馆，CC0"}, {"img": "w2.webp", "w": 1200, "h": 900, "who": "佚名清宫画珐琅匠", "whoLat": "Unknown Qing court enamel painter", "title": "《珐琅彩红地花卉纹碗》", "meta": ["清雍正（1723–1735），瓷胎画珐琅", "高 3.9 cm，口径 9.1 cm，底径 3.3 cm", "台北，台北故宫博物院（故瓷 017557）"], "note": "宫中珐琅彩：洋红作地，满绘牡丹番莲。", "credit": "國立故宮博物院開放資料, File:K1B017557N000000000PAB.jpg — 琺瑯彩紅地花卉紋碗 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w3.webp", "w": 900, "h": 1200, "who": "佚名景德镇御窑厂工匠", "whoLat": "Unknown Jingdezhen imperial kiln artisans", "title": "《粉彩八卦转心瓶》", "meta": ["清乾隆（1736–1795），瓷胎粉彩", "高 22.5 cm，口径 7.9 cm，足径 9.1 cm", "台北，台北故宫博物院（故瓷 016923）"], "note": "同类转心瓶：镂空如意云与八卦，内胆洋红。", "credit": "國立故宮博物院開放資料, File:K1B016923N000000000PAB.jpg — 粉彩八卦轉心瓶 國立故宮博物院，臺北，CC BY 4.0 @ www.npm.gov.tw"}, {"img": "w4.webp", "w": 900, "h": 1200, "who": "佚名景德镇御窑厂工匠", "whoLat": "Unknown Jingdezhen imperial kiln artisans", "title": "《乾隆御制诗瓶》", "meta": ["清乾隆，18 世纪晚期，瓷胎釉上彩描金", "连盖高 22.9 cm，宽 11.4 cm，厚 7 cm", "纽约，大都会艺术博物馆（79.2.612a, b）"], "note": "粉红成了通体的地色，中间写着御制诗。", "credit": "大都会艺术博物馆开放获取, File:DP-17578-001.jpg — 摄影 大都会艺术博物馆，CC0"}], "chain": "之前：上一厅，郎世宁把西洋明暗融入宫廷绘画；康熙、雍正两朝，宫中先学画珐琅，再学自炼彩料。之后：洋彩的粉红在景德镇一直烧了下去，后来多被统称为“粉彩”。下一厅跳到 1951 年的北京，看齐白石。", "sources": [{"label": "台北故宫博物院 · 洋彩玲珑转旋瓶", "claim": "主作品：洋彩玲瓏轉旋瓶，故瓷008824N000000000；清乾隆，西元1736–1795年；高37.7、口徑13.2、足徑12.4公分；由頸、腹、內瓶及底座四部分組成及套合順序（內瓶底心套底座凸心；鏤空腹部底圈小凹陷與底座兩小凸翼扣合；器頸套合內瓶口沿，轉動瓶頸內瓶隨之旋轉，故曰轉心瓶或轉頸瓶）；上下段藍地描金如意紋、番蓮紋、蕉葉紋；鏤空腹部彩繪兩對口銜蓮花與靈芝的鏤雕雙龍紋；內瓶器腹彩繪雲蝠紋；頸內及器底湖綠釉，底心紅料書「大清乾隆年製」六字三行篆款；英文名 Revolving openwork vase with dragon and lotus decoration in yangcai painted enamels；CC BY 4.0 標示文字；參考書目廖寶秀《華麗彩瓷：乾隆洋彩》（2008）", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=28657&dep=U"}, {"label": "台北故宫博物院 · 洋彩玲珑转旋瓶 IIIF 清单", "claim": "23 個視角 PAA–PAW（含內瓶單拍 PAO/PAE/PAG、拆件並排 PAW、底款 PAN），主圖 PAB 2291×3055", "url": "https://digitalarchive.npm.gov.tw/Integrate/GetJson?cid=28657&dept=U"}, {"label": "台北故宫博物院 · 粉彩八卦转心瓶", "claim": "鏤空轉心瓶分圈足、器身、內膽、頸部四段個別燒製，再榫接組裝；內膽與頸相連可旋轉；頸部及內膽為洋紅剔錐錦上添花；高22.5、口徑7.9、足徑9.1公分，故瓷016923；「乾隆八至十年唐英特為清高宗製作新式品種……只要撥動瓶頸，內瓶亦隨之轉動，透過鏤空處可見內套瓶紋飾」；《活計檔》名「洋彩冬青玲瓏如意元（圓）式蓍草瓶」", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=26789&dep=U"}, {"label": "台北故宫博物院 · 风格故事：乾隆年制珐琅彩瓷（双彩联乘）", "claim": "乾隆皇帝力求燒製和康熙、雍正兩朝官窯不同的新品，唐英不得不遵旨研辦，乾隆八年（1743）繳出玲瓏鏤空雙層套瓶和具有旋轉機巧設計的瓷器共計九種；1744 年造辦處檔案登錄洋彩轉足碗類作品；琺瑯彩瓷由宮廷技師在景德鎮白瓷上以琺瑯料彩繪、皇家作坊二次燒成", "url": "https://theme.npm.edu.tw/exh109/ArtisticStyle-Qianlong/ch/page-2.html"}, {"label": "台北故宫博物院 · 风格故事：乾隆年制珐琅彩瓷（集锦新样）", "claim": "康熙朝彩繪琺瑯器的顏料多半自西洋進口；雍正六年（1728）皇家作坊摸索出提煉技術，並將新色料分享給景德鎮御窯廠；乾隆朝清水、膠水或油性介質均能調色，亮黃、嫩綠、紫紅、粉紅和粉綠是乾隆朝新創色系（「如糖果般的顏色」）；唐英說洋彩以製造如同琺瑯彩般的效果為目標；乾隆七年（1742）一批洋彩列為「頭等」；錦地紋為乾隆創新樣式之一", "url": "https://theme.npm.edu.tw/exh109/ArtisticStyle-Qianlong/ch/page-3.html"}, {"label": "台北故宫博物院 · 珐琅彩红地花卉纹碗", "claim": "w2：琺瑯彩紅地花卉紋碗，清雍正 1723–1735，高3.9、口徑9.1、底徑3.3公分，故瓷017557；外壁洋紅地，彩畫牡丹、番蓮等花卉；底「雍正年製」藍料款；CC BY 4.0", "url": "https://digitalarchive.npm.gov.tw/Collection/Detail?id=27320&dep=U"}, {"label": "维基文库 · 蓝浦《景德镇陶录》卷三", "claim": "卷三〈陶務條目〉列「洋彩器皿（新倣西洋法琅畫法，山水、人物、花卉、翎毛，無不精細入神）」及「西洋紅色、綠色器皿」等（引文據此轉為簡體）", "url": "https://zh.wikisource.org/wiki/%E6%99%AF%E5%BE%B7%E9%8E%AE%E9%99%B6%E9%8C%84"}, {"label": "故宫博物院 · 唐英", "claim": "唐英（1682—1756），雍正六年（1728）奉命駐景德鎮御窯廠任協理官；乾隆元年起兼理窯務至二十一年；著有《陶成紀事》等", "url": "https://www.dpm.org.cn/lemmas/239362.html"}, {"label": "维基百科 · 洋彩瓷", "claim": "唐英語「洋彩器皿，本朝新仿西洋法瑯畫法」；學者對洋彩、粉彩、琺瑯彩名稱的討論（汪慶正等）；洋彩後世多稱粉彩", "url": "https://zh.wikipedia.org/zh-hant/%E6%B4%8B%E5%BD%A9%E7%93%B7"}, {"label": "雅昌 · 刘越讲座：珐琅彩与洋彩的区别", "claim": "台北故宮 2008 年「乾隆洋彩」展與廖寶秀的觀點：洋彩是模仿西洋繪畫技法描繪的彩瓷，民國以後統稱粉彩", "url": "https://amma.artron.net/observation_shownews.php?newid=991164"}, {"label": "大英百科全书 · 中国陶瓷：清代", "claim": "Toward the end of the Kangxi reign, a rose-pink made from gold chloride was introduced from Europe; used in famille rose porcelain, cloisonné and overglaze painting", "url": "https://www.britannica.com/art/Chinese-pottery/The-Qing-dynasty-1644-1911-12"}, {"label": "大英百科全书 · 粉彩（famille rose）", "claim": "famille rose：以不透明的釉上玫瑰色（粉紅、胭脂紅諸色）為特徵的清代瓷器", "url": "https://www.britannica.com/art/famille-rose"}, {"label": "鲍尔基金会东方艺术博物馆 · “色彩的秘密”展（Ceramics Now 转载）", "claim": "康熙末年出現新琺瑯料：不透明白可與他色調出深淺；粉紅以膠體金得來，歐洲稱 purple of Cassius", "url": "https://www.ceramicsnow.org/exhibitions/the-secret-of-colours-at-fondation-baur-museum-of-far-eastern-art-geneva"}, {"label": "大英博物馆 · 粉彩瓷（官方社交平台）", "claim": "famille rose 的粉紅以膠體金（colloidal gold，懸浮在水中的極細金微粒）製成", "url": "https://www.facebook.com/britishmuseum/posts/on-wednesdays-we-%CC%B6w%CC%B6e%CC%B6a%CC%B6r%CC%B6-share-pink-famille-rose-pink-family-porcelain-became-/1015226390639421"}, {"label": "康宁玻璃博物馆 · 炼金术士的玻璃：铅水晶与金红，1650–1750", "claim": "1680 年代中期，昆克爾（Kunckel）在波茨坦把 purple of Cassius 加入配料燒出金紅玻璃", "url": "https://whatson.cmog.org/exhibitions-galleries/glass-alchemists-lead-crystal-gold-ruby-1650-1750"}, {"label": "大都会艺术博物馆 · 金红玻璃带盖杯", "claim": "w1：Standing cup with cover，1695–1700，Gold-ruby glass, silver-gilt mounts；Matthäus Baur II（ca. 1653–1728，銀匠）；16.8 × 8.6 × 8.9 cm；27.185.309a, b；公有領域（開放 API）", "url": "https://www.metmuseum.org/art/collection/search/196054"}, {"label": "大都会艺术博物馆 · 炼金术与装饰艺术", "claim": "選帝侯延請昆克爾在波茨坦燒製覆盆子紅色的金紅玻璃；金紅玻璃杯是 17 世紀歐洲收藏的時尚", "url": "https://www.metmuseum.org/blogs/now-at-the-met/2020/alchemy-science-making-marvels"}, {"label": "大都会艺术博物馆 · 乾隆御制诗瓶", "claim": "w4：Vase with Poems Composed by the Qianlong Emperor，late 18th century，Qianlong period；Porcelain painted in overglaze enamels and gilding (Jingdezhen ware)；H. (with cover) 22.9、W. 11.4、D. 7 cm；79.2.612a, b；公有領域（開放 API）", "url": "https://www.metmuseum.org/art/collection/search/49362"}]};

