(window.EH_ROOMS=window.EH_ROOMS||{})["washeng"]={"id": "washeng", "zh": "蛙声", "lat": "Modern China", "yrs": "c. 1850 – 1950s", "one": "一只青蛙也没画，蛙声却有十里", "wall": "#DAD6CD", "wallWhy": "墙色取北京胡同里白灰墙的灰白，比画纸暗一档，纸就从墙上浮出来；光是北方干亮的日光，平而散。尾声走到这里，墙由清宫的暗色退成了白。这是一幅立轴，本厅照挂轴的样子挂，只挂画心；墙上的装裱为示意，不是原件的装裱。", "ink": "dark", "frame": "mount", "art": {"img": "main.webp", "w": 950, "h": 3642, "who": "齐白石", "whoLat": "Qi Baishi, 1864 – 1957", "title": "《蛙声十里出山泉》", "short": "《蛙声十里出山泉》", "meta": ["1951 年，纸本设色", "129 × 33 cm（一说 127.5 × 33 cm）", "北京，中国现代文学馆"], "credit": "百度百科图集, 蛙声十里出山泉 950 × 3642 — 扫描 画家网（huajia.cc），原拍摄者不详；原作 中国现代文学馆藏，© 齐白石（中国大陆已进入公有领域）"}, "lede": "1951 年，作家老舍拿清人查慎行的一句诗向齐白石求画：“蛙声十里出山泉”。蛙声是耳朵听的，画怎么画？", "work": "画心又窄又高，高约是宽的四倍。最上方用石青点出两个远山头；下面两壁浓墨山石夹出一道山涧，泉水从乱石间泻下，用一条条淡墨细线画成，越往下越宽。水里有六只蝌蚪，两只一组，分在上、中、下三处，都顺水往下游。整幅不见一只青蛙。左边山石旁题：“蛙声十里出山泉　查初白句　老舍仁兄教画　九十一白石”，“九十一”是他自报的岁数，比实岁大几岁。", "quote": ["蝌斗四五，随水摇曳；无蛙而蛙声可想矣。", "老舍致齐白石的求画信，1951 年"], "origin": "齐白石生在湖南湘潭的农家，少年学木匠，以雕花出名，二十多岁才正式学画、刻印。五六十岁时他定居北京，卖画刻印为生，受陈师曾影响改了画风。1950 年，他与担任北京市文联领导的老舍相识。1951 年老舍写信求画四幅，每幅出一句诗，还写下自己设想的画面，这一幅就是信里的第二题。这封信 2010 年才公布，此前人们多以为蝌蚪的主意出自画家本人。老舍的子女后来把画捐给了中国现代文学馆。", "traits": [["画外之音", "看不见的东西，靠看得见的东西让人想出来。蝌蚪是蛙的孩子，急水有声，蛙声由看画的人自己补上。学者吴雪杉认为，齐白石是以“泉声”代“蛙声”。"], ["似与不似之间", "齐白石常被引用的一句话：“作画妙在似与不似之间，太似为媚俗，不似为欺世。”他的蝌蚪只是一个墨点拖一根细尾，一眼就认得出。"], ["平常东西入画", "木匠出身的齐白石爱画虾、蟹、鱼、蛙这些水里的小东西，也画瓜果、草虫。高士、梅兰竹菊之外，寻常日子里的东西都能入画，而且画得有趣。"], ["中西相遇", "故宫认为，晚清上海的任颐已把西洋速写、素描的手法用进人物画；徐悲鸿 1919 年起留学欧洲学素描和油画。西洋画法从宫廷走进了画家自己的笔下。"]], "special": {"title": "搅动山泉", "type": "stream_stir_frog_chorus", "text": "把手伸进画里的白泉，左右来回搅，水就急起来，蝌蚪被冲着往下游；水越急，远处的蛙声越响、越多，从一只到一片。停手，水慢下来，蛙声也远了。拍一下水，蛙受了惊，一下全不出声，过一会儿又一只一只叫起来。展项里的蝌蚪是照齐白石的笔意新画的，不是从原画上取下的；从头到尾，画上没有一只青蛙。", "labels": {"stir": "搅水", "slap": "拍水"}, "hints": {"start": "在白的山泉里按住，左右来回搅，水就急起来", "startTouch": "手指在山泉里左右来回划，水就急起来", "keys": "键盘：A、D 左右交替搅水；按住 W、S 手往上游、下游挪；J 拍一下水", "stir": "水急了，听：远处的蛙叫起来了", "more": "再急一点，蛙声越传越远", "rock": "这是山石，手放进白的山泉里", "calm": "停手，水慢下来，蛙声远了", "slap": "啪的一声，蛙一下全不叫了；等一等，一只一只又叫起来", "swept": "一只蝌蚪顺水游出了画外", "ten": "十里蛙声。再看画上：一只青蛙也没有", "again": "再搅一次，把蛙声叫回来"}, "captions": {"meter": "蛙声", "li": "{n} 里", "quiet": "静", "levels": ["远处一只", "三五只", "十几只", "几十只", "一片"], "best": "最远 {n} 里", "tadpoles": "游出画外的蝌蚪 {n} 只", "slaps": "拍水 {n} 次", "verdict": "蛙声是你搅出来、听出来的；画上依旧只有一道泉", "note": "展项里的蝌蚪按齐白石笔意新画，不取自原画；“里”数只是蛙声大小的比方"}, "note": "蛙声、水声为录音或合成，不是原作之物；“十里”取自画题诗句。", "stream": [[420, 470, 110], [600, 480, 150], [800, 480, 180], [1000, 490, 170], [1300, 460, 200], [1500, 455, 205], [1800, 560, 260], [2200, 655, 295], [2600, 665, 285], [3000, 650, 300], [3600, 645, 305]], "streamNote": "[y, 中心 x, 半宽]，main.webp 像素（950 × 3642），按 1:1 目验估读，±30 px；泉水在 y≈360 从乱石间出现，往下到画底", "tadpoles": [[369, 811, 132, 123], [388, 972, 161, 87], [457, 1398, 139, 99], [246, 1439, 104, 174], [629, 2784, 118, 110], [500, 2880, 143, 116]], "tadpolesNote": "六只蝌蚪的框 [x, y, w, h]，main.webp 像素，含 10 px 余量；两只一组，上、中、下三处"}, "works": [{"img": "w1.webp", "w": 668, "h": 1200, "who": "任颐", "whoLat": "Ren Yi, 1840 – 1895", "title": "《苏武牧羊图》", "meta": ["清光绪六年（1880），纸本设色", "149.5 × 81 cm", "北京，故宫博物院"], "note": "海派人物画：苏武持节立在风雪里，羊群挤在脚边。", "credit": "Wikimedia Commons, File:任颐苏武牧羊图轴.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w2.webp", "w": 372, "h": 1200, "who": "吴昌硕", "whoLat": "Wu Changshuo, 1844 – 1927", "title": "《紫藤图》", "meta": ["清光绪三十一年（1905），纸本设色", "132.5 × 41.2 cm", "北京，故宫博物院"], "note": "以书入画：老藤用写篆字的笔一圈圈盘上去。", "credit": "Wikimedia Commons, File:吴昌硕紫藤图轴.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w3.webp", "w": 607, "h": 1200, "who": "齐白石", "whoLat": "Qi Baishi, 1864 – 1957", "title": "《画藤》", "meta": ["1922 年，纸本设色", "131.4 × 63.3 cm", "北京，故宫博物院"], "note": "赭红的大藤打几个圈，垂下蓝紫的花，余下是空纸。", "credit": "Wikimedia Commons, File:齐璜画藤轴.png — 来源 故宫博物院名画记，公有领域"}, {"img": "w4.webp", "w": 1200, "h": 1087, "who": "徐悲鸿", "whoLat": "Xu Beihong, 1895 – 1953", "title": "《康有为像》", "meta": ["1926 年，布面油画", "74 × 84 cm", "上海，上海博物馆"], "note": "留法期间回上海探亲时，用油画给老师康有为画像。", "credit": "Wikimedia Commons, File:徐悲鸿 康有为像.jpg — 来源 上海博物馆，公有领域"}], "chain": "之前：上一厅是乾隆宫廷的洋彩转旋瓶，满身纹饰，工巧到了极处。到齐白石这里，一幅画给一位作家朋友，只画一道泉、几点墨。之后：留学欧洲的画家把素描、油画带回课堂，中国画走进学校和美术馆，展览也就停在这里。", "sources": [{"label": "慕津锋（中国现代文学馆）· 《蛙声十里出山泉》：老舍与齐白石的天合之作（2021，人民号，四川在线转载）", "claim": "齐白石 1951 年为老舍作；2013 年由老舍家属捐赠中国现代文学馆；长 129、宽 33 cm；87 岁（自诩 91 岁）；两侧重墨山涧，中间急湍溪水；六只蝌蚪，两个一组，分布在上、中、下三处；正上方石青点两个远山头；题出查慎行（查初白）《次实君溪边步月韵》“萤火一星沿岸草，蛙声十里出山泉”；老舍求画信全文（四题：渔洋山人、查初白、赵秋谷、施愚山句；第二题“蝌斗四五，随水摇曳；无蛙而蛙声可想矣”）；1950 年 5 月北京市第一次文代会两人初见，老舍担任北京文联领导", "url": "https://focus.scol.com.cn/zgsz/202102/58059808.html"}, {"label": "维基文库 · 查慎行《敬业堂诗集》卷十七（四部丛刊本）", "claim": "《次实君溪边步月韵》：“萤火一星沿岸草，蛙声十里出山泉”，确为查慎行（号初白）诗句", "url": "https://zh.wikisource.org/wiki/%E6%95%AC%E6%A5%AD%E5%A0%82%E8%A9%A9%E9%9B%86_(%E5%9B%9B%E9%83%A8%E5%8F%A2%E5%88%8A%E6%9C%AC)/%E5%8D%B7%E7%AC%AC%E5%8D%81%E4%B8%83"}, {"label": "中国青年报 · 老舍遇到齐白石：不见青蛙，何以蛙声十里（2026）", "claim": "1951 年，一级文物，中国现代文学馆藏；6 只蝌蚪顺流而下，不见青蛙；题款“蛙声十里出山泉，查初白句，老舍仁兄教画，九十一白石”；作者为中国现代文学馆副研究馆员", "url": "http://m.cyol.com/gb/articles/2026-04/12/content_8EpQvBcW3E.html"}, {"label": "人民政协网 · 人民的艺术家——老舍、胡絜青藏画展（2015）", "claim": "展品著录：齐白石，蛙声十里出山泉，1951 年，127.5 × 33，纸本设色，立轴，中国现代文学馆藏（尺寸另一说 129 × 33 cm，见中国现代文学馆研究馆员慕津锋文，本展两说并列）", "url": "https://www.rmzxw.com.cn/c/2015-02-11/446168.shtml"}, {"label": "人民日报海外版 · 中国现代文学馆馆藏精品（2016）", "claim": "齐白石《蛙声十里出山泉》，1951 年，一级品，老舍子女捐赠；老舍以查初白句求画，同时主动提供了绘画构思", "url": "https://paper.people.com.cn/rmrbhwb/html/2016-01/09/content_1646327.htm"}, {"label": "北京画院 齐白石艺术国际研究中心 · 吴雪杉：蛙声十里出山泉——齐白石笔下的画外音", "claim": "2010 年公布的老舍《命题求画信函》显示以蝌蚪表现蛙声的设想出自老舍而非齐白石，颠覆此前近 60 年的认知；作者认为齐白石并未盲从，而是以“泉声”代“蛙声”", "url": "https://www.bjaa.com.cn/news.html?hcs=125&clg=186&news=3842"}, {"label": "中国科学院大学人文学院 · 明德讲堂：蛙声十里出山泉，齐白石笔下的画外音（2024）", "claim": "吴雪杉讲座报道：齐白石通过湍急的山泉和顺流而下的蝌蚪暗示泉水的声音，以“泉声”代替“蛙声”", "url": "https://renwen.ucas.ac.cn/index.php/rczp/2015-12-09-08-37-2/56759-m1020-2"}, {"label": "故宫博物院 · 齐白石（人物词条）", "claim": "齐白石，湖南湘潭人；15 岁学木工，善雕花，人称“芝木匠”；25 岁开始学书画、刻图章；60 岁后定居北京，以篆刻卖画为生；受陈师曾影响一弃旧习；工水墨虾、蟹、鱼、蛙等水族，工笔草虫；故宫作生年 1863", "url": "https://www.dpm.org.cn/lemmas/243103.html"}, {"label": "英文维基百科 · 齐白石", "claim": "Qi Baishi，1864 年 1 月 1 日 – 1957 年 9 月 16 日；湘潭农家；1917 年后定居北京；胡絜青（老舍夫人）是其弟子（故宫词条、Britannica 作 1863：生于清同治二年十一月二十二日，按公历已是 1864 年 1 月 1 日）", "url": "https://en.wikipedia.org/wiki/Qi_Baishi"}, {"label": "求是网 · 中国画的“似”与“不似”（2019）", "claim": "齐白石“妙在似与不似之间，太似为媚俗，不似为欺世”的见解，已成为近代中国画追求神似的一条美学原则（原始出处待考，墙上写作“常被引用的一句话”）", "url": "https://www.qstheory.cn/zhuanqu/bkjx/2019-02/22/c_1124150829.htm"}, {"label": "故宫博物院 · 任颐苏武牧羊图轴", "claim": "《苏武牧羊图》轴，清，任颐作，纸本设色，纵 149.5、横 81 cm；人物造型比例准确，融汇了西洋画速写、素描的技法；画上题“光绪庚辰嘉平吉日”（1880）", "url": "https://www.dpm.org.cn/collection/paint/234558.html"}, {"label": "维基共享资源 · 任颐苏武牧羊图轴", "claim": "作品图像文件，来源故宫名画记，公有领域", "url": "https://commons.wikimedia.org/wiki/File:%E4%BB%BB%E9%A2%90%E8%8B%8F%E6%AD%A6%E7%89%A7%E7%BE%8A%E5%9B%BE%E8%BD%B4.png"}, {"label": "故宫博物院 · 吴昌硕紫藤图轴", "claim": "《紫藤图》轴，清，吴昌硕绘，纸本设色，纵 132.5、横 41.2 cm；以书入画，自言“草书作葡萄，笔动走蛟龙”；款“乙巳八月八日”（1905）", "url": "https://www.dpm.org.cn/collection/paint/231304.html"}, {"label": "维基共享资源 · 吴昌硕紫藤图轴", "claim": "作品图像文件 3300 × 10653，来源故宫名画记，公有领域", "url": "https://commons.wikimedia.org/wiki/File:%E5%90%B4%E6%98%8C%E7%A1%95%E7%B4%AB%E8%97%A4%E5%9B%BE%E8%BD%B4.png"}, {"label": "故宫博物院 · 齐璜画藤轴", "claim": "近现代，齐璜作，纸本设色，纵 131.4、横 63.3 cm；款“壬戌冬十月”（1922）", "url": "https://www.dpm.org.cn/collection/paint/254897.html"}, {"label": "维基共享资源 · 齐璜画藤轴", "claim": "作品图像文件 7042 × 13914，来源故宫名画记，公有领域", "url": "https://commons.wikimedia.org/wiki/File:%E9%BD%90%E7%92%9C%E7%94%BB%E8%97%A4%E8%BD%B4.png"}, {"label": "上海博物馆 · 徐悲鸿 康有为像", "claim": "近现代，1926，油画，布，宽 84 cm、高 74 cm；徐悲鸿留法前在上海拜康有为为师，此画作于 1926 年自巴黎返沪探亲时", "url": "https://www.shanghaimuseum.net/mu/frontend/pg/article/id/CI00160835"}, {"label": "维基共享资源 · 徐悲鸿 康有为像", "claim": "作品图像文件 2098 × 1900，来源上海博物馆，公有领域", "url": "https://commons.wikimedia.org/wiki/File:%E5%BE%90%E6%82%B2%E9%B8%BF_%E5%BA%B7%E6%9C%89%E4%B8%BA%E5%83%8F.jpg"}, {"label": "Britannica · Xu Beihong", "claim": "1919 年靠官费赴法，此后八年在巴黎朱利安学院和国立高等美术学院受学院训练，练就素描与油画", "url": "https://www.britannica.com/biography/Xu-Beihong"}]};

